ints/class-wp-rest-terms-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-users-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-comments-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-search-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-blocks-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-block-renderer-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-settings-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-themes-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-comment-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-post-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-term-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-user-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/search/class-wp-rest-search-handler.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/search/class-wp-rest-post-search-handler.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-block-type.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-block-type-registry.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-block-parser.php\' );\nrequire( ABSPATH . WPINC . \'/blocks.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/archives.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/block.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/categories.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/latest-comments.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/latest-posts.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/shortcode.php\' );\n\n$GLOBALS[\'wp_embed\'] = new WP_Embed();\n\n// マルチサイト固有のファイルをロードします。\nif ( is_multisite() ) {\n	require( ABSPATH . WPINC . \'/ms-functions.php\' );\n	require( ABSPATH . WPINC . \'/ms-default-filters.php\' );\n	require( ABSPATH . WPINC . \'/ms-deprecated.php\' );\n}\n\n// デフォルト値を取得するためにAPIに依存する定数を定義します。\n// sunrise.phpドロップインで上書きされる可能性のある、必ず使用するプラグインディレクトリ定数を定義します。.\nwp_plugin_directory_constants();\n\n$GLOBALS[\'wp_plugin_paths\'] = array();\n\n// マストユーズプラグインをロードします\nforeach ( wp_get_mu_plugins() as $mu_plugin ) {\n	include_once( $mu_plugin );\n\n	/**\n	 * 一つのマストユーズプラグインがロードされたら起動する\n	 *\n	 * @since 5.1.0\n	 *\n	 * @param string $mu_plugin Full path to the plugin\'s main file.\n	 */\n	do_action( \'mu_plugin_loaded\', $mu_plugin );\n}\nunset( $mu_plugin );\n\n// ネットワーク起動プラグインをロードします\nif ( is_multisite() ) {\n	foreach ( wp_get_active_network_plugins() as $network_plugin ) {\n		wp_register_plugin_realpath( $network_plugin );\n		include_once( $network_plugin );\n\n		/**\n		 * 一つのネットワーク起動プラグインがロードされたら起動する\n		 *\n		 * @since 5.1.0\n		 *\n		 * @param string $network_plugin Full path to the plugin\'s main file.\n		 */\n		do_action( \'network_plugin_loaded\', $network_plugin );\n	}\n	unset( $network_plugin );\n}\n\n/**\n * すべての必須使用およびネットワーク起動プラグインがロードされると起動します。\n *\n * @since 2.8.0\n */\n\n//関数：muplugins_loadedを実行する\ndo_action( \'muplugins_loaded\' );\n\nif ( is_multisite() ) {\n	ms_cookie_constants();\n}\n\n// マルチサイトがロードされた後に定数を定義します。\nwp_cookie_constants();\n\n// SSL定数を定義して実施する\nwp_ssl_constants();\n\n// 共通グローバルを作成する\nrequire( ABSPATH . WPINC . \'/vars.php\' );\n\n// タクソノミーや投稿をプラグインやテーマで利用できるようにします。\n// @プラグインの作成者：警告：これらはinitフックに再度登録されます。\ncreate_initial_taxonomies();\ncreate_initial_post_types();\n\nwp_start_scraping_edited_file_errors();\n\n// デフォルトのテーマディレクトリのルートを登録する\nregister_theme_directory( get_theme_root() );\n\n// 有効化されてるプラグインをよみこむ\nforeach ( wp_get_active_and_valid_plugins() as $plugin ) {\n	wp_register_plugin_realpath( $plugin );\n	include_once( $plugin );\n\n	/**\n	 * 一度有効化されたプラグインをよみこむと起動する\n	 *\n	 * @since 5.1.0\n	 *\n	 * @param string $plugin Full path to the plugin\'s main file.\n	 */\n	do_action( \'plugin_loaded\', $plugin );\n}\nunset( $plugin );\n\n// プラガブル関数を読み込む.\nrequire( ABSPATH . WPINC . \'/pluggable.php\' );\nrequire( ABSPATH . WPINC . \'/pluggable-deprecated.php\' );\n\n// 内部エンコーディングを設定します。\nwp_set_internal_encoding();\n\n// オブジェクトキャッシュが有効で、関数が存在する場合は、wp_cache_postload（）を実行する\nif ( WP_CACHE && function_exists( \'wp_cache_postload\' ) ) {\n	wp_cache_postload();\n}\n\n/**\n * 一度有効化されたプラグインをよみこむと起動する\n *\n * 読み込まれているこの時点でプラガブル機能も利用可能です。\n *\n * @since 1.5.0\n */\ndo_action( \'plugins_loaded\' );\n\n// まだ定義されていない場合、機能に影響を与える定数を定義します。\nwp_functionality_constants();\n\n// マジッククオートを追加して$ _REQUEST（$ _GET + $ _POST）を設定する\nwp_magic_quotes();\n\n/**\n * コメントクッキーがサニタイズされたときに起動します。\n *\n * @since 2.0.11\n */\ndo_action( \'sanitize_comment_cookies\' );\n\n/**\n * WordPress Query object\n *\n * @global WP_Query $wp_the_query\n * @since 2.0.0\n */\n$GLOBALS[\'wp_the_query\'] = new WP_Query();\n\n/**\n * $ wp_the_queryへの参照を保持しています\n * WordPressクエリにこのグローバルを使用\n *\n * @global WP_Query $wp_query\n * @since 1.5.0\n */\n$GLOBALS[\'wp_query\'] = $GLOBALS[\'wp_the_query\'];\n\n/**\n * きれいなURLを作成するためのWordPressリライトオブジェクトを保持します。\n * @global WP_Rewrite $wp_rewrite\n * @since 1.5.0\n */\n$GLOBALS[\'wp_rewrite\'] = new WP_Rewrite();\n\n/**\n * WordPress オブジェクト\n *\n * @global WP $wp\n * @since 2.0.0\n */\n$GLOBALS[\'wp\'] = new WP();\n\n/**\n * WordPress Widget Factory Object\n *\n * @global WP_Widget_Factory $wp_widget_factory\n * @since 2.8.0\n */\n$GLOBALS[\'wp_widget_factory\'] = new WP_Widget_Factory();\n\n/**\n * WordPress User Roles\n *\n * @global WP_Roles $wp_roles\n * @since 2.0.0\n */\n$GLOBALS[\'wp_roles\'] = new WP_Roles();\n\n/**\n * テーマが読み込まれる前に発生します。\n *\n * @since 2.6.0\n */\ndo_action( \'setup_theme\' );\n\n// テンプレート関連定数を定義します。\nwp_templating_constants();\n\n// デフォルトのテキストローカライゼーションドメインを読み込む。\nload_default_textdomain();\n\n$locale      = get_locale();\n$locale_file = WP_LANG_DIR . \"/$locale.php\";\nif ( ( 0 === validate_file( $locale ) ) && is_readable( $locale_file ) ) {\n	require( $locale_file );\n}\nunset( $locale_file );\n\n/**\n * ロケールドメインの日付とさまざまな文字列をロードするためのWordPress Localeオブジェクト。\n *\n * @global WP_Locale $wp_locale\n * @since 2.1.0\n */\n$GLOBALS[\'wp_locale\'] = new WP_Locale();\n\n/**\n *  ロケールを切り替えるためのWordPress Locale Switcherオブジェクト\n *\n * @since 4.7.0\n *\n * @global WP_Locale_Switcher $ wp_locale_switcher WordPressロケール切り替えオブジェクト。\n */\n$GLOBALS[\'wp_locale_switcher\'] = new WP_Locale_Switcher();\n$GLOBALS[\'wp_locale_switcher\']--->init();\n\n// 該当する場合は、親テーマと子テーマの両方について、アクティブなテーマの機能をロードします。\nforeach ( wp_get_active_and_valid_themes() as $theme ) {\n	if ( file_exists( $theme . \'/functions.php\' ) ) {\n		include $theme . \'/functions.php\';\n	}\n}\nunset( $theme );\n\n/**\n * テーマが読まれた後に起動する\n *\n * @since 3.0.0\n */\ndo_action( \'after_setup_theme\' );\n\n// 現在のユーザーを設定します。\n$GLOBALS[\'wp\']-&gt;init();\n\n/**\n * WordPressの読み込みが完了した後、ヘッダーが送信される前に起動ます。\n *\n * WPの大部分はこの段階でロードされ、ユーザーは認証されます。\n * WPは{@see \'init\'}フック（例えばウィジェット）に読み込みそれに続いて読み込まれます、多くのプラグインがインスタンス化します\n * WP自身はあらゆる種類の理由で分類します。（例えば、ユーザー、タクソノミーなど）\n *\n * WPがロードされた後にアクションをプラグインしたい場合は、以下の{@see \'wp_loaded\'}フックを使用してください。\n *\n * @since 1.5.0\n */\ndo_action( \'init\' );\n\n// マルチサイトの場合\nif ( is_multisite() ) {\n	if ( true !== ( $file = ms_site_check() ) ) {\n		require( $file );\n		die();\n	}\n	unset( $file );\n}\n\n/**\n * このフックは、WP、すべてのプラグイン、およびテーマが完全に読み込まれてインスタンス化されると起動します。\n *\n * Ajaxリクエストはwp-admin / admin-ajax.phpを使うべきです。\n * ajax.phpは、ログインしていないユーザーに対するリクエストを処理できます。\n * @link https://codex.wordpress.org/AJAX_in_Plugins\n *\n * @since 3.0.0\n */\ndo_action( \'wp_loaded\' );\n\n</pre>\n\n<!-- wp:heading {\"level\":3} -->\n<h3></h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2> まとめ：このファイルで行ってること </h2>\n<!-- /wp:heading -->\n\n<p>・</p>\n\n<!-- wp:heading -->\n<h2> おまけ：このファイルで使われた関数 </h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3> php関数 </h3>\n<!-- /wp:heading -->\n\n<p>date_default_timezone_set( \'UTC\' );</p>\n<p></p>\n<p>register_shutdown_function( \'関数名\' );</p>\n<p>シャットダウン時に実行する関数を登録します</p>\n<p></p>\n<h4>$GLOBALS[\' 変数名 \']</h4>\n<p>phpの定義済み変数のうち、$GLOBALS（グローバル変数）は</p>\n<p>できる変数です。</p>\n<p></p>\n<p>ex)</p>\n<p>この関数に関しては詳しくは以下のページにて↓</p>\n<p></p>\n<p></p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3> wp関数 </h3>\n<!-- /wp:heading -->\n\n<p>いろいろありましたが、大事そうなやつだけピックアップ。</p>\n<p></p>\n<p>wp_initial_constants();</p>\n<p>wp_unregister_GLOBALS();</p>\n<p>wp_favicon_request();</p>\n<p>wp_maintenance();</p>\n<p>timer_start();</p>\n<p>wp_debug_mode();</p>\n<p></p>\n<p>apply_filters();</p>\n<p></p>\n<p>wp_not_installed();</p>\n<p>wp_plugin_directory_constants();</p>\n<p>wp_set_internal_encoding();</p>\n<p>wp_functionality_constants();</p>','wp-setting.phpを解読してみた','','private','closed','closed','','source-reading-wp-setting-php','','','2019-06-03 09:35:28','2019-06-03 00:35:28','',0,'http://localhost:8080/?post_type=web_and_aplication&#038;p=1816',0,'web_and_aplication','',0),(1917,1,'2019-05-10 15:46:17','2019-05-10 06:46:17',' ','','','publish','closed','closed','','1917','','','2019-05-10 15:46:17','2019-05-10 06:46:17','',0,'http://localhost:8080/anothor/1917',4,'nav_menu_item','',0),(1921,1,'2019-05-10 18:53:09','2019-05-10 09:53:09','<!-- wp:heading -->\n<h2> wordpressにおけるwp-setting.phpとは </h2>\n<!-- /wp:heading -->\n\n<p>wp-setting.phpはwordpressのコアファイルを読み込んでいく際に、3番目に読まれるファイルになります。</p>\n<p>wp-load.php</p>\n<p>↓</p>\n<p>wp-config.php</p>\n<p>↓</p>\n<p>wp-setting.php</p>\n<p>↓</p>\n<p>wordpressのコアファイル</p>\n<p></p>\n\n<!-- wp:heading -->\n<h2> 実際に翻訳してみた </h2>\n<!-- /wp:heading -->\n\n<p> </p>\n<p> </p>\n<p>&lt;?php<br />/**<br />* 一般的な変数を設定および修正するために使用され、<br />* WordPressの手続き型およびクラスライブラリを含みます。<br />*<br />* wp-config.phpでの設定を許可します（default-constants.phpを参照）<br />*<br />* @package WordPress<br />*/</p>\n<p>/**<br />* WordPressの関数、クラス、およびコアコンテンツのディレクトリの場所を格納します。<br />*<br />* @since 1.0.0<br />*/</p>\n<p>//「WPINC」をwp-includesディレクトリと定義する<br />define( \'WPINC\', \'wp-includes\' );</p>\n<p>// 初期化に必要なファイルを含めます。<br />//ドキュメントルート/wp-includes/load.phpを読み込む<br />require( ABSPATH . WPINC . \'/load.php\' );<br />//ドキュメントルート/wp-includes/default-constants.phpを読み込む<br />require( ABSPATH . WPINC . \'/default-constants.php\' );<br />//ドキュメントルート/wp-includes/plugin.phpを一回読み込む<br />require_once( ABSPATH . WPINC . \'/plugin.php\' );</p>\n<p>/*<br />* これらはversion.phpで直接グローバル化することはできません。 更新するとき、<br />* 私たちは他のインストールからのversion.phpをインクルードしています。<br />* そしてすでに設定されているならこれらの値を上書きされたくないです。<br />*/</p>\n<p>//以下の変数をグローバル宣言する<br />global $wp_version, $wp_db_version, $tinymce_version, $required_php_version, $required_mysql_version, $wp_local_package;<br />//ドキュメントルート/wp-includes/version.phpを読み込む<br />require( ABSPATH . WPINC . \'/version.php\' );</p>\n<p>/**<br />* まだ設定されていない場合 blog_idは単一サイト設定でデフォルトの1になります。<br />* マルチサイトでは、ms-settings.phpでデフォルトで上書きされます。<br />*<br />* @global int $blog_id<br />* @since 2.0.0<br />*/<br />//<br />global $blog_id;</p>\n<p>// WP_MEMORY_LIMIT、WP_MAX_MEMORY_LIMIT、WP_DEBUG、SCRIPT_DEBUG、WP_CONTENT_DIRおよびWP_CACHEを含む初期デフォルト定数を設定します。<br />wp_initial_constants();</p>\n<p>// 必要なPHPバージョンとMySQLエクステンションまたはデータベースドロップインをチェックしてください。<br />wp_check_php_mysql_versions();</p>\n<p>// 実行時にマジッククォートを無効にします。魔法の引用符は後でwp-settings.phpでwpdbを使って追加されます<br />@ini_set( \'magic_quotes_runtime\', 0 );<br />@ini_set( \'magic_quotes_sybase\', 0 );</p>\n<p>// WordPressはUTCからのオフセットを計算します。<br />date_default_timezone_set( \'UTC\' );</p>\n<p>// register_globalsをオフにします。<br />wp_unregister_GLOBALS();</p>\n<p>// 設定間で$ _SERVER変数を標準化します。<br />wp_fix_server_vars();</p>\n<p>// favicon.icoが見つからないため、リクエストを受信したかどうかを確認します<br />wp_favicon_request();</p>\n<p>// メンテナンスモードになっているか確認してください。<br />wp_maintenance();</p>\n<p>// タイマーをロードします。<br />timer_start();</p>\n<p>// WP_DEBUGモードになっているか確認してください。<br />wp_debug_mode();</p>\n<p>/**<br />* advanced-cache.phpドロップインのロードを有効にするかどうかをフィルタリングします。<br />*<br />* このフィルタはプラグインによって使用される前に実行されます。 Web以外のランタイム用に設計されています。<br />* falseが返された場合、advanced-cache.phpはロードされません。<br />*<br />* @since 4.6.0<br />*<br />* @param bool $enable_advanced_cache_advanced-cache.php（存在する場合）の読み込みを有効にするかどうか<br />* Default true.<br />*/</p>\n<p>if ( WP_CACHE &amp;&amp; apply_filters( \'enable_loading_advanced_cache_dropin\', true ) ) {<br />// 高度なキャッシングプラグインを使うために。必要なのは静的ドロップインだけです。<br />WP_DEBUG ? include( WP_CONTENT_DIR . \'/advanced-cache.php\' ) : @include( WP_CONTENT_DIR . \'/advanced-cache.php\' );</p>\n<p>// advanced-cache.phpによって手動で追加されたフックを再初期化します<br />if ( $wp_filter ) {<br />$wp_filter = WP_Hook::build_preinitialized_hooks( $wp_filter );<br />}<br />}</p>\n<p>// 設定されていない場合はWP_LANG_DIRを定義します。<br />wp_set_lang_dir();</p>\n<p>// 初期のWordPressファイルを読み込む.<br />require( ABSPATH . WPINC . \'/compat.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-list-util.php\' );<br />require( ABSPATH . WPINC . \'/formatting.php\' );<br />require( ABSPATH . WPINC . \'/meta.php\' );<br />require( ABSPATH . WPINC . \'/functions.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-meta-query.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-matchesmapregex.php\' );<br />require( ABSPATH . WPINC . \'/class-wp.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-error.php\' );<br />require( ABSPATH . WPINC . \'/pomo/mo.php\' );</p>\n<p>// wpdbクラスと、存在する場合はdb.phpデータベースドロップインを含めます。<br />global $wpdb;<br />require_wp_db();</p>\n<p>// データベーステーブルのプレフィックスとデータベーステーブル列のフォーマット指定子を設定します。<br />$GLOBALS[\'table_prefix\'] = $table_prefix;<br />wp_set_wpdb_vars();</p>\n<p>// WordPressオブジェクトキャッシュ、またはドロップインが存在する場合は外部オブジェクトキャッシュを起動します。<br />wp_start_object_cache();</p>\n<p>// Attach the default filters.<br />require( ABSPATH . WPINC . \'/default-filters.php\' );</p>\n<p>// 有効な場合はマルチサイトを初期化します。<br />if ( is_multisite() ) {<br />require( ABSPATH . WPINC . \'/class-wp-site-query.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-network-query.php\' );<br />require( ABSPATH . WPINC . \'/ms-blogs.php\' );<br />require( ABSPATH . WPINC . \'/ms-settings.php\' );<br />} elseif ( ! defined( \'MULTISITE\' ) ) {<br />define( \'MULTISITE\', false );<br />}</p>\n<p>register_shutdown_function( \'shutdown_action_hook\' );</p>\n<p>// 基本的な機能を使いたいだけなら、大半のWordPressをロードしないようにしてください。<br />if ( SHORTINIT ) {<br />return false;<br />}</p>\n<p>// L10nライブラリをロードする<br />require_once( ABSPATH . WPINC . \'/l10n.php\' );<br />require_once( ABSPATH . WPINC . \'/class-wp-locale.php\' );<br />require_once( ABSPATH . WPINC . \'/class-wp-locale-switcher.php\' );</p>\n<p>// WordPressがインストールされていない場合はインストーラを実行してください<br />wp_not_installed();</p>\n<p>// WordPressの大半をロードする<br />require( ABSPATH . WPINC . \'/class-wp-walker.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-ajax-response.php\' );<br />require( ABSPATH . WPINC . \'/capabilities.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-roles.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-role.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-user.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-query.php\' );<br />require( ABSPATH . WPINC . \'/query.php\' );<br />require( ABSPATH . WPINC . \'/date.php\' );<br />require( ABSPATH . WPINC . \'/theme.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-theme.php\' );<br />require( ABSPATH . WPINC . \'/template.php\' );<br />require( ABSPATH . WPINC . \'/user.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-user-query.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-session-tokens.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-user-meta-session-tokens.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-metadata-lazyloader.php\' );<br />require( ABSPATH . WPINC . \'/general-template.php\' );<br />require( ABSPATH . WPINC . \'/link-template.php\' );<br />require( ABSPATH . WPINC . \'/author-template.php\' );<br />require( ABSPATH . WPINC . \'/post.php\' );<br />require( ABSPATH . WPINC . \'/class-walker-page.php\' );<br />require( ABSPATH . WPINC . \'/class-walker-page-dropdown.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-post-type.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-post.php\' );<br />require( ABSPATH . WPINC . \'/post-template.php\' );<br />require( ABSPATH . WPINC . \'/revision.php\' );<br />require( ABSPATH . WPINC . \'/post-formats.php\' );<br />require( ABSPATH . WPINC . \'/post-thumbnail-template.php\' );<br />require( ABSPATH . WPINC . \'/category.php\' );<br />require( ABSPATH . WPINC . \'/class-walker-category.php\' );<br />require( ABSPATH . WPINC . \'/class-walker-category-dropdown.php\' );<br />require( ABSPATH . WPINC . \'/category-template.php\' );<br />require( ABSPATH . WPINC . \'/comment.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-comment.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-comment-query.php\' );<br />require( ABSPATH . WPINC . \'/class-walker-comment.php\' );<br />require( ABSPATH . WPINC . \'/comment-template.php\' );<br />require( ABSPATH . WPINC . \'/rewrite.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-rewrite.php\' );<br />require( ABSPATH . WPINC . \'/feed.php\' );<br />require( ABSPATH . WPINC . \'/bookmark.php\' );<br />require( ABSPATH . WPINC . \'/bookmark-template.php\' );<br />require( ABSPATH . WPINC . \'/kses.php\' );<br />require( ABSPATH . WPINC . \'/cron.php\' );<br />require( ABSPATH . WPINC . \'/deprecated.php\' );<br />require( ABSPATH . WPINC . \'/script-loader.php\' );<br />require( ABSPATH . WPINC . \'/taxonomy.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-taxonomy.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-term.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-term-query.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-tax-query.php\' );<br />require( ABSPATH . WPINC . \'/update.php\' );<br />require( ABSPATH . WPINC . \'/canonical.php\' );<br />require( ABSPATH . WPINC . \'/shortcodes.php\' );<br />require( ABSPATH . WPINC . \'/embed.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-embed.php\' );<br />require( ABSPATH . WPINC . \'/class-oembed.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-oembed-controller.php\' );<br />require( ABSPATH . WPINC . \'/media.php\' );<br />require( ABSPATH . WPINC . \'/http.php\' );<br />require( ABSPATH . WPINC . \'/class-http.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-http-streams.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-http-curl.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-http-proxy.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-http-cookie.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-http-encoding.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-http-response.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-http-requests-response.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-http-requests-hooks.php\' );<br />require( ABSPATH . WPINC . \'/widgets.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-widget.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-widget-factory.php\' );<br />require( ABSPATH . WPINC . \'/nav-menu.php\' );<br />require( ABSPATH . WPINC . \'/nav-menu-template.php\' );<br />require( ABSPATH . WPINC . \'/admin-bar.php\' );<br />require( ABSPATH . WPINC . \'/rest-api.php\' );<br />require( ABSPATH . WPINC . \'/rest-api/class-wp-rest-server.php\' );<br />require( ABSPATH . WPINC . \'/rest-api/class-wp-rest-response.php\' );<br />require( ABSPATH . WPINC . \'/rest-api/class-wp-rest-request.php\' );<br />require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-controller.php\' );<br />require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-posts-controller.php\' );<br />require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-attachments-controller.php\' );<br />require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-post-types-controller.php\' );<br />require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-post-statuses-controller.php\' );<br />require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-revisions-controller.php\' );<br />require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-autosaves-controller.php\' );<br />require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-taxonomies-controller.php\' );<br />require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-terms-controller.php\' );<br />require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-users-controller.php\' );<br />require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-comments-controller.php\' );<br />require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-search-controller.php\' );<br />require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-blocks-controller.php\' );<br />require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-block-renderer-controller.php\' );<br />require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-settings-controller.php\' );<br />require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-themes-controller.php\' );<br />require( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-meta-fields.php\' );<br />require( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-comment-meta-fields.php\' );<br />require( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-post-meta-fields.php\' );<br />require( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-term-meta-fields.php\' );<br />require( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-user-meta-fields.php\' );<br />require( ABSPATH . WPINC . \'/rest-api/search/class-wp-rest-search-handler.php\' );<br />require( ABSPATH . WPINC . \'/rest-api/search/class-wp-rest-post-search-handler.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-block-type.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-block-type-registry.php\' );<br />require( ABSPATH . WPINC . \'/class-wp-block-parser.php\' );<br />require( ABSPATH . WPINC . \'/blocks.php\' );<br />require( ABSPATH . WPINC . \'/blocks/archives.php\' );<br />require( ABSPATH . WPINC . \'/blocks/block.php\' );<br />require( ABSPATH . WPINC . \'/blocks/categories.php\' );<br />require( ABSPATH . WPINC . \'/blocks/latest-comments.php\' );<br />require( ABSPATH . WPINC . \'/blocks/latest-posts.php\' );<br />require( ABSPATH . WPINC . \'/blocks/shortcode.php\' );</p>\n<p>$GLOBALS[\'wp_embed\'] = new WP_Embed();</p>\n<p>// マルチサイト固有のファイルをロードします。<br />if ( is_multisite() ) {<br />require( ABSPATH . WPINC . \'/ms-functions.php\' );<br />require( ABSPATH . WPINC . \'/ms-default-filters.php\' );<br />require( ABSPATH . WPINC . \'/ms-deprecated.php\' );<br />}</p>\n<p>// デフォルト値を取得するためにAPIに依存する定数を定義します。<br />// sunrise.phpドロップインで上書きされる可能性のある、必ず使用するプラグインディレクトリ定数を定義します。.<br />wp_plugin_directory_constants();</p>\n<p>$GLOBALS[\'wp_plugin_paths\'] = array();</p>\n<p>// マストユーズプラグインをロードします<br />foreach ( wp_get_mu_plugins() as $mu_plugin ) {<br />include_once( $mu_plugin );</p>\n<p>/**<br />* 一つのマストユーズプラグインがロードされたら起動する<br />*<br />* @since 5.1.0<br />*<br />* @param string $mu_plugin Full path to the plugin\'s main file.<br />*/<br />do_action( \'mu_plugin_loaded\', $mu_plugin );<br />}<br />unset( $mu_plugin );</p>\n<p>// ネットワーク起動プラグインをロードします<br />if ( is_multisite() ) {<br />foreach ( wp_get_active_network_plugins() as $network_plugin ) {<br />wp_register_plugin_realpath( $network_plugin );<br />include_once( $network_plugin );</p>\n<p>/**<br />* 一つのネットワーク起動プラグインがロードされたら起動する<br />*<br />* @since 5.1.0<br />*<br />* @param string $network_plugin Full path to the plugin\'s main file.<br />*/<br />do_action( \'network_plugin_loaded\', $network_plugin );<br />}<br />unset( $network_plugin );<br />}</p>\n<p>/**<br />* Fires once all must-use and network-activated plugins have loaded.<br />*<br />* @since 2.8.0<br />*/<br />do_action( \'muplugins_loaded\' );</p>\n<p>if ( is_multisite() ) {<br />ms_cookie_constants();<br />}</p>\n<p>// Define constants after multisite is loaded.<br />wp_cookie_constants();</p>\n<p>// Define and enforce our SSL constants<br />wp_ssl_constants();</p>\n<p>// Create common globals.<br />require( ABSPATH . WPINC . \'/vars.php\' );</p>\n<p>// Make taxonomies and posts available to plugins and themes.<br />// @plugin authors: warning: these get registered again on the init hook.<br />create_initial_taxonomies();<br />create_initial_post_types();</p>\n<p>wp_start_scraping_edited_file_errors();</p>\n<p>// Register the default theme directory root<br />register_theme_directory( get_theme_root() );</p>\n<p>// Load active plugins.<br />foreach ( wp_get_active_and_valid_plugins() as $plugin ) {<br />wp_register_plugin_realpath( $plugin );<br />include_once( $plugin );</p>\n<p>/**<br />* Fires once a single activated plugin has loaded.<br />*<br />* @since 5.1.0<br />*<br />* @param string $plugin Full path to the plugin\'s main file.<br />*/<br />do_action( \'plugin_loaded\', $plugin );<br />}<br />unset( $plugin );</p>\n<p>// Load pluggable functions.<br />require( ABSPATH . WPINC . \'/pluggable.php\' );<br />require( ABSPATH . WPINC . \'/pluggable-deprecated.php\' );</p>\n<p>// Set internal encoding.<br />wp_set_internal_encoding();</p>\n<p>// Run wp_cache_postload() if object cache is enabled and the function exists.<br />if ( WP_CACHE &amp;&amp; function_exists( \'wp_cache_postload\' ) ) {<br />wp_cache_postload();<br />}</p>\n<p>/**<br />* Fires once activated plugins have loaded.<br />*<br />* Pluggable functions are also available at this point in the loading order.<br />*<br />* @since 1.5.0<br />*/<br />do_action( \'plugins_loaded\' );</p>\n<p>// Define constants which affect functionality if not already defined.<br />wp_functionality_constants();</p>\n<p>// Add magic quotes and set up $_REQUEST ( $_GET + $_POST )<br />wp_magic_quotes();</p>\n<p>/**<br />* Fires when comment cookies are sanitized.<br />*<br />* @since 2.0.11<br />*/<br />do_action( \'sanitize_comment_cookies\' );</p>\n<p>/**<br />* WordPress Query object<br />*<br />* @global WP_Query $wp_the_query<br />* @since 2.0.0<br />*/<br />$GLOBALS[\'wp_the_query\'] = new WP_Query();</p>\n<p>/**<br />* Holds the reference to @see $wp_the_query<br />* Use this global for WordPress queries<br />*<br />* @global WP_Query $wp_query<br />* @since 1.5.0<br />*/<br />$GLOBALS[\'wp_query\'] = $GLOBALS[\'wp_the_query\'];</p>\n<p>/**<br />* Holds the WordPress Rewrite object for creating pretty URLs<br />*<br />* @global WP_Rewrite $wp_rewrite<br />* @since 1.5.0<br />*/<br />$GLOBALS[\'wp_rewrite\'] = new WP_Rewrite();</p>\n<p>/**<br />* WordPress Object<br />*<br />* @global WP $wp<br />* @since 2.0.0<br />*/<br />$GLOBALS[\'wp\'] = new WP();</p>\n<p>/**<br />* WordPress Widget Factory Object<br />*<br />* @global WP_Widget_Factory $wp_widget_factory<br />* @since 2.8.0<br />*/<br />$GLOBALS[\'wp_widget_factory\'] = new WP_Widget_Factory();</p>\n<p>/**<br />* WordPress User Roles<br />*<br />* @global WP_Roles $wp_roles<br />* @since 2.0.0<br />*/<br />$GLOBALS[\'wp_roles\'] = new WP_Roles();</p>\n<p>/**<br />* Fires before the theme is loaded.<br />*<br />* @since 2.6.0<br />*/<br />do_action( \'setup_theme\' );</p>\n<p>// Define the template related constants.<br />wp_templating_constants();</p>\n<p>// Load the default text localization domain.<br />load_default_textdomain();</p>\n<p>$locale = get_locale();<br />$locale_file = WP_LANG_DIR . \"/$locale.php\";<br />if ( ( 0 === validate_file( $locale ) ) &amp;&amp; is_readable( $locale_file ) ) {<br />require( $locale_file );<br />}<br />unset( $locale_file );</p>\n<p>/**<br />* WordPress Locale object for loading locale domain date and various strings.<br />*<br />* @global WP_Locale $wp_locale<br />* @since 2.1.0<br />*/<br />$GLOBALS[\'wp_locale\'] = new WP_Locale();</p>\n<p>/**<br />* WordPress Locale Switcher object for switching locales.<br />*<br />* @since 4.7.0<br />*<br />* @global WP_Locale_Switcher $wp_locale_switcher WordPress locale switcher object.<br />*/<br />$GLOBALS[\'wp_locale_switcher\'] = new WP_Locale_Switcher();<br />$GLOBALS[\'wp_locale_switcher\']-&gt;init();</p>\n<p>// Load the functions for the active theme, for both parent and child theme if applicable.<br />foreach ( wp_get_active_and_valid_themes() as $theme ) {<br />if ( file_exists( $theme . \'/functions.php\' ) ) {<br />include $theme . \'/functions.php\';<br />}<br />}<br />unset( $theme );</p>\n<p>/**<br />* Fires after the theme is loaded.<br />*<br />* @since 3.0.0<br />*/<br />do_action( \'after_setup_theme\' );</p>\n<p>// Set up current user.<br />$GLOBALS[\'wp\']-&gt;init();</p>\n<p>/**<br />* Fires after WordPress has finished loading but before any headers are sent.<br />*<br />* Most of WP is loaded at this stage, and the user is authenticated. WP continues<br />* to load on the {@see \'init\'} hook that follows (e.g. widgets), and many plugins instantiate<br />* themselves on it for all sorts of reasons (e.g. they need a user, a taxonomy, etc.).<br />*<br />* If you wish to plug an action once WP is loaded, use the {@see \'wp_loaded\'} hook below.<br />*<br />* @since 1.5.0<br />*/<br />do_action( \'init\' );</p>\n<p>// Check site status<br />if ( is_multisite() ) {<br />if ( true !== ( $file = ms_site_check() ) ) {<br />require( $file );<br />die();<br />}<br />unset( $file );<br />}</p>\n<p>/**<br />* This hook is fired once WP, all plugins, and the theme are fully loaded and instantiated.<br />*<br />* Ajax requests should use wp-admin/admin-ajax.php. admin-ajax.php can handle requests for<br />* users not logged in.<br />*<br />* @link https://codex.wordpress.org/AJAX_in_Plugins<br />*<br />* @since 3.0.0<br />*/<br />do_action( \'wp_loaded\' );</p>\n<p> </p>\n<p> </p>\n<p> </p>\n\n<!-- wp:heading -->\n<h2> まとめ：このファイルで行ってること </h2>\n<!-- /wp:heading -->\n\n<p>・</p>\n\n<!-- wp:heading -->\n<h2> おまけ：このファイルで使われた関数 </h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3> php関数 </h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3> wp関数 </h3>\n<!-- /wp:heading -->','wp-setting.phpを解読してみた','','inherit','closed','closed','','1816-revision-v1','','','2019-05-10 18:53:09','2019-05-10 09:53:09','',1816,'http://localhost:8080/anothor/1816-revision-v1',0,'revision','',0),(1923,1,'2019-05-13 09:59:38','2019-05-13 00:59:38','<!-- wp:heading -->\n<h2> wordpressにおけるwp-setting.phpとは </h2>\n<!-- /wp:heading -->\n\n<p>wp-setting.phpはwordpressのコアファイルを読み込んでいく際のおよそ3番目に読まれるファイルになります。</p>\n<p>wp-load.php</p>\n<p>↓</p>\n<p>wp-config.php</p>\n<p>↓</p>\n<p><strong><span style=\"color: #ff0000;\">wp-setting.php</span></strong></p>\n<p>↓</p>\n<p>wordpressのコアファイル群</p>\n<p> </p>\n<p>wp-setting.phpで行っていることはざっくりいうと、wordpressを起動させる際の設定をし、コアファイルたちを次々実行していき実質的にwordpressを起動させるファイルになります。</p>\n<p> </p>\n<p> </p>\n\n<!-- wp:heading -->\n<h2> 実際に翻訳してみた </h2>\n<!-- /wp:heading -->\n\n<p></p>\n<p></p>\n<p>&lt;?php<br>/**<br>* 一般的な変数を設定および修正するために使用され、<br>* WordPressの手続き型およびクラスライブラリを含みます。<br>*<br>* wp-config.phpでの設定を許可します（default-constants.phpを参照）<br>*<br>* @package WordPress<br>*/</p>\n<p>/**<br>* WordPressの関数、クラス、およびコアコンテンツのディレクトリの場所を格納します。<br>*<br>* @since 1.0.0<br>*/</p>\n<p>//「WPINC」をwp-includesディレクトリと定義する<br>define( \'WPINC\', \'wp-includes\' );</p>\n<p>// 初期化に必要なファイルを含めます。<br>//ドキュメントルート/wp-includes/load.phpを読み込む<br>require( ABSPATH . WPINC . \'/load.php\' );<br>//ドキュメントルート/wp-includes/default-constants.phpを読み込む<br>require( ABSPATH . WPINC . \'/default-constants.php\' );<br>//ドキュメントルート/wp-includes/plugin.phpを一回読み込む<br>require_once( ABSPATH . WPINC . \'/plugin.php\' );</p>\n<p>/*<br>* これらはversion.phpで直接グローバル化することはできません。 更新するとき、<br>* 私たちは他のインストールからのversion.phpをインクルードしています。<br>* そしてすでに設定されているならこれらの値を上書きされたくないです。<br>*/</p>\n<p>//以下の変数をグローバル宣言する<br>global $wp_version, $wp_db_version, $tinymce_version, $required_php_version, $required_mysql_version, $wp_local_package;<br>//ドキュメントルート/wp-includes/version.phpを読み込む<br>require( ABSPATH . WPINC . \'/version.php\' );</p>\n<p>/**<br>* まだ設定されていない場合 blog_idは単一サイト設定でデフォルトの1になります。<br>* マルチサイトでは、ms-settings.phpでデフォルトで上書きされます。<br>*<br>* @global int $blog_id<br>* @since 2.0.0<br>*/<br>//<br>global $blog_id;</p>\n<p>// WP_MEMORY_LIMIT、WP_MAX_MEMORY_LIMIT、WP_DEBUG、SCRIPT_DEBUG、WP_CONTENT_DIRおよびWP_CACHEを含む初期デフォルト定数を設定します。<br>wp_initial_constants();</p>\n<p>// 必要なPHPバージョンとMySQLエクステンションまたはデータベースドロップインをチェックしてください。<br>wp_check_php_mysql_versions();</p>\n<p>// 実行時にマジッククォートを無効にします。魔法の引用符は後でwp-settings.phpでwpdbを使って追加されます<br>@ini_set( \'magic_quotes_runtime\', 0 );<br>@ini_set( \'magic_quotes_sybase\', 0 );</p>\n<p>// WordPressはUTCからのオフセットを計算します。<br>date_default_timezone_set( \'UTC\' );</p>\n<p>// register_globalsをオフにします。<br>wp_unregister_GLOBALS();</p>\n<p>// 設定間で$ _SERVER変数を標準化します。<br>wp_fix_server_vars();</p>\n<p>// favicon.icoが見つからないため、リクエストを受信したかどうかを確認します<br>wp_favicon_request();</p>\n<p>// メンテナンスモードになっているか確認してください。<br>wp_maintenance();</p>\n<p>// タイマーをロードします。<br>timer_start();</p>\n<p>// WP_DEBUGモードになっているか確認してください。<br>wp_debug_mode();</p>\n<p>/**<br>* advanced-cache.phpドロップインのロードを有効にするかどうかをフィルタリングします。<br>*<br>* このフィルタはプラグインによって使用される前に実行されます。 Web以外のランタイム用に設計されています。<br>* falseが返された場合、advanced-cache.phpはロードされません。<br>*<br>* @since 4.6.0<br>*<br>* @param bool $enable_advanced_cache_advanced-cache.php（存在する場合）の読み込みを有効にするかどうか<br>* Default true.<br>*/</p>\n<p>if ( WP_CACHE &amp;&amp; apply_filters( \'enable_loading_advanced_cache_dropin\', true ) ) {<br>// 高度なキャッシングプラグインを使うために。必要なのは静的ドロップインだけです。<br>WP_DEBUG ? include( WP_CONTENT_DIR . \'/advanced-cache.php\' ) : @include( WP_CONTENT_DIR . \'/advanced-cache.php\' );</p>\n<p>// advanced-cache.phpによって手動で追加されたフックを再初期化します<br>if ( $wp_filter ) {<br>$wp_filter = WP_Hook::build_preinitialized_hooks( $wp_filter );<br>}<br>}</p>\n<p>// 設定されていない場合はWP_LANG_DIRを定義します。<br>wp_set_lang_dir();</p>\n<p>// 初期のWordPressファイルを読み込む.<br>require( ABSPATH . WPINC . \'/compat.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-list-util.php\' );<br>require( ABSPATH . WPINC . \'/formatting.php\' );<br>require( ABSPATH . WPINC . \'/meta.php\' );<br>require( ABSPATH . WPINC . \'/functions.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-meta-query.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-matchesmapregex.php\' );<br>require( ABSPATH . WPINC . \'/class-wp.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-error.php\' );<br>require( ABSPATH . WPINC . \'/pomo/mo.php\' );</p>\n<p>// wpdbクラスと、存在する場合はdb.phpデータベースドロップインを含めます。<br>global $wpdb;<br>require_wp_db();</p>\n<p>// データベーステーブルのプレフィックスとデータベーステーブル列のフォーマット指定子を設定します。<br>$GLOBALS[\'table_prefix\'] = $table_prefix;<br>wp_set_wpdb_vars();</p>\n<p>// WordPressオブジェクトキャッシュ、またはドロップインが存在する場合は外部オブジェクトキャッシュを起動します。<br>wp_start_object_cache();</p>\n<p>// Attach the default filters.<br>require( ABSPATH . WPINC . \'/default-filters.php\' );</p>\n<p>// 有効な場合はマルチサイトを初期化します。<br>if ( is_multisite() ) {<br>require( ABSPATH . WPINC . \'/class-wp-site-query.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-network-query.php\' );<br>require( ABSPATH . WPINC . \'/ms-blogs.php\' );<br>require( ABSPATH . WPINC . \'/ms-settings.php\' );<br>} elseif ( ! defined( \'MULTISITE\' ) ) {<br>define( \'MULTISITE\', false );<br>}</p>\n<p>register_shutdown_function( \'shutdown_action_hook\' );</p>\n<p>// 基本的な機能を使いたいだけなら、大半のWordPressをロードしないようにしてください。<br>if ( SHORTINIT ) {<br>return false;<br>}</p>\n<p>// L10nライブラリをロードする<br>require_once( ABSPATH . WPINC . \'/l10n.php\' );<br>require_once( ABSPATH . WPINC . \'/class-wp-locale.php\' );<br>require_once( ABSPATH . WPINC . \'/class-wp-locale-switcher.php\' );</p>\n<p>// WordPressがインストールされていない場合はインストーラを実行してください<br>wp_not_installed();</p>\n<p>// WordPressの大半をロードする<br>require( ABSPATH . WPINC . \'/class-wp-walker.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-ajax-response.php\' );<br>require( ABSPATH . WPINC . \'/capabilities.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-roles.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-role.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-user.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-query.php\' );<br>require( ABSPATH . WPINC . \'/query.php\' );<br>require( ABSPATH . WPINC . \'/date.php\' );<br>require( ABSPATH . WPINC . \'/theme.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-theme.php\' );<br>require( ABSPATH . WPINC . \'/template.php\' );<br>require( ABSPATH . WPINC . \'/user.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-user-query.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-session-tokens.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-user-meta-session-tokens.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-metadata-lazyloader.php\' );<br>require( ABSPATH . WPINC . \'/general-template.php\' );<br>require( ABSPATH . WPINC . \'/link-template.php\' );<br>require( ABSPATH . WPINC . \'/author-template.php\' );<br>require( ABSPATH . WPINC . \'/post.php\' );<br>require( ABSPATH . WPINC . \'/class-walker-page.php\' );<br>require( ABSPATH . WPINC . \'/class-walker-page-dropdown.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-post-type.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-post.php\' );<br>require( ABSPATH . WPINC . \'/post-template.php\' );<br>require( ABSPATH . WPINC . \'/revision.php\' );<br>require( ABSPATH . WPINC . \'/post-formats.php\' );<br>require( ABSPATH . WPINC . \'/post-thumbnail-template.php\' );<br>require( ABSPATH . WPINC . \'/category.php\' );<br>require( ABSPATH . WPINC . \'/class-walker-category.php\' );<br>require( ABSPATH . WPINC . \'/class-walker-category-dropdown.php\' );<br>require( ABSPATH . WPINC . \'/category-template.php\' );<br>require( ABSPATH . WPINC . \'/comment.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-comment.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-comment-query.php\' );<br>require( ABSPATH . WPINC . \'/class-walker-comment.php\' );<br>require( ABSPATH . WPINC . \'/comment-template.php\' );<br>require( ABSPATH . WPINC . \'/rewrite.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-rewrite.php\' );<br>require( ABSPATH . WPINC . \'/feed.php\' );<br>require( ABSPATH . WPINC . \'/bookmark.php\' );<br>require( ABSPATH . WPINC . \'/bookmark-template.php\' );<br>require( ABSPATH . WPINC . \'/kses.php\' );<br>require( ABSPATH . WPINC . \'/cron.php\' );<br>require( ABSPATH . WPINC . \'/deprecated.php\' );<br>require( ABSPATH . WPINC . \'/script-loader.php\' );<br>require( ABSPATH . WPINC . \'/taxonomy.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-taxonomy.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-term.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-term-query.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-tax-query.php\' );<br>require( ABSPATH . WPINC . \'/update.php\' );<br>require( ABSPATH . WPINC . \'/canonical.php\' );<br>require( ABSPATH . WPINC . \'/shortcodes.php\' );<br>require( ABSPATH . WPINC . \'/embed.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-embed.php\' );<br>require( ABSPATH . WPINC . \'/class-oembed.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-oembed-controller.php\' );<br>require( ABSPATH . WPINC . \'/media.php\' );<br>require( ABSPATH . WPINC . \'/http.php\' );<br>require( ABSPATH . WPINC . \'/class-http.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-http-streams.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-http-curl.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-http-proxy.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-http-cookie.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-http-encoding.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-http-response.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-http-requests-response.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-http-requests-hooks.php\' );<br>require( ABSPATH . WPINC . \'/widgets.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-widget.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-widget-factory.php\' );<br>require( ABSPATH . WPINC . \'/nav-menu.php\' );<br>require( ABSPATH . WPINC . \'/nav-menu-template.php\' );<br>require( ABSPATH . WPINC . \'/admin-bar.php\' );<br>require( ABSPATH . WPINC . \'/rest-api.php\' );<br>require( ABSPATH . WPINC . \'/rest-api/class-wp-rest-server.php\' );<br>require( ABSPATH . WPINC . \'/rest-api/class-wp-rest-response.php\' );<br>require( ABSPATH . WPINC . \'/rest-api/class-wp-rest-request.php\' );<br>require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-controller.php\' );<br>require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-posts-controller.php\' );<br>require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-attachments-controller.php\' );<br>require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-post-types-controller.php\' );<br>require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-post-statuses-controller.php\' );<br>require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-revisions-controller.php\' );<br>require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-autosaves-controller.php\' );<br>require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-taxonomies-controller.php\' );<br>require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-terms-controller.php\' );<br>require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-users-controller.php\' );<br>require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-comments-controller.php\' );<br>require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-search-controller.php\' );<br>require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-blocks-controller.php\' );<br>require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-block-renderer-controller.php\' );<br>require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-settings-controller.php\' );<br>require( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-themes-controller.php\' );<br>require( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-meta-fields.php\' );<br>require( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-comment-meta-fields.php\' );<br>require( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-post-meta-fields.php\' );<br>require( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-term-meta-fields.php\' );<br>require( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-user-meta-fields.php\' );<br>require( ABSPATH . WPINC . \'/rest-api/search/class-wp-rest-search-handler.php\' );<br>require( ABSPATH . WPINC . \'/rest-api/search/class-wp-rest-post-search-handler.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-block-type.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-block-type-registry.php\' );<br>require( ABSPATH . WPINC . \'/class-wp-block-parser.php\' );<br>require( ABSPATH . WPINC . \'/blocks.php\' );<br>require( ABSPATH . WPINC . \'/blocks/archives.php\' );<br>require( ABSPATH . WPINC . \'/blocks/block.php\' );<br>require( ABSPATH . WPINC . \'/blocks/categories.php\' );<br>require( ABSPATH . WPINC . \'/blocks/latest-comments.php\' );<br>require( ABSPATH . WPINC . \'/blocks/latest-posts.php\' );<br>require( ABSPATH . WPINC . \'/blocks/shortcode.php\' );</p>\n<p>$GLOBALS[\'wp_embed\'] = new WP_Embed();</p>\n<p>// マルチサイト固有のファイルをロードします。<br>if ( is_multisite() ) {<br>require( ABSPATH . WPINC . \'/ms-functions.php\' );<br>require( ABSPATH . WPINC . \'/ms-default-filters.php\' );<br>require( ABSPATH . WPINC . \'/ms-deprecated.php\' );<br>}</p>\n<p>// デフォルト値を取得するためにAPIに依存する定数を定義します。<br>// sunrise.phpドロップインで上書きされる可能性のある、必ず使用するプラグインディレクトリ定数を定義します。.<br>wp_plugin_directory_constants();</p>\n<p>$GLOBALS[\'wp_plugin_paths\'] = array();</p>\n<p>// マストユーズプラグインをロードします<br>foreach ( wp_get_mu_plugins() as $mu_plugin ) {<br>include_once( $mu_plugin );</p>\n<p>/**<br>* 一つのマストユーズプラグインがロードされたら起動する<br>*<br>* @since 5.1.0<br>*<br>* @param string $mu_plugin Full path to the plugin\'s main file.<br>*/<br>do_action( \'mu_plugin_loaded\', $mu_plugin );<br>}<br>unset( $mu_plugin );</p>\n<p>// ネットワーク起動プラグインをロードします<br>if ( is_multisite() ) {<br>foreach ( wp_get_active_network_plugins() as $network_plugin ) {<br>wp_register_plugin_realpath( $network_plugin );<br>include_once( $network_plugin );</p>\n<p>/**<br>* 一つのネットワーク起動プラグインがロードされたら起動する<br>*<br>* @since 5.1.0<br>*<br>* @param string $network_plugin Full path to the plugin\'s main file.<br>*/<br>do_action( \'network_plugin_loaded\', $network_plugin );<br>}<br>unset( $network_plugin );<br>}</p>\n<p>/**<br>* Fires once all must-use and network-activated plugins have loaded.<br>*<br>* @since 2.8.0<br>*/<br>do_action( \'muplugins_loaded\' );</p>\n<p>if ( is_multisite() ) {<br>ms_cookie_constants();<br>}</p>\n<p>// Define constants after multisite is loaded.<br>wp_cookie_constants();</p>\n<p>// Define and enforce our SSL constants<br>wp_ssl_constants();</p>\n<p>// Create common globals.<br>require( ABSPATH . WPINC . \'/vars.php\' );</p>\n<p>// Make taxonomies and posts available to plugins and themes.<br>// @plugin authors: warning: these get registered again on the init hook.<br>create_initial_taxonomies();<br>create_initial_post_types();</p>\n<p>wp_start_scraping_edited_file_errors();</p>\n<p>// Register the default theme directory root<br>register_theme_directory( get_theme_root() );</p>\n<p>// Load active plugins.<br>foreach ( wp_get_active_and_valid_plugins() as $plugin ) {<br>wp_register_plugin_realpath( $plugin );<br>include_once( $plugin );</p>\n<p>/**<br>* Fires once a single activated plugin has loaded.<br>*<br>* @since 5.1.0<br>*<br>* @param string $plugin Full path to the plugin\'s main file.<br>*/<br>do_action( \'plugin_loaded\', $plugin );<br>}<br>unset( $plugin );</p>\n<p>// Load pluggable functions.<br>require( ABSPATH . WPINC . \'/pluggable.php\' );<br>require( ABSPATH . WPINC . \'/pluggable-deprecated.php\' );</p>\n<p>// Set internal encoding.<br>wp_set_internal_encoding();</p>\n<p>// Run wp_cache_postload() if object cache is enabled and the function exists.<br>if ( WP_CACHE &amp;&amp; function_exists( \'wp_cache_postload\' ) ) {<br>wp_cache_postload();<br>}</p>\n<p>/**<br>* Fires once activated plugins have loaded.<br>*<br>* Pluggable functions are also available at this point in the loading order.<br>*<br>* @since 1.5.0<br>*/<br>do_action( \'plugins_loaded\' );</p>\n<p>// Define constants which affect functionality if not already defined.<br>wp_functionality_constants();</p>\n<p>// Add magic quotes and set up $_REQUEST ( $_GET + $_POST )<br>wp_magic_quotes();</p>\n<p>/**<br>* Fires when comment cookies are sanitized.<br>*<br>* @since 2.0.11<br>*/<br>do_action( \'sanitize_comment_cookies\' );</p>\n<p>/**<br>* WordPress Query object<br>*<br>* @global WP_Query $wp_the_query<br>* @since 2.0.0<br>*/<br>$GLOBALS[\'wp_the_query\'] = new WP_Query();</p>\n<p>/**<br>* Holds the reference to @see $wp_the_query<br>* Use this global for WordPress queries<br>*<br>* @global WP_Query $wp_query<br>* @since 1.5.0<br>*/<br>$GLOBALS[\'wp_query\'] = $GLOBALS[\'wp_the_query\'];</p>\n<p>/**<br>* Holds the WordPress Rewrite object for creating pretty URLs<br>*<br>* @global WP_Rewrite $wp_rewrite<br>* @since 1.5.0<br>*/<br>$GLOBALS[\'wp_rewrite\'] = new WP_Rewrite();</p>\n<p>/**<br>* WordPress Object<br>*<br>* @global WP $wp<br>* @since 2.0.0<br>*/<br>$GLOBALS[\'wp\'] = new WP();</p>\n<p>/**<br>* WordPress Widget Factory Object<br>*<br>* @global WP_Widget_Factory $wp_widget_factory<br>* @since 2.8.0<br>*/<br>$GLOBALS[\'wp_widget_factory\'] = new WP_Widget_Factory();</p>\n<p>/**<br>* WordPress User Roles<br>*<br>* @global WP_Roles $wp_roles<br>* @since 2.0.0<br>*/<br>$GLOBALS[\'wp_roles\'] = new WP_Roles();</p>\n<p>/**<br>* Fires before the theme is loaded.<br>*<br>* @since 2.6.0<br>*/<br>do_action( \'setup_theme\' );</p>\n<p>// Define the template related constants.<br>wp_templating_constants();</p>\n<p>// Load the default text localization domain.<br>load_default_textdomain();</p>\n<p>$locale = get_locale();<br>$locale_file = WP_LANG_DIR . \"/$locale.php\";<br>if ( ( 0 === validate_file( $locale ) ) &amp;&amp; is_readable( $locale_file ) ) {<br>require( $locale_file );<br>}<br>unset( $locale_file );</p>\n<p>/**<br>* WordPress Locale object for loading locale domain date and various strings.<br>*<br>* @global WP_Locale $wp_locale<br>* @since 2.1.0<br>*/<br>$GLOBALS[\'wp_locale\'] = new WP_Locale();</p>\n<p>/**<br>* WordPress Locale Switcher object for switching locales.<br>*<br>* @since 4.7.0<br>*<br>* @global WP_Locale_Switcher $wp_locale_switcher WordPress locale switcher object.<br>*/<br>$GLOBALS[\'wp_locale_switcher\'] = new WP_Locale_Switcher();<br>$GLOBALS[\'wp_locale_switcher\']-&gt;init();</p>\n<p>// Load the functions for the active theme, for both parent and child theme if applicable.<br>foreach ( wp_get_active_and_valid_themes() as $theme ) {<br>if ( file_exists( $theme . \'/functions.php\' ) ) {<br>include $theme . \'/functions.php\';<br>}<br>}<br>unset( $theme );</p>\n<p>/**<br>* Fires after the theme is loaded.<br>*<br>* @since 3.0.0<br>*/<br>do_action( \'after_setup_theme\' );</p>\n<p>// Set up current user.<br>$GLOBALS[\'wp\']-&gt;init();</p>\n<p>/**<br>* Fires after WordPress has finished loading but before any headers are sent.<br>*<br>* Most of WP is loaded at this stage, and the user is authenticated. WP continues<br>* to load on the {@see \'init\'} hook that follows (e.g. widgets), and many plugins instantiate<br>* themselves on it for all sorts of reasons (e.g. they need a user, a taxonomy, etc.).<br>*<br>* If you wish to plug an action once WP is loaded, use the {@see \'wp_loaded\'} hook below.<br>*<br>* @since 1.5.0<br>*/<br>do_action( \'init\' );</p>\n<p>// Check site status<br>if ( is_multisite() ) {<br>if ( true !== ( $file = ms_site_check() ) ) {<br>require( $file );<br>die();<br>}<br>unset( $file );<br>}</p>\n<p>/**<br>* This hook is fired once WP, all plugins, and the theme are fully loaded and instantiated.<br>*<br>* Ajax requests should use wp-admin/admin-ajax.php. admin-ajax.php can handle requests for<br>* users not logged in.<br>*<br>* @link https://codex.wordpress.org/AJAX_in_Plugins<br>*<br>* @since 3.0.0<br>*/<br>do_action( \'wp_loaded\' );</p>\n<p></p>\n<p></p>\n<p></p>\n\n<!-- wp:heading -->\n<h2> まとめ：このファイルで行ってること </h2>\n<!-- /wp:heading -->\n\n<p>・</p>\n\n<!-- wp:heading -->\n<h2> おまけ：このファイルで使われた関数 </h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3> php関数 </h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3> wp関数 </h3>\n<!-- /wp:heading -->','wp-setting.phpを解読してみた','','inherit','closed','closed','','1816-revision-v1','','','2019-05-13 09:59:38','2019-05-13 00:59:38','',1816,'http://localhost:8080/anothor/1816-revision-v1',0,'revision','',0),(1924,1,'2019-05-13 10:54:54','2019-05-13 01:54:54','<!-- wp:heading -->\n<h2> wordpressにおけるwp-setting.phpとは </h2>\n<!-- /wp:heading -->\n\n<p>wp-setting.phpはwordpressのコアファイルを読み込んでいく際のおよそ3番目に読まれるファイルになります。</p>\n<p>wp-load.php</p>\n<p>↓</p>\n<p>wp-config.php</p>\n<p>↓</p>\n<p><strong><span style=\"color: #ff0000;\">wp-setting.php</span></strong></p>\n<p>↓</p>\n<p>wordpressのコアファイル群</p>\n<p> </p>\n<p>wp-setting.phpで行っていることはざっくりいうと、wordpressを起動させる際の設定をし、コアファイルたちを次々実行していき実質的にwordpressを起動させるファイルになります。</p>\n<p> </p>\n<p> </p>\n\n<!-- wp:heading -->\n<h2> 実際に翻訳してみた </h2>\n<!-- /wp:heading -->\n\n<p>長いので、400行ちょっとあるファイルなので分割していきます。</p>\n<p> </p>\n<p> </p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>冒頭～メンテナンスモードまで</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>メンテナンスモード～デフォルトフィルター登録まで</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>デフォルトフィルター登録 ～ コアファイルの読み込みまで</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3> コアファイルの読み込み ～ まで</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3></h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2> まとめ：このファイルで行ってること </h2>\n<!-- /wp:heading -->\n\n<p>・</p>\n\n<!-- wp:heading -->\n<h2> おまけ：このファイルで使われた関数 </h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3> php関数 </h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3> wp関数 </h3>\n<!-- /wp:heading -->','wp-setting.phpを解読してみた','','inherit','closed','closed','','1816-revision-v1','','','2019-05-13 10:54:54','2019-05-13 01:54:54','',1816,'http://localhost:8080/anothor/1816-revision-v1',0,'revision','',0),(1925,1,'2019-05-13 11:03:48','2019-05-13 02:03:48','<!-- wp:heading -->\n<h2> wordpressにおけるwp-setting.phpとは </h2>\n<!-- /wp:heading -->\n\n<p>wp-setting.phpはwordpressのコアファイルを読み込んでいく際のおよそ3番目に読まれるファイルになります。</p>\n<p>wp-load.php</p>\n<p>↓</p>\n<p>wp-config.php</p>\n<p>↓</p>\n<p><strong><span style=\"color: #ff0000;\">wp-setting.php</span></strong></p>\n<p>↓</p>\n<p>wordpressのコアファイル群</p>\n<p> </p>\n<p>wp-setting.phpで行っていることはざっくりいうと、wordpressを起動させる際の設定をし、コアファイルたちを次々実行していき実質的にwordpressを起動させるファイルになります。</p>\n<p> </p>\n<p> </p>\n\n<!-- wp:heading -->\n<h2> 実際に翻訳してみた </h2>\n<!-- /wp:heading -->\n\n<p>長いので、400行ちょっとあるファイルなので行っている処理ごとに分割していきます。</p>\n<p> </p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>冒頭～メンテナンスモードまで</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>メンテナンスモード～デフォルトフィルター登録まで</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>デフォルトフィルター登録 ～ コアファイルの読み込みまで</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3> コアファイルの読み込み ～ まで</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3></h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2> まとめ：このファイルで行ってること </h2>\n<!-- /wp:heading -->\n\n<p>・</p>\n\n<!-- wp:heading -->\n<h2> おまけ：このファイルで使われた関数 </h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3> php関数 </h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3> wp関数 </h3>\n<!-- /wp:heading -->','wp-setting.phpを解読してみた','','inherit','closed','closed','','1816-revision-v1','','','2019-05-13 11:03:48','2019-05-13 02:03:48','',1816,'http://localhost:8080/anothor/1816-revision-v1',0,'revision','',0),(1927,1,'2019-05-13 15:46:32','2019-05-13 06:46:32','<!-- wp:heading -->\n<h2>wordpressにおけるwp-load.phpとは</h2>\n<!-- /wp:heading -->\n\n<p>フロント側であっても管理画面であっても必ず読み込まれるファイルの一つにこのload.phpがあります。</p>\n<p>このwp-load.phpはwordpressのコアが読み込まれる際に、<span style=\"color: #ff0000;\"><strong>最初に</strong></span>当たるファイルなので、このファイルが読み込まれる事は実質的にwordpressを起動させ、動かすことができます。</p>\n<p>「動かす」というのは具体的には以下のことができます。</p>\n<p>・wordpressのタイトルやテーマを表示（取得）できる</p>\n<p>・wordpress内のテーブル内のデータを取得・変更・削除できる</p>\n<p>・読み込ませたファイルでバッチ処理ができる</p>\n<p>などなど・・</p>\n<p></p>\n\n<!-- wp:heading -->\n<h2>実際に翻訳してみた</h2>\n<!-- /wp:heading -->\n\n<p>英語のコメントも日本語訳してます。</p>\n<p>変な日本語訳になってたらすみませんm(_ _)m</p>\n<pre class=\"lang:php decode:true\" title=\"wp-load.php（Jananese）\">/**\n * ABSPATH定数を設定するためのブートストラップファイルです。\n * そしてwp-config.phpファイルを読み込みます\n * wp-config.phpはwp-settings.phpファイルを読み込みます。\n * これでWordPress環境がセットアップされます。\n *\n * wp-config.phpファイルが見つからない場合は、\n * 訪問者にwp-config.phpファイルを設定するように\n * 要求するエラーが表示されます。\n *\n * WordPressのディレクトリを維持しておくために、\n * wp-config.phpを検索する際は親ディレクトリも検索します。\n *\n * @package WordPress\n */\n \n/** Define ABSPATH as this file\'s directory */\n//「ABSPATH」が定義されていなかったら\nif ( ! defined( \'ABSPATH\' ) ) {\n \n//「ABSPATH」をドキュメントルート（起点の/からこのファイルがあるディレクトリ+/）に定義する\n	define( \'ABSPATH\', dirname( __FILE__ ) . \'/\' );\n}\n \n//エラーレベルを以下の通りに設定する\nerror_reporting( E_CORE_ERROR | E_CORE_WARNING | E_COMPILE_ERROR | E_ERROR | E_WARNING | E_PARSE | E_USER_ERROR | E_USER_WARNING | E_RECOVERABLE_ERROR );\n \n/*\n * wp-config.phpがWordPressのルートに存在する場合、またはルートに存在するがwp-settings.phpが存在しない場合は、\n * wp-config.phpをロードしてください。  wp-settings.phpの二次チェックには、現在のディレクトリが入れ子になったインストールの場合を回避するという追加の利点があります。\n * /はWordPress（a）、/ blog /はWordPress（b）です。\n *\n * どちらの条件も満たさない場合は、セットアッププロセスのロードを開始してください。\n */\n \n//ABSPATHの先にwp-config.phpがあったら\nif ( file_exists( ABSPATH . \'wp-config.php\' ) ) {\n \n	/** 設定ファイルはABSPATHにあります。*/\n	//wp-config.phpを一回読み込む\n	require_once( ABSPATH . \'wp-config.php\' );\n \n//ABSPATHの一つ上の階層にwp-config.phpがあって、wp-settingsがなかったら\n} elseif ( @file_exists( dirname( ABSPATH ) . \'/wp-config.php\' ) &amp;&amp; ! @file_exists( dirname( ABSPATH ) . \'/wp-settings.php\' ) ) {\n \n	/** 設定ファイルはABSPATHより1レベル上にありますが、他のwordpressのインストールのものではありません */\n	//wp-config.phpを一回読み込む\n	require_once( dirname( ABSPATH ) . \'/wp-config.php\' );\n \n//ABSPATHの先にwp-config.phpがなかったら\n} else {\n \n	//「WPINC」をwp-includesディレクトリと定義する\n	define( \'WPINC\', \'wp-includes\' );\n \n	//wp-includes/load.phpを一回読み込む\n	require_once( ABSPATH . WPINC . \'/load.php\' );\n \n	//設定間で$ _SERVER変数を標準化します。\n	wp_fix_server_vars();\n \n	//wp-includes/functions.phpを一回読み込む\n	require_once( ABSPATH . WPINC . \'/functions.php\' );\n \n	//変数：pathをサイトURL/wp-admin/setup-config.phpとする\n	$path = wp_guess_url() . \'/wp-admin/setup-config.php\';\n \n	/*\n	 * setup-config.phpにリダイレクトします。\n	 * これは無限ループにはならないでしょうが、それを想定するのが愚かなことだと思いませんか？\n	 * 私たちが輪になって旅行してるなら、私たちの最後の努力は「もっと助けが必要ですか？」です。\n	 */\n \n	//set-upconfigがURLに含まれてなかったら\n	if ( false === strpos( $_SERVER[\'REQUEST_URI\'], \'setup-config\' ) ) {\n		//HTTPレスポンスのステータスコードを302で返し、リダイレクト先を$pathにする。\n		header( \'Location: \' . $path );\n		exit;\n	}\n \n    //「WP_CONTENT_DIR」をドキュメントルート/wp-contentディレクトリとする\n	define( \'WP_CONTENT_DIR\', ABSPATH . \'wp-content\' );\n \n    //wp-includes/version.phpを一回読み込む\n	require_once( ABSPATH . WPINC . \'/version.php\' );\n \n    //phpとmysqlのバージョンを確認する\n	wp_check_php_mysql_versions();\n \n    //早い段階で翻訳する\n	wp_load_translations_early();\n \n    // エラーメッセージで終了\n	/* %sを wp-config.php に翻訳する*/\n	$die = sprintf(\n		//wp-config.phpファイルはありません。始める前にこれが必要です。\n		__( \"There doesn\'t seem to be a %s file. I need this before we can get started.\" ),\n		\'&lt;code&gt;wp-config.php&lt;/code&gt;\'\n	) . \'&lt;/p&gt;\';\n \n	/* %sをCodex URLに翻訳する*/\n	$die .= \'&lt;p&gt;\' . sprintf(\n		//もっと助けが必要ですか？（リンク先：Codex URL）\n		__( \"Need more help? &lt;a href=\'%s\'&gt;We got it&lt;/a&gt;.\" ),\n		__( \'https://codex.wordpress.org/Editing_wp-config.php\' )\n	) . \'&lt;/p&gt;\';\n \n	/* %sをwp-config.php に翻訳する*/\n	$die .= \'&lt;p&gt;\' . sprintf(\n		//あなたはWebインターフェースを通してwp-config.phpファイルを作成することができますが、これはすべてのサーバー設定に対しては機能しません。最も安全な方法は手動でファイルを作成することです。\n		__( \"You can create a %s file through a web interface, but this doesn\'t work for all server setups. The safest way is to manually create the file.\" ),\n		\'&lt;code&gt;wp-config.php&lt;/code&gt;\'\n	) . \'&lt;/p&gt;\';\n \n	//設定ファイルを作成します(リンク先：サイトURL/wp-admin/setup-config.php)\n	$die .= \'&lt;p&gt;&lt;a href=\"\' . $path . \'\" class=\"button button-large\"&gt;\' . __( \'Create a Configuration File\' ) . \'&lt;/a&gt;\';\n \n	//WordPressの処理を中断し「WordPress &gt; Error」のタイトルで$dieのエラーメッセージをHTMLで出力する\n	wp_die( $die, __( \'WordPress &amp;rsaquo; Error\' ) );\n}\n\n</pre>\n<p></p>\n\n<!-- wp:heading -->\n<h2>まとめ：このファイルで行ってること</h2>\n<!-- /wp:heading -->\n\n<p>・まず「ABSPATH」という単語をドキュメントルートに定義しています。</p>\n<p>・次にエラーレベルを設定しています。</p>\n<p>・その後config.phpを読みこみます。上で設定したABSPATH（ドキュメントルート）直下にあるか、もしくは1段階上にある場合は読み込みます。</p>\n<p>もし、どちらにも該当しなかった場合はwp-includesディレクトリ直下にあるload.phpとfunctions.phpを読みに行き、その後wp-adminディレクトリにあるsetup-config.phpへリダイレクトするようにしています。</p>\n<p></p>\n<p>・その後、変数「$path」にサイトURL/wp-admin/setup-config.phpを充てて、setup-configという文字列がページにアクセスした際のドメイン以降のURIに含まれていなかったら、ステータスコードを302で返し、リダイレクト先を$path(サイトURL/wp-admin/setup-config.php)を返すようにしています。</p>\n<p>・「WP_CONTENT_DIR」という単語をwp-contentディレクトリに定義しています。</p>\n<p>・wp-includesディレクトリにあるversion.phpを一回読みにいきます。</p>\n<p>・最後に返すエラーメッセージを設定しています。</p>\n<p></p>\n<p></p>\n\n<!-- wp:heading -->\n<h2>おまけ：このファイルで使われた関数</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>php関数</h3>\n<!-- /wp:heading -->\n\n<h4>dirname( ファイル名 , さかのぼる階層)</h4>\n<p>第一引数に入るのはファイル名かディレクトリ名。</p>\n<p>この第一引数にかかれた文字列を受け取って、ルートからそのファイルのあるディレクトリまでのパスを取得します。</p>\n<p>第二引数は数字（int）が入ります。</p>\n<p>１だと同階層なため入力しなくても同じ結果がでますが、2は一階層上、３は二階層上までのパスを返します。</p>\n<p>なお、<strong>__FILE__</strong>はマジカル定数と呼ばれるもので、このファイル名とそのファイルまでのパスを取得できます。</p>\n<p>ためしに/home/centos/にfile.phpというファイルを作成し、以下の内容を記述してみました。</p>\n<pre class=\"\">&lt;?php\n\necho __FILE__.\"\\n\";\ndirname(__FILE__).\"\\n\";\n\n</pre>\n<p>実行結果がこちらです</p>\n<p>↓</p>\n<pre class=\"\">/home/centos/file.php      //__FILE__だけ\n/home/centos               //dirname(__FILE__)\n\n</pre>\n<p> </p>\n<h4>define( \'定数名\', 返す値 , trueかfalse );</h4>\n<p>defineは自分で定数を作りたい時に決める事ができる関数。</p>\n<p>第一引数は定数にしたい言葉。</p>\n<p>第二引数はその定数で返す値。文字列でも数値でも他の変数でも可。</p>\n<p>第三引数はtrueかfalse。trueだと定数名が大文字でも小文字でも第二引数の値を返す。</p>\n<p>falseだと大文字と小文字が区別されるので、もし同じ文字列でも大小違うと違う定数としてみなされます。</p>\n<h4><span class=\"crayon-st\">if</span> <span class=\"crayon-sy\">(</span> <span class=\"crayon-o\">!</span> <span class=\"crayon-e\">defined</span><span class=\"crayon-sy\">(</span> <span class=\"crayon-s\">\'定数名\'</span> <span class=\"crayon-sy\">)</span> <span class=\"crayon-sy\">)</span> <span class=\"crayon-sy\">{<br />      実行する処理<br />}</span></h4>\n<p>この定数名が存在したら、実行したい処理をするといった感じです。</p>\n<p>だいたいwordpressのコアファイルではこれとセットで定数を定義しています。</p>\n<pre class=\"lang:php decode:true  \" title=\"define&amp;defined\">if ( ! defined( \'定義名\' ) ) {\n　　define( \'定義名\',返したい値  );\n}\n//定義したい名前がすでに使われているか確認してから、定義する感じ\n\n</pre>\n<p> </p>\n<h4>error_reporting（定義済み定数）</h4>\n<p>出力するエラーを設定します。</p>\n<p> </p>\n<h4>@file_exists(ディレクトリ . ファイル名)</h4>\n<p>ファイルがあるかどうか。</p>\n<p>TRUEかFALSEで返すため、だいたいif文で使ってます。</p>\n<p> </p>\n<h4>strpos(検索される文字列 , 探したい文字列 , 検索開始位置)</h4>\n<p>第一引数には探す範囲を指定します。</p>\n<p>第二引数は探したい文字が入ります。</p>\n<p>第三引数はオフセットと呼ばれる数字（int）が入ります。</p>\n<p>これは第一引数で指定した文字列内で何文字目から探すのかを指定します。</p>\n<p>例えば、頭の2文字を飛ばした部分から検索したい時は第三引数には1と入ります。</p>\n<p>数え方は一文字目は0から始まるため、一つづつずれます。</p>\n<p>なお、負の数をいれると文字列の末尾からこの数だけ戻った場所から検索を開始します。</p>\n<p> </p>\n<p> </p>\n<h4>$_SERVER[ \' キー名 \' ]</h4>\n<p>phpの定義済み変数のうち、$_SERVER（サーバ変数）はサーバ内のヘッダ、パス、スクリプトの位置のような情報を取得できる変数です。</p>\n<p>その中でもREQUEST_URIというキーはドメイン以降のパスを取得できます。</p>\n<p>ex)</p>\n<p>このページならhttp://localhost:8080<span style=\"color: #008080;\">/web_and_aplication/source-reading_wp-load-php</span></p>\n<p>なのでREQUEST_URIは</p>\n<p><span style=\"text-decoration: underline; color: #008080;\">web_and_aplication/source-reading_wp-load-php</span></p>\n<p>が返ってきます。</p>\n<p>この関数に関しては詳しくは以下のページにて↓</p>\n<p><span style=\"color: #3366ff;\"><strong><a style=\"color: #3366ff;\" href=\"http://localhost:8080/web_and_aplication/server-variable\" target=\"_blank\" rel=\"noopener noreferrer\"><span style=\"text-decoration: underline;\">$_SERVERで色々出してみた</span></a></strong></span></p>\n<p> </p>\n<h4>header( <span class=\"crayon-sy\">$</span>ヘッダ文字列 . $path );</h4>\n<p>header関数は、送信するHTTPヘッダの中身を自分で色々指定できる関数です。これを使うと返ってくるレスポンスをコントロールできます。</p>\n<p>中でも、Locationヘッダはリダイレクト先のページを指定できるので、特定のファイルやリソースを指定しブラウザ上に表示することができます。</p>\n<p><a href=\"http://localhost:8080/backend_and_server/request_and_response\" target=\"_blank\" rel=\"noopener noreferrer\"><span style=\"color: #3366ff;\"><strong><span style=\"text-decoration: underline;\">リクエストとレスポンスについて</span></strong></span></a></p>\n<p> </p>\n<h4>sprintf( \'フォーマットとして返したい文\' ,)</h4>\n<p> </p>\n<p> </p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>wp関数</h3>\n<!-- /wp:heading -->\n\n<h4>wp_fix_server_vars</h4>\n<p>上で出てきた$_SERVER変数はサーバ情報を取得できますが、動作環境によって$_SERVER変数の値が違うため、その差異を訂正する関数になります。</p>\n<p>/wp-includes/load.phpに記載。</p>\n<p></p>\n<h4><span class=\"crayon-e\">wp_guess_url</span><span class=\"crayon-sy\">(</span><span class=\"crayon-sy\">);</span></h4>\n<p>/wp-adminディレクトリに含まれていない場合のみURLを返す。</p>\n<p>/wp-admin/includes/noop.phpに記載。</p>\n<p></p>\n<h4>wp_check_php_mysql_versions();</h4>\n<p>phpのバージョンと<span id=\"MySQL\">MySQLの環境や拡張機能のチェックしてます。</span></p>\n<p>/wp-includes/load.phpに記載。</p>\n<p></p>\n<h4>wp_load_translations_early();</h4>\n<p>ロケールが正しく検出されてロードされる前に、初期ロードプロセス中に発生したエラーに使用されます。</p>\n<p>/wp-includes/load.phpに記載。</p>\n<p></p>\n<h4>wp_die( $message, $title );</h4>\n<p>phpのexitやdieと似てます。</p>\n<p>処理を途中で中断して、条件つきのエラーメッセージを返します。</p>\n<p>第一引数は返すエラーメッセージの中身の文章。</p>\n<p>第二引数はエラーのタイトル</p>\n<p>を設定します。</p>\n<p></p>\n<p></p>\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','wp-load.phpを解読してみた','','inherit','closed','closed','','369-autosave-v1','','','2019-05-13 15:46:32','2019-05-13 06:46:32','',369,'http://localhost:8080/anothor/369-autosave-v1',0,'revision','',0),(1928,1,'2019-05-13 12:53:15','2019-05-13 03:53:15','<!-- wp:heading -->\n<h2> wordpressにおけるwp-setting.phpとは </h2>\n<!-- /wp:heading -->\n\n<p>wp-setting.phpはwordpressのコアファイルを読み込んでいく際のおよそ3番目に読まれるファイルになります。</p>\n<p>wp-load.php</p>\n<p>↓</p>\n<p>wp-config.php</p>\n<p>↓</p>\n<p><strong><span style=\"color: #ff0000;\">wp-setting.php</span></strong></p>\n<p>↓</p>\n<p>wordpressのコアファイル群</p>\n<p> </p>\n<p>wp-setting.phpで行っていることはざっくりいうと、wordpressを起動させる際の設定をし、コアファイルたちを次々実行していき実質的にwordpressを起動させるファイルになります。</p>\n<p> </p>\n<p> </p>\n\n<!-- wp:heading -->\n<h2> 実際に翻訳してみた </h2>\n<!-- /wp:heading -->\n\n<p>長いので、400行ちょっとあるファイルなので行っている処理ごとに分割していきます。</p>\n<p> </p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>冒頭～メンテナンスモードまで</h3>\n<!-- /wp:heading -->\n\n<p>行数でいえば、最初から70行目あたりまで。</p>\n<p>wp_debug_mode();という関数があるとこまでです。</p>\n<p> </p>\n<p> </p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>メンテナンスモード～ コアファイルの読み込みまで </h3>\n<!-- /wp:heading -->\n\n<p>行数でいえば、最初から71～行目あたりまで。</p>\n<p>wp_debug_mode();という関数があるとこまでです。</p>\n<p><!-- wp:heading {\"level\":3} --></p>\n<h3>メンテナンスモード～ コアファイルの読み込みまで</h3>\n<p><!-- /wp:heading --></p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3> コアファイルの読み込み ～ まで</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3></h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2> まとめ：このファイルで行ってること </h2>\n<!-- /wp:heading -->\n\n<p>・</p>\n\n<!-- wp:heading -->\n<h2> おまけ：このファイルで使われた関数 </h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3> php関数 </h3>\n<!-- /wp:heading -->\n\n<p>date_default_timezone_set( \'UTC\' );</p>\n<p> </p>\n<p>register_shutdown_function( \'shutdown_action_hook\' );</p>\n<p>シャットダウン時に実行する関数を登録します</p>\n<p> </p>\n<h4>$GLOBALS[\' 変数名 \']</h4>\n<p>phpの定義済み変数のうち、$GLOBALS（グローバル変数）はサーバ内のヘッダ、パス、スクリプトの位置のような情報を取得できる変数です。</p>\n<p>その中でもというキーはドメイン以降のパスを取得できます。</p>\n<p>ex)</p>\n<p>この関数に関しては詳しくは以下のページにて↓</p>\n<p> </p>\n<p> </p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3> wp関数 </h3>\n<!-- /wp:heading -->\n\n<p>wp_initial_constants();</p>\n<p>wp_unregister_GLOBALS();</p>\n<p>wp_favicon_request();</p>\n<p>wp_maintenance();</p>\n<p> </p>\n<p> </p>\n<p>wp_not_installed();</p>\n<p>wp_plugin_directory_constants();</p>\n<p> </p>\n<p> </p>','wp-setting.phpを解読してみた','','inherit','closed','closed','','1816-revision-v1','','','2019-05-13 12:53:15','2019-05-13 03:53:15','',1816,'http://