hpで直接グローバル化することはできません。 更新するとき、\n * 私たちは他のインストールからのversion.phpをインクルードしています。\n * そしてすでに設定されているならこれらの値を上書きされたくないです。\n */\n\n//以下の変数をグローバル宣言する\nglobal $wp_version, $wp_db_version, $tinymce_version, $required_php_version, $required_mysql_version, $wp_local_package;\n//ドキュメントルート/wp-includes/version.phpを読み込む\nrequire( ABSPATH . WPINC . \'/version.php\' );\n\n/**\n * まだ設定されていない場合 blog_idは単一サイト設定でデフォルトの1になります。\n * マルチサイトでは、ms-settings.phpでデフォルトで上書きされます。\n *\n * @global int $blog_id\n * @since 2.0.0\n */\n//\nglobal $blog_id;\n\n// WP_MEMORY_LIMIT、WP_MAX_MEMORY_LIMIT、WP_DEBUG、SCRIPT_DEBUG、WP_CONTENT_DIRおよびWP_CACHEを含む初期デフォルト定数を設定します。\nwp_initial_constants();\n\n// 必要なPHPバージョンとMySQLエクステンションまたはデータベースドロップインをチェックしてください。\nwp_check_php_mysql_versions();\n\n// 実行時にマジッククォートを無効にします。魔法の引用符は後でwp-settings.phpでwpdbを使って追加されます\n@ini_set( \'magic_quotes_runtime\', 0 );\n@ini_set( \'magic_quotes_sybase\', 0 );\n\n// WordPressはUTCからのオフセットを計算します。\ndate_default_timezone_set( \'UTC\' );\n\n// register_globalsをオフにします。\nwp_unregister_GLOBALS();\n\n// 設定間で$ _SERVER変数を標準化します。\nwp_fix_server_vars();\n\n// favicon.icoが見つからないため、リクエストを受信したかどうかを確認します\nwp_favicon_request();\n\n// メンテナンスモードになっているか確認してください。\nwp_maintenance();\n\n// タイマーをロードします。\ntimer_start();\n\n// WP_DEBUGモードになっているか確認してください。\nwp_debug_mode();\n\n/**\n * advanced-cache.phpドロップインのロードを有効にするかどうかをフィルタリングします。\n *\n * このフィルタはプラグインによって使用される前に実行されます。 Web以外のランタイム用に設計されています。\n * falseが返された場合、advanced-cache.phpはロードされません。\n *\n * @since 4.6.0\n *\n * @param bool $enable_advanced_cache_advanced-cache.php（存在する場合）の読み込みを有効にするかどうか\n *                                    Default true.\n */\n\nif ( WP_CACHE && apply_filters( \'enable_loading_advanced_cache_dropin\', true ) ) {\n	// 高度なキャッシングプラグインを使うために。必要なのは静的ドロップインだけです。\n	WP_DEBUG ? include( WP_CONTENT_DIR . \'/advanced-cache.php\' ) : @include( WP_CONTENT_DIR . \'/advanced-cache.php\' );\n\n	// advanced-cache.phpによって手動で追加されたフックを再初期化します\n	if ( $wp_filter ) {\n		$wp_filter = WP_Hook::build_preinitialized_hooks( $wp_filter );\n	}\n}\n\n// 設定されていない場合はWP_LANG_DIRを定義します。\nwp_set_lang_dir();\n\n// 初期のWordPressファイルを読み込む.\nrequire( ABSPATH . WPINC . \'/compat.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-list-util.php\' );\nrequire( ABSPATH . WPINC . \'/formatting.php\' );\nrequire( ABSPATH . WPINC . \'/meta.php\' );\nrequire( ABSPATH . WPINC . \'/functions.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-meta-query.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-matchesmapregex.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-error.php\' );\nrequire( ABSPATH . WPINC . \'/pomo/mo.php\' );\n\n// wpdbクラスと、存在する場合はdb.phpデータベースドロップインを含めます。\nglobal $wpdb;\nrequire_wp_db();\n\n// データベーステーブルのプレフィックスとデータベーステーブル列のフォーマット指定子を設定します。\n$GLOBALS[\'table_prefix\'] = $table_prefix;\nwp_set_wpdb_vars();\n\n// WordPressオブジェクトキャッシュ、またはドロップインが存在する場合は外部オブジェクトキャッシュを起動します。\nwp_start_object_cache();\n\n// デフォルトのフィルタを添付してください。\nrequire( ABSPATH . WPINC . \'/default-filters.php\' );\n\n// 有効な場合はマルチサイトを初期化します。\nif ( is_multisite() ) {\n	require( ABSPATH . WPINC . \'/class-wp-site-query.php\' );\n	require( ABSPATH . WPINC . \'/class-wp-network-query.php\' );\n	require( ABSPATH . WPINC . \'/ms-blogs.php\' );\n	require( ABSPATH . WPINC . \'/ms-settings.php\' );\n} elseif ( ! defined( \'MULTISITE\' ) ) {\n	define( \'MULTISITE\', false );\n}\n\n//関数：shutdown_action_hookをシャットダウン時に実行する\nregister_shutdown_function( \'shutdown_action_hook\' );\n\n// 基本的な機能を使いたいだけなら、大半のWordPressをロードしないようにしてください。\nif ( SHORTINIT ) {\n	return false;\n}\n\n// L10nライブラリをロードする\nrequire_once( ABSPATH . WPINC . \'/l10n.php\' );\nrequire_once( ABSPATH . WPINC . \'/class-wp-locale.php\' );\nrequire_once( ABSPATH . WPINC . \'/class-wp-locale-switcher.php\' );\n\n// WordPressがインストールされていない場合はインストーラを実行してください\nwp_not_installed();\n\n// WordPressコアファイルの大半をロードする\nrequire( ABSPATH . WPINC . \'/class-wp-walker.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-ajax-response.php\' );\nrequire( ABSPATH 