ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-blocks-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-block-renderer-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-settings-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-themes-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-comment-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-post-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-term-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-user-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/search/class-wp-rest-search-handler.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/search/class-wp-rest-post-search-handler.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-block-type.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-block-type-registry.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-block-parser.php\' );\nrequire( ABSPATH . WPINC . \'/blocks.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/archives.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/block.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/categories.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/latest-comments.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/latest-posts.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/shortcode.php\' );\n\n$GLOBALS[\'wp_embed\'] = new WP_Embed();\n\n// マルチサイト固有のファイルをロードします。\nif ( is_multisite() ) {\n	require( ABSPATH . WPINC . \'/ms-functions.php\' );\n	require( ABSPATH . WPINC . \'/ms-default-filters.php\' );\n	require( ABSPATH . WPINC . \'/ms-deprecated.php\' );\n}\n\n// デフォルト値を取得するためにAPIに依存する定数を定義します。\n// sunrise.phpドロップインで上書きされる可能性のある、必ず使用するプラグインディレクトリ定数を定義します。.\nwp_plugin_directory_constants();\n\n$GLOBALS[\'wp_plugin_paths\'] = array();\n\n// マストユーズプラグインをロードします\nforeach ( wp_get_mu_plugins() as $mu_plugin ) {\n	include_once( $mu_plugin );\n\n	/**\n	 * 一つのマストユーズプラグインがロードされたら起動する\n	 *\n	 * @since 5.1.0\n	 *\n	 * @param string $mu_plugin Full path to the plugin\'s main file.\n	 */\n	do_action( \'mu_plugin_loaded\', $mu_plugin );\n}\nunset( $mu_plugin );\n\n// ネットワーク起動プラグインをロードします\nif ( is_multisite() ) {\n	foreach ( wp_get_active_network_plugins() as $network_plugin ) {\n		wp_register_plugin_realpath( $network_plugin );\n		include_once( $network_plugin );\n\n		/**\n		 * 一つのネットワーク起動プラグインがロードされたら起動する\n		 *\n		 * @since 5.1.0\n		 *\n		 * @param string $network_plugin Full path to the plugin\'s main file.\n		 */\n		do_action( \'network_plugin_loaded\', $network_plugin );\n	}\n	unset( $network_plugin );\n}\n\n/**\n * すべての必須使用およびネットワーク起動プラグインがロードされると起動します。\n *\n * @since 2.8.0\n */\n\n//関数：muplugins_loadedを実行する\ndo_action( \'muplugins_loaded\' );\n\nif ( is_multisite() ) {\n	ms_cookie_constants();\n}\n\n// マルチサイトがロードされた後に定数を定義します。\nwp_cookie_constants();\n\n// SSL定数を定義して実施する\nwp_ssl_constants();\n\n// 共通グローバルを作成する\nrequire( ABSPATH . WPINC . \'/vars.php\' );\n\n// タクソノミーや投稿をプラグインやテーマで利用できるようにします。\n// @プラグインの作成者：警告：これらはinitフックに再度登録されます。\ncreate_initial_taxonomies();\ncreate_initial_post_types();\n\nwp_start_scraping_edited_file_errors();\n\n// デフォルトのテーマディレクトリのルートを登録する\nregister_theme_directory( get_theme_root() );\n\n// 有効化されてるプラグインをよみこむ\nforeach ( wp_get_active_and_valid_plugins() as $plugin ) {\n	wp_register_plugin_realpath( $plugin );\n	include_once( $plugin );\n\n	/**\n	 * 一度有効化されたプラグインをよみこむと起動する\n	 *\n	 * @since 5.1.0\n	 *\n	 * @param string $plugin Full path to the plugin\'s main file.\n	 */\n	do_action( \'plugin_loaded\', $plugin );\n}\nunset( $plugin );\n\n// プラガブル関数を読み込む.\nrequire( ABSPATH . WPINC . \'/pluggable.php\' );\nrequire( ABSPATH . WPINC . \'/pluggable-deprecated.php\' );\n\n// 内部エンコーディングを設定します。\nwp_set_internal_encoding();\n\n// オブジェクトキャッシュが有効で、関数が存在する場合は、wp_cache_postload（）を実行する\nif ( WP_CACHE && function_exists( \'wp_cache_postload\' ) ) {\n	wp_cache_postload();\n}\n\n/**\n * 一度有効化されたプラグインをよみこむと起動する\n *\n * 読み込まれているこの時点でプラガブル機能も利用可能です。\n *\n * @since 1.5.0\n */\ndo_action( \'plugins_loaded\' );\n\n// まだ定義されていない場合、機能に影響を与える定数を定義します。\nwp_functionality_constants();\n\n// マジッククオートを追加して$ _REQUEST（$ _GET + $ _POST）を設定する\nwp_magic_quotes();\n\n/**\n * コメントクッキーがサニタイズされたときに起動します。\n *\n * @since 2.0.11\n */\ndo_action( \'sanitize_comment_cookies\' );\n\n/**\n * WordPress Query object\n *\n * @global WP_Query $wp_the_query\n * @since 2.0.0\n */\n$GLOBALS[\'wp_the_query\'] = new WP_Query();\n\n/**\n * $ wp_the_queryへの参照を保持しています\n * WordPressクエリにこのグローバルを使用\n *\n * @global WP_Query $wp_query\n * @since 1.5.0\n */\n$GLOBALS[\'wp_query\'] = $GLOBALS[\'wp_the_query\'];\n\n/**\n * きれいなURLを作成するためのWordPressリライトオブジェクトを保持します。\n * @global WP_Rewrite $wp_rewrite\n * @since 1.5.0\n */\n$GLOBALS[\'wp_rewrite\'] = new WP_Rewrite();\n\n/**\n * WordPress オブジェクト\n *\n * @global WP $wp\n * @since 2.0.0\n */\n$GLOBALS[\'wp\'] = new WP();\n\n/**\n * WordPress Widget Factory Object\n *\n * @global WP_Widget_Factory $wp_widget_factory\n * @since 2.8.0\n */\n$GLOBALS[\'wp_widget_factory\'] = new WP_Widget_Factory();\n\n/**\n * WordPress User Roles\n *\n * @global WP_Roles $wp_roles\n * @since 2.0.0\n */\n$GLOBALS[\'wp_roles\'] = new WP_Roles();\n\n/**\n * テーマが読み込まれる前に発生します。\n *\n * @since 2.6.0\n */\ndo_action( \'setup_theme\' );\n\n// テンプレート関連定数を定義します。\nwp_templating_constants();\n\n// デフォルトのテキストローカライゼーションドメインを読み込む。\nload_default_textdomain();\n\n$locale      = get_locale();\n$locale_file = WP_LANG_DIR . \"/$locale.php\";\nif ( ( 0 === validate_file( $locale ) ) && is_readable( $locale_file ) ) {\n	require( $locale_file );\n}\nunset( $locale_file );\n\n/**\n * ロケールドメインの日付とさまざまな文字列をロードするためのWordPress Localeオブジェクト。\n *\n * @global WP_Locale $wp_locale\n * @since 2.1.0\n */\n$GLOBALS[\'wp_locale\'] = new WP_Locale();\n\n/**\n *  ロケールを切り替えるためのWordPress Locale Switcherオブジェクト\n *\n * @since 4.7.0\n *\n * @global WP_Locale_Switcher $ wp_locale_switcher WordPressロケール切り替えオブジェクト。\n */\n$GLOBALS[\'wp_locale_switcher\'] = new WP_Locale_Switcher();\n$GLOBALS[\'wp_locale_switcher\']--->init();\n\n// 該当する場合は、親テーマと子テーマの両方について、アクティブなテーマの機能をロードします。\nforeach ( wp_get_active_and_valid_themes() as $theme ) {\n	if ( file_exists( $theme . \'/functions.php\' ) ) {\n		include $theme . \'/functions.php\';\n	}\n}\nunset( $theme );\n\n/**\n * テーマが読まれた後に起動する\n *\n * @since 3.0.0\n */\ndo_action( \'after_setup_theme\' );\n\n// 現在のユーザーを設定します。\n$GLOBALS[\'wp\']-&gt;init();\n\n/**\n * WordPressの読み込みが完了した後、ヘッダーが送信される前に起動ます。\n *\n * WPの大部分はこの段階でロードされ、ユーザーは認証されます。\n * WPは{@see \'init\'}フック（例えばウィジェット）に読み込みそれに続いて読み込まれます、多くのプラグインがインスタンス化します\n * WP自身はあらゆる種類の理由で分類します。（例えば、ユーザー、タクソノミーなど）\n *\n * WPがロードされた後にアクションをプラグインしたい場合は、以下の{@see \'wp_loaded\'}フックを使用してください。\n *\n * @since 1.5.0\n */\ndo_action( \'init\' );\n\n// マルチサイトの場合\nif ( is_multisite() ) {\n	if ( true !== ( $file = ms_site_check() ) ) {\n		require( $file );\n		die();\n	}\n	unset( $file );\n}\n\n/**\n * このフックは、WP、すべてのプラグイン、およびテーマが完全に読み込まれてインスタンス化されると起動します。\n *\n * Ajaxリクエストはwp-admin / admin-ajax.phpを使うべきです。\n * ajax.phpは、ログインしていないユーザーに対するリクエストを処理できます。\n * @link https://codex.wordpress.org/AJAX_in_Plugins\n *\n * @since 3.0.0\n */\ndo_action( \'wp_loaded\' );\n\n</pre>\n\n<!-- wp:heading {\"level\":3} -->\n<h3></h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2> まとめ：このファイルで行ってること </h2>\n<!-- /wp:heading -->\n\n<p>・</p>\n\n<!-- wp:heading -->\n<h2> おまけ：このファイルで使われた関数 </h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3> php関数 </h3>\n<!-- /wp:heading -->\n\n<p>date_default_timezone_set( \'UTC\' );</p>\n<p></p>\n<p>register_shutdown_function( \'関数名\' );</p>\n<p>シャットダウン時に実行する関数を登録します</p>\n<p></p>\n<h4>$GLOBALS[\' 変数名 \']</h4>\n<p>phpの定義済み変数のうち、$GLOBALS（グローバル変数）は</p>\n<p>できる変数です。</p>\n<p></p>\n<p>ex)</p>\n<p>この関数に関しては詳しくは以下のページにて↓</p>\n<p></p>\n<p></p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3> wp関数 </h3>\n<!-- /wp:heading -->\n\n<p>wp_initial_constants();</p>\n<p>wp_unregister_GLOBALS();</p>\n<p>wp_favicon_request();</p>\n<p>wp_maintenance();</p>\n<p></p>\n<p></p>\n<p>wp_not_installed();</p>\n<p>wp_plugin_directory_constants();</p>\n<p>wp_set_internal_encoding();</p>\n<p>wp_functionality_constants();</p>','wp-setting.phpを解読してみた','','inherit','closed','closed','','1816-revision-v1','','','2019-05-15 09:07:31','2019-05-15 00:07:31','',1816,'http://localhost:8080/anothor/1816-revision-v1',0,'revision','',0),(2054,1,'2019-05-20 18:44:08','2019-05-20 09:44:08','<p>wordpressのテーブルとカラムついてのまとめ。</p>\n<p>wordpressのテーブルはデフォルトでは全部で12こあります。</p>\n<p>他のプラグインを入れることによってテーブルが増えたりしますが、基本的な構造ではたった12こしかありません。</p>\n<p>一つづつ見ていきましょう！</p>\n<p></p>\n\n<!-- wp:heading -->\n<h2>ユーザ情報に関するテーブル</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>wp_users</h3>\n<!-- /wp:heading -->\n\n<p>wp_usersテーブルはwordpressを使用するユーザ情報を格納しているテーブルです。</p>\n<p>のちに出てくるwp_posts、wp_usermeta、wp_commentsテーブルとは一対多の関係で結びついており、wordpressにおいては、このusersテーブルが起点になっています。</p>\n<p></p>\n\n<!-- wp:html -->\n<table>\n<tr>\n<th>No</th>\n<th>物理名</th>\n<th>論理名</th>\n<th>型</th>\n<th>NULL</th>\n<th>Key</th>\n<th>デフォルト</th>\n<th>その他</th>\n</tr>\n<tr>\n<th>1</th>\n	<td>ID</td>\n	<td>ユーザID</td>\n	<td>bigint(20) unsigned</td>\n	<td>NOT NULL</td>\n	<td>PRI</td>\n	<td>NULL</td>\n	<td>auto_increment</td>\n</tr>\n<tr>\n<th>2</th>\n	<td>user_login</td>\n	<td>ユーザ名</td>\n	<td>varchar(60)</td>\n	<td>NOT NULL</td>\n	<td>MUL</td>\n	<td>0</td>\n	<td>ログインする際のユーザ名</td>\n</tr>\n<tr>\n<th>3</th>\n	<td>user_pass</td>\n	<td>ログインパスワード</td>\n	<td>varchar(64)</td>\n	<td></td>\n	<td>MUL</td>\n	<td>NULL</td>\n	<td>ハッシュ化された値が入ります</td>\n</tr>\n<tr>\n<th>4</th>\n	<td>user_nicename</td>\n	<td></td>\n	<td>varchar(50)</td>\n	<td></td>\n	<td></td>\n	<td>NULL</td>\n	<td></td>\n</tr>\n<tr>\n<th>5</th>\n	<td>user_email</td>\n	<td>メールアドレス</td>\n	<td>varchar(100)</td>\n	<td></td>\n	<td></td>\n	<td>NULL</td>\n	<td></td>\n</tr>\n<tr>\n<th>6</th>\n	<td>user_url</td>\n	<td>ユーザのスラッグ名</td>\n	<td>varchar(100)</td>\n	<td></td>\n	<td></td>\n	<td>NULL</td>\n	<td></td>\n</tr>\n<tr>\n<th>7</th>\n	<td>user_registered</td>\n	<td>登録日時</td>\n	<td>datetime</td>\n	<td></td>\n	<td></td>\n	<td>0000-00-00 00:00:00</td>\n	<td>そのユーザを作成した日時</td>\n</tr>\n<tr>\n<th>8</th>\n	<td>user_activation_key</td>\n	<td>アクティベーションキー</td>\n	<td>varchar(255)</td>\n	<td></td>\n	<td></td>\n	<td>NULL</td>\n	<td>パスワードを再発行する際に</td>\n</tr>\n<tr>\n<th>9</th>\n	<td>user_status</td>\n	<td>ユーザステータス</td>\n	<td>int(11)</td>\n	<td></td>\n	<td></td>\n	<td>0</td>\n	<td>ただwpコアでは使用されておらず全部0が入っています</td>\n</tr>\n<tr>\n<th>10</th>\n	<td>display_name</td>\n	<td>表示名</td>\n	<td>varchar(250)</td>\n	<td></td>\n	<td></td>\n	<td></td>\n	<td></td>\n</tr>\n</table>\n<!-- /wp:html -->\n\n<p>１：usersテーブルのIDは、wp_usermeta、wp_posts、wp_commentsテーブルのそれぞれのuser_idと一体多の関係になっています。</p>\n<p>２：user_loginは管理画面に入る際（login.php）のユーザ名になっています。</p>\n<p>３：user_passは管理画面に入る際（login.php）のパスワードになっています。直接パスワードが入るのはセキュリティとしてあまりに危険なため、ハッシュ値が入っています。wordpressのバージョンが2.5以前は<span style=\"color: #3366ff;\"><strong>md5</strong></span>で、それ以降は<span style=\"color: #ff6600;\"><strong>phpass</strong></span>でハッシュ値を生成しています。</p>\n<p>４：user_nicenameは管理画面に入る際のユーザ名になっています。似ているニックネームはwp_usermetaテーブルに入るので注意。</p>\n<p>５：user_emailはユーザ作成時に登録するメールアドレスがそのまま格納されます。</p>\n<p>６：user_urlは任意になりますが、/wp-admin/profile.php内だと、サイトと言う欄に当てはまります。</p>\n<p>７：user_registeredはユーザ登録時の日時が入ります。</p>\n<p>８：user_activation_key</p>\n<p></p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>wp_usermeta</h3>\n<!-- /wp:heading -->\n\n<p>wordpressのテーブル構造はざっくり分けると</p>\n<p>・投稿に関する情報が入るposts</p>\n<p>・ユーザ情報に関するusers</p>\n<p>・タームやタクソノミーに関するterms</p>\n<p>・コメントの情報が入るcomments</p>\n<p>・その他</p>\n<p>に分けられますが、いづれも〇〇metaと名付けられているテーブルは本来の用途以外に追加される拡張した情報が入るテーブルになります。</p>\n<p>そして、どのmetaテーブルもほぼ大体同じ構造をしており、メインで使われているテーブルとは一対多の関係になっています。</p>\n<p>usermetaテーブルもusersテーブルと一対多の関係になっており、このテーブルのuser_idはwp_usersテーブルのID外部キーになっています。</p>\n<p></p>\n<p></p>\n<p>usermetaテーブルには、usersテーブルには入りきらなかったユーザの追加情報が入ります。</p>\n<p>具体的にはユーザのプロフィール画面（/wp-admin/profile.php）の項目が入っています。</p>\n\n<!-- wp:html -->\n<table>\n<tr>\n<th>No</th>\n<th>物理名</th>\n<th>論理名</th>\n<th>型</th>\n<th>NULL</th>\n<th>Key</th>\n<th>デフォルト</th>\n<th>その他</th>\n</tr>\n<tr>\n<th>1</th>\n	<td>umeta_id</td>\n	<td>ユーザメタID</td>\n	<td>bigint(20) unsigned</td>\n	<td>NOT NULL</td>\n	<td>PRI</td>\n	<td>NULL</td>\n	<td>auto_increment</td>\n</tr>\n<tr>\n<th>2</th>\n	<td>user_id</td>\n	<td>ユーザID</td>\n	<td>bigint(20) unsigned</td>\n	<td>NOT NULL</td>\n	<td>MUL</td>\n	<td>0</td>\n	<td>wp_usersテーブルのIDの外部キー</td>\n</tr>\n<tr>\n<th>3</th>\n	<td>meta_key</td>\n	<td>カスタムフィールドのキー</td>\n	<td>varchar(255)</td>\n	<td></td>\n	<td>MUL</td>\n	<td>NULL</td>\n	<td></td>\n</tr>\n<tr>\n<th>1</th>\n	<td>meta_value</td>\n	<td>カスタムフィールドの値</td>\n	<td>longtext</td>\n	<td></td>\n	<td></td>\n	<td>NULL</td>\n	<td>シリアライズされた値が入ります</td>\n</tr>\n</table>\n<!-- /wp:html -->\n\n<p>１：ユーザメタIDは</p>\n<p>２：</p>\n<p>３：</p>\n<p>４：</p>\n<p></p>\n<p></p>\n\n<!-- wp:heading -->\n<h2>投稿に関するテーブル</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>wp_posts</h3>\n<!-- /wp:heading -->\n\n<p>postsテーブルに入るものはブログの投稿記事内のデータもそうですが、固定ページやメディア、カスタム投稿のデータ、ナビゲーションメニュー、リビジョンなど。</p>\n<p>ブログの投稿に限らずわりと広い意味で「投稿する」データが格納されます。</p>\n\n<!-- wp:html -->\n<table>\n<tr>\n<th>No</th>\n<th>物理名</th>\n<th>論理名</th>\n<th>型</th>\n<th>NULL</th>\n<th>Key</th>\n<th>デフォルト</th>\n<th>その他</th>\n</tr>\n<tr>\n<th>1</th>\n	<td>ID</td>\n	<td>投稿ID</td>\n	<td>bigint(20) unsigned</td>\n	<td>NOT NULL</td>\n	<td></td>\n	<td></td>\n	<td></td>\n</tr>\n<tr>\n<th>2</th>\n	<td>post_parent</td>\n	<td>親投稿ID</td>\n	<td>bigint(20) unsigned</td>\n	<td>NOT NULL</td>\n	<td></td>\n	<td></td>\n	<td></td>\n</tr>\n<tr>\n<th>3</th>\n	<td>post_author</td>\n	<td>筆者ID</td>\n	<td>bigint(20) unsigned</td>\n	<td>NOT NULL</td>\n	<td></td>\n	<td></td>\n	<td></td>\n</tr>\n<tr>\n<th>4</th>\n	<td>guid</td>\n	<td>グローバル一意識別子</td>\n	<td></td>\n	<td>NOT NULL</td>\n	<td></td>\n	<td></td>\n	<td></td>\n</tr>\n<tr>\n<th>5</th>\n	<td>post_date</td>\n	<td>公開日時</td>\n	<td>datetime</td>\n	<td>NOT NULL</td>\n	<td></td>\n	<td>0000-00-00 00:00:00</td>\n	<td></td>\n</tr>\n<tr>\n<th>6</th>\n	<td>post_date_gmt</td>\n	<td>公開日時（GMT）</td>\n	<td>datetime</td>\n	<td>NOT NULL</td>\n	<td></td>\n	<td>0000-00-00 00:00:00</td>\n	<td></td>\n</tr>\n<tr>\n<th>7</th>\n	<td>post_modified</td>\n	<td>更新日時</td>\n	<td>datetime</td>\n	<td>NOT NULL</td>\n	<td></td>\n	<td>0000-00-00 00:00:00</td>\n	<td></td>\n</tr>\n<tr>\n<th>8</th>\n	<td>post_modified_gmt</td>\n	<td>更新日時（GMT）</td>\n	<td>datetime</td>\n	<td>NOT NULL</td>\n	<td></td>\n	<td>0000-00-00 00:00:00</td>\n	<td></td>\n</tr>\n<tr>\n<th>9</th>\n	<td>post_name</td>\n	<td>スラッグ</td>\n	<td></td>\n	<td>NOT NULL</td>\n	<td></td>\n	<td></td>\n	<td></td>\n</tr>\n<tr>\n<th>10</th>\n	<td>post_title</td>\n	<td>タイトル</td>\n	<td>text</td>\n	<td>NOT NULL</td>\n	<td></td>\n	<td></td>\n	<td></td>\n</tr>\n<tr>\n<th>11</th>\n	<td>post_content</td>\n	<td>本文</td>\n	<td>longtext</td>\n	<td>NOT NULL</td>\n	<td></td>\n	<td></td>\n	<td></td>\n</tr>\n<tr>\n<th>12</th>\n	<td>post_content_filtered</td>\n	<td>フィルターされた本文</td>\n	<td></td>\n	<td>NOT NULL</td>\n	<td></td>\n	<td></td>\n	<td></td>\n</tr>\n<tr>\n<th>13</th>\n	<td>post_except</td>\n	<td>抜粋</td>\n	<td></td>\n	<td>NOT NULL</td>\n	<td></td>\n	<td></td>\n	<td></td>\n</tr>\n<tr>\n<th>14</th>\n	<td>post_status</td>\n	<td>公開状態</td>\n	<td>varchar(20)</td>\n	<td>NOT NULL</td>\n	<td></td>\n	<td></td>\n	<td></td>\n</tr>\n<tr>\n<th>15</th>\n	<td>post_password</td>\n	<td>閲覧パスワード</td>\n	<td></td>\n	<td>NOT NULL</td>\n	<td></td>\n	<td></td>\n	<td></td>\n</tr>\n<tr>\n<th>16</th>\n	<td>ping_status</td>\n	<td>ピンステータス</td>\n	<td></td>\n	<td>NOT NULL</td>\n	<td></td>\n	<td></td>\n	<td></td>\n</tr>\n<tr>\n<th>17</th>\n	<td>to_ping</td>\n	<td>ピン通知</td>\n	<td></td>\n	<td>NOT NULL</td>\n	<td></td>\n	<td></td>\n　　　　　<td></td>\n</tr>\n<tr>\n<th>18</th>\n	<td>pingd</td>\n	<td>ピン通知済み</td>\n	<td></td>\n	<td>NOT NULL</td>\n	<td></td>\n	<td></td>\n　　　　　<td></td>\n</tr>\n<tr>\n<th>19</th>\n	<td>comment_status</td>\n	<td>コメントステータス</td>\n	<td></td>\n	<td>NOT NULL</td>\n	<td></td>\n	<td></td>\n	<td></td>\n</tr>\n<tr>\n<th>20</th>\n	<td>comment_count</td>\n	<td>コメント数</td>\n	<td></td>\n	<td>NOT NULL</td>\n	<td></td>\n	<td></td>\n	<td></td>\n</tr>\n<tr>\n<th>21</th>\n	<td>menu_order</td>\n	<td>左メニュー位置</td>\n	<td></td>\n	<td>NOT NULL</td>\n	<td></td>\n	<td></td>\n	<td></td>\n</tr>\n<tr>\n<th>22</th>\n	<td>post_type</td>\n	<td>投稿タイプ</td>\n	<td></td>\n	<td>NOT NULL</td>\n	<td></td>\n	<td></td>\n	<td></td>\n</tr>\n<tr>\n<th>23</th>\n	<td>post_mime_type</td>\n	<td>MIMEタイプ</td>\n	<td></td>\n	<td>NOT NULL</td>\n	<td></td>\n	<td></td>\n	<td>(投稿タイプがattachmentの場合)</td>\n</tr>\n</table>\n<!-- /wp:html -->\n\n<p>１：投稿IDは各記事に自動的に付与されるID。これが一つ一つの記事を識別するため、ユニークであり、かつプライマリーキーにもなっています。</p>\n<p>２：親IDとは</p>\n<p>３：筆者IDはユーザごとに付与されてるID。</p>\n<p>４：guidとはidと書かれていますが、実際は</p>\n<p>５〜８：公開日時は新規作成時などに初めて公開した日時。更新日時は２回目以降に更新ボタンを押した日時。それぞれGMTがつくと</p>\n<p>９：スラッグはパーマリンク設定で随分変わりますが、その記事のドメイン以降のパスを設定できます。</p>\n<p>10 、11、13：タイトル、本文、抜粋はわかりやすく管理画面上から入力したものがこれらに入ります。</p>\n<p>12：フィルターされた本文というのは、</p>\n<p>14：この投稿記事が現在どういう状態なのかが入ります。</p>\n<p>publish =&gt; 公開されている</p>\n<p>close =&gt;非公開</p>\n<p>inhrbit =&gt;継承</p>\n<p>future =&gt; 予約公開</p>\n<p>draft =&gt;下書き保存</p>\n<p>auto-draft =&gt;自動保存</p>\n<p>trash =&gt; ゴミ箱に入ってる</p>\n<p></p>\n<p></p>\n<p>22：投稿タイプとは、どんな種類の投稿データなのかが入ります。具体的には</p>\n<p>⑴ post</p>\n<p>⑵ page</p>\n<p>⑶ attachment</p>\n<p>⑷ revision</p>\n<p>⑸ nav_menu_item</p>\n<p>⑹ カスタム投稿タイプ</p>\n<p>が入ります。それぞれ、</p>\n<p>⑴ post =&gt; 投稿内の記事</p>\n<p>⑵ page =&gt; 固定ページ内の記事</p>\n<p>⑶ attachment =&gt; メディア内のアップロードしたファイル(画像や音声など)</p>\n<p>アップロードしたファイルにはそれぞれ唯一無二のIDが付与されますが、post_parent（親ID）には添付先の投稿IDが入ります。</p>\n<p>⑷ revision =&gt; 過去の投稿の履歴の管理</p>\n<p>これも一つ一つのリビジョンのIDはユニークですが、それぞれの親IDは現在の投稿のIDになります。</p>\n<p>⑸ nav_menu_item =&gt; 外観メニューで設定している</p>\n<p>⑹ カスタム投稿タイプで設定したpost_typeの値</p>\n<p></p>\n<p>23：MIMEタイプとは、投稿タイプがattachmentの場合に入ってくる値で、そのファイルがどんな形式なのかが入ってきます。</p>\n<p>ex ) 画像なら<span class=\"s1\">image/png</span>、<span class=\"s1\">image/jpeg、</span><span class=\"s1\">image/jpg </span></p>\n<p>pdfなら、application/pdf</p>\n<p>音声なら、audio/vorbis、audio/mpeg</p>\n<p>といった具合に。</p>\n<p></p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>wp_postmeta</h3>\n<!-- /wp:heading -->\n\n<p>postmetaテーブルには投稿の追加情報（メタ情報）が入り、平たく言うと、主にカスタムフィールドの値が入ります。</p>\n<p>なお、postsテーブルとは一対多の関係になっており、このテーブルのpost_idはwp_postsテーブルのID外部キーになっています。</p>\n\n<!-- wp:html -->\n<table>\n<tr>\n<th>No</th>\n<th>物理名</th>\n<th>論理名</th>\n<th>型</th>\n<th>NULL</th>\n<th>Key</th>\n<th>デフォルト</th>\n<th>その他</th>\n</tr>\n<tr>\n<th>1</th>\n	<td>meta_id</td>\n	<td>メタID</td>\n	<td>bigint(20) unsigned</td>\n	<td>NOT NULL</td>\n	<td>PRI</td>\n	<td>NULL</td>\n	<td>auto_increment</td>\n</tr>\n<tr>\n<th>2</th>\n	<td>post_id</td>\n	<td>投稿ID</td>\n	<td>bigint(20) unsigned</td>\n	<td>NOT NULL</td>\n	<td>MUL</td>\n	<td>0</td>\n	<td>wp_postsテーブルのIDの外部キー</td>\n</tr>\n<tr>\n<th>1</th>\n	<td>meta_key</td>\n	<td>カスタムフィールドのキー</td>\n	<td>varchar(255)</td>\n	<td></td>\n	<td>MUL</td>\n	<td>NULL</td>\n	<td></td>\n</tr>\n<tr>\n<th>1</th>\n	<td>meta_value</td>\n	<td>カスタムフィールドの値</td>\n	<td>longtext</td>\n	<td></td>\n	<td></td>\n	<td>NULL</td>\n	<td>シリアライズされた値が入ります</td>\n</tr>\n</table>\n<!-- /wp:html -->\n\n<p></p>\n<p></p>\n\n<!-- wp:heading -->\n<h2>分類に関するテーブル</h2>\n<!-- /wp:heading -->\n\n<p>wordpressのメイン機能であるブログ記事や固定ページは何らかのグループ分けにより一覧表示できます。</p>\n<p>デフォルトではカテゴリーとタグがすでにありますが、その他自分で作るカスタムタクソノミーもこれらのテーブルに入ります。</p>\n<p>termに関するテーブルはデフォルトでは全部で4つあります。</p>\n<p> </p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>wp_term_relationships</h3>\n<!-- /wp:heading -->\n\n<p>wp_term_relationshipsはwp_posts、wp_linksとwp_term_taxonomyテーブルを繋ぐ中間テーブルになります。</p>\n<p>なお、このテーブルは多対多の関係です</p>\n<p> </p>\n<p> </p>\n\n<!-- wp:html -->\n<table>\n<tr>\n<th>No</th>\n<th>物理名</th>\n<th>論理名</th>\n<th>型</th>\n<th>NULL</th>\n<th>Key</th>\n<th>デフォルト</th>\n<th>その他</th>\n</tr>\n<tr>\n<th>1</th>\n	<td>object_id</td>\n	<td>オブジェクトID</td>\n	<td>bigint(20) unsigned</td>\n	<td>NOT NULL</td>\n	<td>PRI</td>\n	<td>NULL</td>\n	<td>auto_increment</td>\n</tr>\n<tr>\n<th>2</th>\n	<td>term_taxonomy_id</td>\n	<td>タームタクソノミーID</td>\n	<td>bigint(20) unsigned</td>\n	<td>NOT NULL</td>\n	<td>PRI</td>\n	<td>0</td>\n	<td></td>\n</tr>\n<tr>\n<th>1</th>\n	<td>meta_key</td>\n	<td>ターム順</td>\n	<td>int(11)</td>\n	<td></td>\n	<td></td>\n	<td>0</td>\n	<td></td>\n</tr>\n</table>\n<!-- /wp:html -->\n\n<p>1：オブジェクトIDはwp_postsの投稿IDかwp_linksのlink_idが入るので、この二つの外部キーになっています。</p>\n<p>２：</p>\n<p></p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>wp_term_taxonomy</h3>\n<!-- /wp:heading -->\n\n<p>このテーブルは</p>\n\n<!-- wp:html -->\n<table>\n<tr>\n<th>No</th>\n<th>物理名</th>\n<th>論理名</th>\n<th>型</th>\n<th>NULL</th>\n<th>Key</th>\n<th>デフォルト</th>\n<th>その他</th>\n</tr>\n<tr>\n<th>1</th>\n	<td>object_id</td>\n	<td>オブジェクトID</td>\n	<td>bigint(20) unsigned</td>\n	<td>NOT NULL</td>\n	<td>PRI</td>\n	<td>NULL</td>\n	<td>auto_increment</td>\n</tr>\n<tr>\n<th>2</th>\n	<td>term_taxonomy_id</td>\n	<td>タームタクソノミーID</td>\n	<td>bigint(20) unsigned</td>\n	<td>NOT NULL</td>\n	<td>PRI</td>\n	<td>0</td>\n	<td>wp_postsテーブルのIDの外部キー</td>\n</tr>\n<tr>\n<th>1</th>\n	<td>meta_key</td>\n	<td>ターム順</td>\n	<td>int(11)</td>\n	<td></td>\n	<td></td>\n	<td>0</td>\n	<td></td>\n</tr>\n</table>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>wp_terms</h3>\n<!-- /wp:heading -->\n\n<p>termsテーブルには</p>\n<p>カテゴリー、タグ、カスタムタクソノミー</p>\n<p>/wp-admin/edit-tags.php?taxonomy=category</p>\n<p>で入力した一つ一つのタームの詳細情報が格納されます。</p>\n<p></p>\n\n<!-- wp:html -->\n<table>\n<tr>\n<th>No</th>\n<th>物理名</th>\n<th>論理名</th>\n<th>型</th>\n<th>NULL</th>\n<th>Key</th>\n<th>デフォルト</th>\n<th>その他</th>\n</tr>\n<tr>\n<th>1</th>\n	<td>term_id</td>\n	<td>タームID</td>\n	<td>bigint(20) unsigned</td>\n	<td>NOT NULL</td>\n	<td>PRI</td>\n	<td>NULL</td>\n	<td>auto_increment</td>\n</tr>\n<tr>\n<th>2</th>\n	<td>name</td>\n	<td>ターム名</td>\n	<td>varchar(200)</td>\n	<td>NOT NULL</td>\n	<td>MUL</td>\n	<td></td>\n	<td></td>\n</tr>\n<tr>\n<th>3</th>\n	<td>slug</td>\n	<td>スラッグ</td>\n	<td>varchar(200)</td>\n	<td>NOT NULL</td>\n	<td></td>\n	<td>0</td>\n	<td></td>\n</tr>\n<tr>\n<th>4</th>\n	<td>term_group</td>\n	<td>タームのグループ</td>\n	<td>bigint(10)</td>\n	<td>NOT NULL</td>\n	<td></td>\n	<td>0</td>\n	<td></td>\n</tr>\n</table>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>wp_termmeta</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2>コメントに関するテーブル</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>wp_commentmeta</h3>\n<!-- /wp:heading -->\n\n<!-- wp:html -->\n<table>\n<tr>\n<th>No</th>\n<th>物理名</th>\n<th>論理名</th>\n<th>型</th>\n<th>NULL</th>\n<th>Key</th>\n<th>デフォルト</th>\n<th>その他</th>\n</tr>\n<tr>\n<th>1</th>\n	<td>meta_id</td>\n	<td>メタID</td>\n	<td>bigint(20) unsigned</td>\n	<td>NOT NULL</td>\n	<td>PRI</td>\n	<td>NULL</td>\n	<td>auto_increment</td>\n</tr>\n<tr>\n<th>2</th>\n	<td>comment_id</td>\n	<td>コメントID</td>\n	<td>bigint(20) unsigned</td>\n	<td>NOT NULL</td>\n	<td>MUL</td>\n	<td>0</td>\n	<td>wp_commentsテーブルのIDの外部キー</td>\n</tr>\n<tr>\n<th>3</th>\n	<td>meta_key</td>\n	<td>のキー</td>\n	<td>varchar(255)</td>\n	<td></td>\n	<td>MUL</td>\n	<td>NULL</td>\n	<td></td>\n</tr>\n<tr>\n<th>4</th>\n	<td>meta_value</td>\n	<td>カスタムフィールドの値</td>\n	<td>longtext</td>\n	<td></td>\n	<td></td>\n	<td>NULL</td>\n	<td>シリアライズされた値が入ります</td>\n</tr>\n</table>\n<!-- /wp:html -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>wp_comments</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2>その他のテーブル</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>wp_options</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>wp_links</h3>\n<!-- /wp:heading -->\n\n<p>一応あるんですが、現在コアではほとんど使われていないため、</p>\n\n<!-- wp:heading -->\n<h2>各テーブルと使われているページのまとめ</h2>\n<!-- /wp:heading -->','wordpressのテーブルについて','wordpressのテーブルとカラムついてのまとめ。','inherit','closed','closed','','1767-autosave-v1','','','2019-05-20 18:44:08','2019-05-20 09:44:08','',1767,'http://localhost:8080/anothor/1767-autosave-v1',0,'revision','',0),(2055,1,'2019-05-21 13:24:15','2019-05-21 04:24:15','<!-- wp:heading -->\n<h2> wordpressにおけるwp-setting.phpとは </h2>\n<!-- /wp:heading -->\n\n<p>wp-setting.phpはwordpressのコアファイルを読み込んでいく際のおよそ3番目に読まれるファイルになります。</p>\n<p>wp-load.php</p>\n<p>↓</p>\n<p>wp-config.php</p>\n<p>↓</p>\n<p><strong><span style=\"color: #ff0000;\">wp-setting.php</span></strong></p>\n<p>↓</p>\n<p>wordpressのコアファイル群</p>\n<p></p>\n<p>wp-setting.phpで行っていることはざっくりいうと、wordpressを起動させる際の設定をし、コアファイルたちを次々実行していき実質的にwordpressを起動させるファイルになります。</p>\n<p></p>\n<p></p>\n\n<!-- wp:heading -->\n<h2> 実際に翻訳してみた </h2>\n<!-- /wp:heading -->\n\n<p>長いので、400行ちょっとあるファイルなので行っている処理ごとに分割していきます。</p>\n<p></p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>冒頭～メンテナンスモードまで</h3>\n<!-- /wp:heading -->\n\n<p>行数でいえば、最初から70行目あたりまで。</p>\n<p>wp_debug_mode();という関数があるとこまでです。</p>\n<pre class=\"lang:php decode:true\" title=\"wp-setting.php\">&lt;?php\n/**\n * 一般的な変数を設定および修正するために使用され、\n * WordPressの手続き型およびクラスライブラリを含みます。\n *\n * wp-config.phpでの設定を許可します（default-constants.phpを参照）\n *\n * @package WordPress\n */\n\n/**\n * WordPressの関数、クラス、およびコアコンテンツのディレクトリの場所を格納します。\n *\n * @since 1.0.0\n */\n\n//「WPINC」をwp-includesディレクトリと定義する\ndefine( \'WPINC\', \'wp-includes\' );\n\n// 初期化に必要なファイルを含めます。\nrequire( ABSPATH . WPINC . \'/load.php\' );\nrequire( ABSPATH . WPINC . \'/default-constants.php\' );\nrequire_once( ABSPATH . WPINC . \'/plugin.php\' );\n\n/*\n * これらはversion.phpで直接グローバル化することはできません。 更新するとき、\n * 私たちは他のインストールからのversion.phpをインクルードしています。\n * そしてすでに設定されているならこれらの値を上書きされたくないです。\n */\n\n//以下の変数をグローバル宣言する\nglobal $wp_version, $wp_db_version, $tinymce_version, $required_php_version, $required_mysql_version, $wp_local_package;\n//ドキュメントルート/wp-includes/version.phpを読み込む\nrequire( ABSPATH . WPINC . \'/version.php\' );\n\n/**\n * まだ設定されていない場合 blog_idは単一サイト設定でデフォルトの1になります。\n * マルチサイトでは、ms-settings.phpでデフォルトで上書きされます。\n *\n * @global int $blog_id\n * @since 2.0.0\n */\n//\nglobal $blog_id;\n\n// WP_MEMORY_LIMIT、WP_MAX_MEMORY_LIMIT、WP_DEBUG、SCRIPT_DEBUG、WP_CONTENT_DIRおよびWP_CACHEを含む初期デフォルト定数を設定します。\nwp_initial_constants();\n\n// 必要なPHPバージョンとMySQLエクステンションまたはデータベースドロップインをチェックしてください。\nwp_check_php_mysql_versions();\n\n// 実行時にマジッククォートを無効にします。魔法の引用符は後でwp-settings.phpでwpdbを使って追加されます\n@ini_set( \'magic_quotes_runtime\', 0 );\n@ini_set( \'magic_quotes_sybase\', 0 );\n\n// WordPressはUTCからのオフセットを計算します。\ndate_default_timezone_set( \'UTC\' );\n\n// register_globalsをオフにします。\nwp_unregister_GLOBALS();\n\n// 設定間で$ _SERVER変数を標準化します。\nwp_fix_server_vars();\n\n// favicon.icoが見つからないため、リクエストを受信したかどうかを確認します\nwp_favicon_request();\n\n// メンテナンスモードになっているか確認してください。\nwp_maintenance();\n</pre>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>メンテナンスモード～ コアファイルの読み込みまで </h3>\n<!-- /wp:heading -->\n\n<p>行数でいえば、最初から71～152行目あたりまで。</p>\n<p>wp_not_installed();という関数があるとこまでです。</p>\n<p></p>\n<p>&nbsp;</p>\n<pre class=\"\">// タイマーをロードします。\ntimer_start();\n\n// WP_DEBUGモードになっているか確認してください。\nwp_debug_mode();\n\n/**\n * advanced-cache.phpドロップインのロードを有効にするかどうかをフィルタリングします。\n *\n * このフィルタはプラグインによって使用される前に実行されます。 Web以外のランタイム用に設計されています。\n * falseが返された場合、advanced-cache.phpはロードされません。\n *\n * @since 4.6.0\n *\n * @param bool $enable_advanced_cache_advanced-cache.php（存在する場合）の読み込みを有効にするかどうか\n *                                    Default true.\n */\n\nif ( WP_CACHE &amp;&amp; apply_filters( \'enable_loading_advanced_cache_dropin\', true ) ) {\n	// 高度なキャッシングプラグインを使うために。必要なのは静的ドロップインだけです。\n	WP_DEBUG ? include( WP_CONTENT_DIR . \'/advanced-cache.php\' ) : @include( WP_CONTENT_DIR . \'/advanced-cache.php\' );\n\n	// advanced-cache.phpによって手動で追加されたフックを再初期化します\n	if ( $wp_filter ) {\n		$wp_filter = WP_Hook::build_preinitialized_hooks( $wp_filter );\n	}\n}\n\n// 設定されていない場合はWP_LANG_DIRを定義します。\nwp_set_lang_dir();\n\n// 初期のWordPressファイルを読み込む.\nrequire( ABSPATH . WPINC . \'/compat.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-list-util.php\' );\nrequire( ABSPATH . WPINC . \'/formatting.php\' );\nrequire( ABSPATH . WPINC . \'/meta.php\' );\nrequire( ABSPATH . WPINC . \'/functions.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-meta-query.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-matchesmapregex.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-error.php\' );\nrequire( ABSPATH . WPINC . \'/pomo/mo.php\' );\n\n// wpdbクラスと、存在する場合はdb.phpデータベースドロップインを含めます。\nglobal $wpdb;\nrequire_wp_db();\n\n// データベーステーブルのプレフィックスとデータベーステーブル列のフォーマット指定子を設定します。\n$GLOBALS[\'table_prefix\'] = $table_prefix;\nwp_set_wpdb_vars();\n\n// WordPressオブジェクトキャッシュ、またはドロップインが存在する場合は外部オブジェクトキャッシュを起動します。\nwp_start_object_cache();\n\n// デフォルトのフィルタを添付してください。\nrequire( ABSPATH . WPINC . \'/default-filters.php\' );\n\n// 有効な場合はマルチサイトを初期化します。\nif ( is_multisite() ) {\n	require( ABSPATH . WPINC . \'/class-wp-site-query.php\' );\n	require( ABSPATH . WPINC . \'/class-wp-network-query.php\' );\n	require( ABSPATH . WPINC . \'/ms-blogs.php\' );\n	require( ABSPATH . WPINC . \'/ms-settings.php\' );\n} elseif ( ! defined( \'MULTISITE\' ) ) {\n	define( \'MULTISITE\', false );\n}\n\n//関数：shutdown_action_hookをシャットダウン時に実行する\nregister_shutdown_function( \'shutdown_action_hook\' );\n\n// 基本的な機能を使いたいだけなら、大半のWordPressをロードしないようにしてください。\nif ( SHORTINIT ) {\n	return false;\n}\n\n// L10nライブラリをロードする\nrequire_once( ABSPATH . WPINC . \'/l10n.php\' );\nrequire_once( ABSPATH . WPINC . \'/class-wp-locale.php\' );\nrequire_once( ABSPATH . WPINC . \'/class-wp-locale-switcher.php\' );\n\n// WordPressがインストールされていない場合はインストーラを実行してください\nwp_not_installed();\n</pre>\n<p>&nbsp;</p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3> コアファイルの読み込み ～ まで</h3>\n<!-- /wp:heading -->\n\n<pre class=\"\"><!--?php\n/**\n * 一般的な変数を設定および修正するために使用され、\n * WordPressの手続き型およびクラスライブラリを含みます。\n *\n * wp-config.phpでの設定を許可します（default-constants.phpを参照）\n *\n * @package WordPress\n */\n\n/**\n * WordPressの関数、クラス、およびコアコンテンツのディレクトリの場所を格納します。\n *\n * @since 1.0.0\n */\n\n//「WPINC」をwp-includesディレクトリと定義する\ndefine( \'WPINC\', \'wp-includes\' );\n\n// 初期化に必要なファイルを含めます。\nrequire( ABSPATH . WPINC . \'/load.php\' );\nrequire( ABSPATH . WPINC . \'/default-constants.php\' );\nrequire_once( ABSPATH . WPINC . \'/plugin.php\' );\n\n/*\n * これらはversion.phpで直接グローバル化することはできません。 更新するとき、\n * 私たちは他のインストールからのversion.phpをインクルードしています。\n * そしてすでに設定されているならこれらの値を上書きされたくないです。\n */\n\n//以下の変数をグローバル宣言する\nglobal $wp_version, $wp_db_version, $tinymce_version, $required_php_version, $required_mysql_version, $wp_local_package;\n//ドキュメントルート/wp-includes/version.phpを読み込む\nrequire( ABSPATH . WPINC . \'/version.php\' );\n\n/**\n * まだ設定されていない場合 blog_idは単一サイト設定でデフォルトの1になります。\n * マルチサイトでは、ms-settings.phpでデフォルトで上書きされます。\n *\n * @global int $blog_id\n * @since 2.0.0\n */\n//\nglobal $blog_id;\n\n// WP_MEMORY_LIMIT、WP_MAX_MEMORY_LIMIT、WP_DEBUG、SCRIPT_DEBUG、WP_CONTENT_DIRおよびWP_CACHEを含む初期デフォルト定数を設定します。\nwp_initial_constants();\n\n// 必要なPHPバージョンとMySQLエクステンションまたはデータベースドロップインをチェックしてください。\nwp_check_php_mysql_versions();\n\n// 実行時にマジッククォートを無効にします。魔法の引用符は後でwp-settings.phpでwpdbを使って追加されます\n@ini_set( \'magic_quotes_runtime\', 0 );\n@ini_set( \'magic_quotes_sybase\', 0 );\n\n// WordPressはUTCからのオフセットを計算します。\ndate_default_timezone_set( \'UTC\' );\n\n// register_globalsをオフにします。\nwp_unregister_GLOBALS();\n\n// 設定間で$ _SERVER変数を標準化します。\nwp_fix_server_vars();\n\n// favicon.icoが見つからないため、リクエストを受信したかどうかを確認します\nwp_favicon_request();\n\n// メンテナンスモードになっているか確認してください。\nwp_maintenance();\n\n// タイマーをロードします。\ntimer_start();\n\n// WP_DEBUGモードになっているか確認してください。\nwp_debug_mode();\n\n/**\n * advanced-cache.phpドロップインのロードを有効にするかどうかをフィルタリングします。\n *\n * このフィルタはプラグインによって使用される前に実行されます。 Web以外のランタイム用に設計されています。\n * falseが返された場合、advanced-cache.phpはロードされません。\n *\n * @since 4.6.0\n *\n * @param bool $enable_advanced_cache_advanced-cache.php（存在する場合）の読み込みを有効にするかどうか\n *                                    Default true.\n */\n\nif ( WP_CACHE && apply_filters( \'enable_loading_advanced_cache_dropin\', true ) ) {\n	// 高度なキャッシングプラグインを使うために。必要なのは静的ドロップインだけです。\n	WP_DEBUG ? include( WP_CONTENT_DIR . \'/advanced-cache.php\' ) : @include( WP_CONTENT_DIR . \'/advanced-cache.php\' );\n\n	// advanced-cache.phpによって手動で追加されたフックを再初期化します\n	if ( $wp_filter ) {\n		$wp_filter = WP_Hook::build_preinitialized_hooks( $wp_filter );\n	}\n}\n\n// 設定されていない場合はWP_LANG_DIRを定義します。\nwp_set_lang_dir();\n\n// 初期のWordPressファイルを読み込む.\nrequire( ABSPATH . WPINC . \'/compat.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-list-util.php\' );\nrequire( ABSPATH . WPINC . \'/formatting.php\' );\nrequire( ABSPATH . WPINC . \'/meta.php\' );\nrequire( ABSPATH . WPINC . \'/functions.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-meta-query.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-matchesmapregex.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-error.php\' );\nrequire( ABSPATH . WPINC . \'/pomo/mo.php\' );\n\n// wpdbクラスと、存在する場合はdb.phpデータベースドロップインを含めます。\nglobal $wpdb;\nrequire_wp_db();\n\n// データベーステーブルのプレフィックスとデータベーステーブル列のフォーマット指定子を設定します。\n$GLOBALS[\'table_prefix\'] = $table_prefix;\nwp_set_wpdb_vars();\n\n// WordPressオブジェクトキャッシュ、またはドロップインが存在する場合は外部オブジェクトキャッシュを起動します。\nwp_start_object_cache();\n\n// デフォルトのフィルタを添付してください。\nrequire( ABSPATH . WPINC . \'/default-filters.php\' );\n\n// 有効な場合はマルチサイトを初期化します。\nif ( is_multisite() ) {\n	require( ABSPATH . WPINC . \'/class-wp-site-query.php\' );\n	require( ABSPATH . WPINC . \'/class-wp-network-query.php\' );\n	require( ABSPATH . WPINC . \'/ms-blogs.php\' );\n	require( ABSPATH . WPINC . \'/ms-settings.php\' );\n} elseif ( ! defined( \'MULTISITE\' ) ) {\n	define( \'MULTISITE\', false );\n}\n\n//関数：shutdown_action_hookをシャットダウン時に実行する\nregister_shutdown_function( \'shutdown_action_hook\' );\n\n// 基本的な機能を使いたいだけなら、大半のWordPressをロードしないようにしてください。\nif ( SHORTINIT ) {\n	return false;\n}\n\n// L10nライブラリをロードする\nrequire_once( ABSPATH . WPINC . \'/l10n.php\' );\nrequire_once( ABSPATH . WPINC . \'/class-wp-locale.php\' );\nrequire_once( ABSPATH . WPINC . \'/class-wp-locale-switcher.php\' );\n\n// WordPressがインストールされていない場合はインストーラを実行してください\nwp_not_installed();\n\n// WordPressコアファイルの大半をロードする\nrequire( ABSPATH . WPINC . \'/class-wp-walker.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-ajax-response.php\' );\nrequire( ABSPATH . WPINC . \'/capabilities.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-roles.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-role.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-user.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-query.php\' );\nrequire( ABSPATH . WPINC . \'/query.php\' );\nrequire( ABSPATH . WPINC . \'/date.php\' );\nrequire( ABSPATH . WPINC . \'/theme.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-theme.php\' );\nrequire( ABSPATH . WPINC . \'/template.php\' );\nrequire( ABSPATH . WPINC . \'/user.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-user-query.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-session-tokens.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-user-meta-session-tokens.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-metadata-lazyloader.php\' );\nrequire( ABSPATH . WPINC . \'/general-template.php\' );\nrequire( ABSPATH . WPINC . \'/link-template.php\' );\nrequire( ABSPATH . WPINC . \'/author-template.php\' );\nrequire( ABSPATH . WPINC . \'/post.php\' );\nrequire( ABSPATH . WPINC . \'/class-walker-page.php\' );\nrequire( ABSPATH . WPINC . \'/class-walker-page-dropdown.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-post-type.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-post.php\' );\nrequire( ABSPATH . WPINC . \'/post-template.php\' );\nrequire( ABSPATH . WPINC . \'/revision.php\' );\nrequire( ABSPATH . WPINC . \'/post-formats.php\' );\nrequire( ABSPATH . WPINC . \'/post-thumbnail-template.php\' );\nrequire( ABSPATH . WPINC . \'/category.php\' );\nrequire( ABSPATH . WPINC . \'/class-walker-category.php\' );\nrequire( ABSPATH . WPINC . \'/class-walker-category-dropdown.php\' );\nrequire( ABSPATH . WPINC . \'/category-template.php\' );\nrequire( ABSPATH . WPINC . \'/comment.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-comment.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-comment-query.php\' );\nrequire( ABSPATH . WPINC . \'/class-walker-comment.php\' );\nrequire( ABSPATH . WPINC . \'/comment-template.php\' );\nrequire( ABSPATH . WPINC . \'/rewrite.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-rewrite.php\' );\nrequire( ABSPATH . WPINC . \'/feed.php\' );\nrequire( ABSPATH . WPINC . \'/bookmark.php\' );\nrequire( ABSPATH . WPINC . \'/bookmark-template.php\' );\nrequire( ABSPATH . WPINC . \'/kses.php\' );\nrequire( ABSPATH . WPINC . \'/cron.php\' );\nrequire( ABSPATH . WPINC . \'/deprecated.php\' );\nrequire( ABSPATH . WPINC . \'/script-loader.php\' );\nrequire( ABSPATH . WPINC . \'/taxonomy.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-taxonomy.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-term.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-term-query.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-tax-query.php\' );\nrequire( ABSPATH . WPINC . \'/update.php\' );\nrequire( ABSPATH . WPINC . \'/canonical.php\' );\nrequire( ABSPATH . WPINC . \'/shortcodes.php\' );\nrequire( ABSPATH . WPINC . \'/embed.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-embed.php\' );\nrequire( ABSPATH . WPINC . \'/class-oembed.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-oembed-controller.php\' );\nrequire( ABSPATH . WPINC . \'/media.php\' );\nrequire( ABSPATH . WPINC . \'/http.php\' );\nrequire( ABSPATH . WPINC . \'/class-http.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-streams.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-curl.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-proxy.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-cookie.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-encoding.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-response.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-requests-response.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-requests-hooks.php\' );\nrequire( ABSPATH . WPINC . \'/widgets.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-widget.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-widget-factory.php\' );\nrequire( ABSPATH . WPINC . \'/nav-menu.php\' );\nrequire( ABSPATH . WPINC . \'/nav-menu-template.php\' );\nrequire( ABSPATH . WPINC . \'/admin-bar.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/class-wp-rest-server.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/class-wp-rest-response.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/class-wp-rest-request.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-posts-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-attachments-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-post-types-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-post-statuses-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-revisions-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-autosaves-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-taxonomies-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-terms-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-users-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-comments-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-search-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-blocks-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-block-renderer-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-settings-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-themes-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-comment-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-post-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-term-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-user-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/search/class-wp-rest-search-handler.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/search/class-wp-rest-post-search-handler.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-block-type.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-block-type-registry.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-block-parser.php\' );\nrequire( ABSPATH . WPINC . \'/blocks.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/archives.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/block.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/categories.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/latest-comments.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/latest-posts.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/shortcode.php\' );\n\n$GLOBALS[\'wp_embed\'] = new WP_Embed();\n\n// マルチサイト固有のファイルをロードします。\nif ( is_multisite() ) {\n	require( ABSPATH . WPINC . \'/ms-functions.php\' );\n	require( ABSPATH . WPINC . \'/ms-default-filters.php\' );\n	require( ABSPATH . WPINC . \'/ms-deprecated.php\' );\n}\n\n// デフォルト値を取得するためにAPIに依存する定数を定義します。\n// sunrise.phpドロップインで上書きされる可能性のある、必ず使用するプラグインディレクトリ定数を定義します。.\nwp_plugin_directory_constants();\n\n$GLOBALS[\'wp_plugin_paths\'] = array();\n\n// マストユーズプラグインをロードします\nforeach ( wp_get_mu_plugins() as $mu_plugin ) {\n	include_once( $mu_plugin );\n\n	/**\n	 * 一つのマストユーズプラグインがロードされたら起動する\n	 *\n	 * @since 5.1.0\n	 *\n	 * @param string $mu_plugin Full path to the plugin\'s main file.\n	 */\n	do_action( \'mu_plugin_loaded\', $mu_plugin );\n}\nunset( $mu_plugin );\n\n// ネットワーク起動プラグインをロードします\nif ( is_multisite() ) {\n	foreach ( wp_get_active_network_plugins() as $network_plugin ) {\n		wp_register_plugin_realpath( $network_plugin );\n		include_once( $network_plugin );\n\n		/**\n		 * 一つのネットワーク起動プラグインがロードされたら起動する\n		 *\n		 * @since 5.1.0\n		 *\n		 * @param string $network_plugin Full path to the plugin\'s main file.\n		 */\n		do_action( \'network_plugin_loaded\', $network_plugin );\n	}\n	unset( $network_plugin );\n}\n\n/**\n * すべての必須使用およびネットワーク起動プラグインがロードされると起動します。\n *\n * @since 2.8.0\n */\n\n//関数：muplugins_loadedを実行する\ndo_action( \'muplugins_loaded\' );\n\nif ( is_multisite() ) {\n	ms_cookie_constants();\n}\n\n// マルチサイトがロードされた後に定数を定義します。\nwp_cookie_constants();\n\n// SSL定数を定義して実施する\nwp_ssl_constants();\n\n// 共通グローバルを作成する\nrequire( ABSPATH . WPINC . \'/vars.php\' );\n\n// タクソノミーや投稿をプラグインやテーマで利用できるようにします。\n// @プラグインの作成者：警告：これらはinitフックに再度登録されます。\ncreate_initial_taxonomies();\ncreate_initial_post_types();\n\nwp_start_scraping_edited_file_errors();\n\n// デフォルトのテーマディレクトリのルートを登録する\nregister_theme_directory( get_theme_root() );\n\n// 有効化されてるプラグインをよみこむ\nforeach ( wp_get_active_and_valid_plugins() as $plugin ) {\n	wp_register_plugin_realpath( $plugin );\n	include_once( $plugin );\n\n	/**\n	 * 一度有効化されたプラグインをよみこむと起動する\n	 *\n	 * @since 5.1.0\n	 *\n	 * @param string $plugin Full path to the plugin\'s main file.\n	 */\n	do_action( \'plugin_loaded\', $plugin );\n}\nunset( $plugin );\n\n// プラガブル関数を読み込む.\nrequire( ABSPATH . WPINC . \'/pluggable.php\' );\nrequire( ABSPATH . WPINC . \'/pluggable-deprecated.php\' );\n\n// 内部エンコーディングを設定します。\nwp_set_internal_encoding();\n\n// オブジェクトキャッシュが有効で、関数が存在する場合は、wp_cache_postload（）を実行する\nif ( WP_CACHE && function_exists( \'wp_cache_postload\' ) ) {\n	wp_cache_postload();\n}\n\n/**\n * 一度有効化されたプラグインをよみこむと起動する\n *\n * 読み込まれているこの時点でプラガブル機能も利用可能です。\n *\n * @since 1.5.0\n */\ndo_action( \'plugins_loaded\' );\n\n// まだ定義されていない場合、機能に影響を与える定数を定義します。\nwp_functionality_constants();\n\n// マジッククオートを追加して$ _REQUEST（$ _GET + $ _POST）を設定する\nwp_magic_quotes();\n\n/**\n * コメントクッキーがサニタイズされたときに起動します。\n *\n * @since 2.0.11\n */\ndo_action( \'sanitize_comment_cookies\' );\n\n/**\n * WordPress Query object\n *\n * @global WP_Query $wp_the_query\n * @since 2.0.0\n */\n$GLOBALS[\'wp_the_query\'] = new WP_Query();\n\n/**\n * $ wp_the_queryへの参照を保持しています\n * WordPressクエリにこのグローバルを使用\n *\n * @global WP_Query $wp_query\n * @since 1.5.0\n */\n$GLOBALS[\'wp_query\'] = $GLOBALS[\'wp_the_query\'];\n\n/**\n * きれいなURLを作成するためのWordPressリライトオブジェクトを保持します。\n * @global WP_Rewrite $wp_rewrite\n * @since 1.5.0\n */\n$GLOBALS[\'wp_rewrite\'] = new WP_Rewrite();\n\n/**\n * WordPress オブジェクト\n *\n * @global WP $wp\n * @since 2.0.0\n */\n$GLOBALS[\'wp\'] = new WP();\n\n/**\n * WordPress Widget Factory Object\n *\n * @global WP_Widget_Factory $wp_widget_factory\n * @since 2.8.0\n */\n$GLOBALS[\'wp_widget_factory\'] = new WP_Widget_Factory();\n\n/**\n * WordPress User Roles\n *\n * @global WP_Roles $wp_roles\n * @since 2.0.0\n */\n$GLOBALS[\'wp_roles\'] = new WP_Roles();\n\n/**\n * テーマが読み込まれる前に発生します。\n *\n * @since 2.6.0\n */\ndo_action( \'setup_theme\' );\n\n// テンプレート関連定数を定義します。\nwp_templating_constants();\n\n// デフォルトのテキストローカライゼーションドメインを読み込む。\nload_default_textdomain();\n\n$locale      = get_locale();\n$locale_file = WP_LANG_DIR . \"/$locale.php\";\nif ( ( 0 === validate_file( $locale ) ) && is_readable( $locale_file ) ) {\n	require( $locale_file );\n}\nunset( $locale_file );\n\n/**\n * ロケールドメインの日付とさまざまな文字列をロードするためのWordPress Localeオブジェクト。\n *\n * @global WP_Locale $wp_locale\n * @since 2.1.0\n */\n$GLOBALS[\'wp_locale\'] = new WP_Locale();\n\n/**\n *  ロケールを切り替えるためのWordPress Locale Switcherオブジェクト\n *\n * @since 4.7.0\n *\n * @global WP_Locale_Switcher $ wp_locale_switcher WordPressロケール切り替えオブジェクト。\n */\n$GLOBALS[\'wp_locale_switcher\'] = new WP_Locale_Switcher();\n$GLOBALS[\'wp_locale_switcher\']--->init();\n\n// 該当する場合は、親テーマと子テーマの両方について、アクティブなテーマの機能をロードします。\nforeach ( wp_get_active_and_valid_themes() as $theme ) {\n	if ( file_exists( $theme . \'/functions.php\' ) ) {\n		include $theme . \'/functions.php\';\n	}\n}\nunset( $theme );\n\n/**\n * テーマが読まれた後に起動する\n *\n * @since 3.0.0\n */\ndo_action( \'after_setup_theme\' );\n\n// 現在のユーザーを設定します。\n$GLOBALS[\'wp\']-&gt;init();\n\n/**\n * WordPressの読み込みが完了した後、ヘッダーが送信される前に起動ます。\n *\n * WPの大部分はこの段階でロードされ、ユーザーは認証されます。\n * WPは{@see \'init\'}フック（例えばウィジェット）に読み込みそれに続いて読み込まれます、多くのプラグインがインスタンス化します\n * WP自身はあらゆる種類の理由で分類します。（例えば、ユーザー、タクソノミーなど）\n *\n * WPがロードされた後にアクションをプラグインしたい場合は、以下の{@see \'wp_loaded\'}フックを使用してください。\n *\n * @since 1.5.0\n */\ndo_action( \'init\' );\n\n// マルチサイトの場合\nif ( is_multisite() ) {\n	if ( true !== ( $file = ms_site_check() ) ) {\n		require( $file );\n		die();\n	}\n	unset( $file );\n}\n\n/**\n * このフックは、WP、すべてのプラグイン、およびテーマが完全に読み込まれてインスタンス化されると起動します。\n *\n * Ajaxリクエストはwp-admin / admin-ajax.phpを使うべきです。\n * ajax.phpは、ログインしていないユーザーに対するリクエストを処理できます。\n * @link https://codex.wordpress.org/AJAX_in_Plugins\n *\n * @since 3.0.0\n */\ndo_action( \'wp_loaded\' );\n\n</pre>\n\n<!-- wp:heading {\"level\":3} -->\n<h3></h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2> まとめ：このファイルで行ってること </h2>\n<!-- /wp:heading -->\n\n<p>・</p>\n\n<!-- wp:heading -->\n<h2> おまけ：このファイルで使われた関数 </h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3> php関数 </h3>\n<!-- /wp:heading -->\n\n<p>date_default_timezone_set( \'UTC\' );</p>\n<p></p>\n<p>register_shutdown_function( \'関数名\' );</p>\n<p>シャットダウン時に実行する関数を登録します</p>\n<p></p>\n<h4>$GLOBALS[\' 変数名 \']</h4>\n<p>phpの定義済み変数のうち、$GLOBALS（グローバル変数）は</p>\n<p>できる変数です。</p>\n<p></p>\n<p>ex)</p>\n<p>この関数に関しては詳しくは以下のページにて↓</p>\n<p></p>\n<p></p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3> wp関数 </h3>\n<!-- /wp:heading -->\n\n<p>wp_initial_constants();</p>\n<p>wp_unregister_GLOBALS();</p>\n<p>wp_favicon_request();</p>\n<p>wp_maintenance();</p>\n<p>timer_start();</p>\n<p>wp_debug_mode();</p>\n<p> </p>\n<p>apply_filters();</p>\n<p> </p>\n<p>wp_not_installed();</p>\n<p>wp_plugin_directory_constants();</p>\n<p>wp_set_internal_encoding();</p>\n<p>wp_functionality_constants();</p>','wp-setting.phpを解読してみた','','inherit','closed','closed','','1816-revision-v1','','','2019-05-21 13:24:15','2019-05-21 04:24:15','',1816,'http://localhost:8080/anothor/1816-revision-v1',0,'revision','',0),(2059,1,'2019-05-22 09:15:42','2019-05-22 00:15:42','<!-- wp:heading -->\n<h2> wordpressにおけるwp-setting.phpとは </h2>\n<!-- /wp:heading -->\n\n<p>wp-setting.phpはwordpressのコアファイルを読み込んでいく際のおよそ3番目に読まれるファイルになります。</p>\n<p>wp-load.php</p>\n<p>↓</p>\n<p>wp-config.php</p>\n<p>↓</p>\n<p><strong><span style=\"color: #ff0000;\">wp-setting.php</span></strong></p>\n<p>↓</p>\n<p>・wordpressのコアファイル群</p>\n<p>・/wp-include/wp-db.php（データベースに接続しているファイル）</p>\n<p> </p>\n<p>wp-setting.phpで行っていることはざっくりいうと、wordpressを起動させる際の設定をし、コアファイルたちを次々実行していき実質的にwordpressを起動させるファイルになります。</p>\n<p> </p>\n<p> </p>\n\n<!-- wp:heading -->\n<h2> 実際に翻訳してみた </h2>\n<!-- /wp:heading -->\n\n<p>長いので、400行ちょっとあるファイルなので行っている処理ごとに分割していきます。</p>\n<p></p>\n\n<!-- wp:heading -->\n<h2>冒頭～メンテナンスモードまで</h2>\n<!-- /wp:heading -->\n\n<p>行数でいえば、最初から70行目あたりまで。</p>\n<p>wp_debug_mode();という関数があるとこまでです。</p>\n<pre class=\"lang:php decode:true\" title=\"wp-setting.php\">&lt;?php\n/**\n * 一般的な変数を設定および修正するために使用され、\n * WordPressの手続き型およびクラスライブラリを含みます。\n *\n * wp-config.phpでの設定を許可します（default-constants.phpを参照）\n *\n * @package WordPress\n */\n\n/**\n * WordPressの関数、クラス、およびコアコンテンツのディレクトリの場所を格納します。\n *\n * @since 1.0.0\n */\n\n//「WPINC」をwp-includesディレクトリと定義する\ndefine( \'WPINC\', \'wp-includes\' );\n\n// 初期化に必要なファイルを含めます。\nrequire( ABSPATH . WPINC . \'/load.php\' );\nrequire( ABSPATH . WPINC . \'/default-constants.php\' );\nrequire_once( ABSPATH . WPINC . \'/plugin.php\' );\n\n/*\n * これらはversion.phpで直接グローバル化することはできません。 更新するとき、\n * 私たちは他のインストールからのversion.phpをインクルードしています。\n * そしてすでに設定されているならこれらの値を上書きされたくないです。\n */\n\n//以下の変数をグローバル宣言する\nglobal $wp_version, $wp_db_version, $tinymce_version, $required_php_version, $required_mysql_version, $wp_local_package;\n//ドキュメントルート/wp-includes/version.phpを読み込む\nrequire( ABSPATH . WPINC . \'/version.php\' );\n\n/**\n * まだ設定されていない場合 blog_idは単一サイト設定でデフォルトの1になります。\n * マルチサイトでは、ms-settings.phpでデフォルトで上書きされます。\n *\n * @global int $blog_id\n * @since 2.0.0\n */\n//\nglobal $blog_id;\n\n// WP_MEMORY_LIMIT、WP_MAX_MEMORY_LIMIT、WP_DEBUG、SCRIPT_DEBUG、WP_CONTENT_DIRおよびWP_CACHEを含む初期デフォルト定数を設定します。\nwp_initial_constants();\n\n// 必要なPHPバージョンとMySQLエクステンションまたはデータベースドロップインをチェックしてください。\nwp_check_php_mysql_versions();\n\n// 実行時にマジッククォートを無効にします。魔法の引用符は後でwp-settings.phpでwpdbを使って追加されます\n@ini_set( \'magic_quotes_runtime\', 0 );\n@ini_set( \'magic_quotes_sybase\', 0 );\n\n// WordPressはUTCからのオフセットを計算します。\ndate_default_timezone_set( \'UTC\' );\n\n// register_globalsをオフにします。\nwp_unregister_GLOBALS();\n\n// 設定間で$ _SERVER変数を標準化します。\nwp_fix_server_vars();\n\n// favicon.icoが見つからないため、リクエストを受信したかどうかを確認します\nwp_favicon_request();\n\n// メンテナンスモードになっているか確認してください。\nwp_maintenance();\n</pre>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n\n<!-- wp:heading -->\n<h2>メンテナンスモード～ コアファイルの読み込みまで </h2>\n<!-- /wp:heading -->\n\n<p>行数でいえば、最初から71～152行目あたりまで。</p>\n<p>wp_not_installed();という関数があるとこまでです。</p>\n<p></p>\n<p>&nbsp;</p>\n<pre class=\"\">// タイマーをロードします。\ntimer_start();\n\n// WP_DEBUGモードになっているか確認してください。\nwp_debug_mode();\n\n/**\n * advanced-cache.phpドロップインのロードを有効にするかどうかをフィルタリングします。\n *\n * このフィルタはプラグインによって使用される前に実行されます。 Web以外のランタイム用に設計されています。\n * falseが返された場合、advanced-cache.phpはロードされません。\n *\n * @since 4.6.0\n *\n * @param bool $enable_advanced_cache_advanced-cache.php（存在する場合）の読み込みを有効にするかどうか\n *                                    Default true.\n */\n\nif ( WP_CACHE &amp;&amp; apply_filters( \'enable_loading_advanced_cache_dropin\', true ) ) {\n	// 高度なキャッシングプラグインを使うために。必要なのは静的ドロップインだけです。\n	WP_DEBUG ? include( WP_CONTENT_DIR . \'/advanced-cache.php\' ) : @include( WP_CONTENT_DIR . \'/advanced-cache.php\' );\n\n	// advanced-cache.phpによって手動で追加されたフックを再初期化します\n	if ( $wp_filter ) {\n		$wp_filter = WP_Hook::build_preinitialized_hooks( $wp_filter );\n	}\n}\n\n// 設定されていない場合はWP_LANG_DIRを定義します。\nwp_set_lang_dir();\n\n// 初期のWordPressファイルを読み込む.\nrequire( ABSPATH . WPINC . \'/compat.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-list-util.php\' );\nrequire( ABSPATH . WPINC . \'/formatting.php\' );\nrequire( ABSPATH . WPINC . \'/meta.php\' );\nrequire( ABSPATH . WPINC . \'/functions.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-meta-query.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-matchesmapregex.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-error.php\' );\nrequire( ABSPATH . WPINC . \'/pomo/mo.php\' );\n\n// wpdbクラスと、存在する場合はdb.phpデータベースドロップインを含めます。\nglobal $wpdb;\nrequire_wp_db();\n\n// データベーステーブルのプレフィックスとデータベーステーブル列のフォーマット指定子を設定します。\n$GLOBALS[\'table_prefix\'] = $table_prefix;\nwp_set_wpdb_vars();\n\n// WordPressオブジェクトキャッシュ、またはドロップインが存在する場合は外部オブジェクトキャッシュを起動します。\nwp_start_object_cache();\n\n// デフォルトのフィルタを添付してください。\nrequire( ABSPATH . WPINC . \'/default-filters.php\' );\n\n// 有効な場合はマルチサイトを初期化します。\nif ( is_multisite() ) {\n	require( ABSPATH . WPINC . \'/class-wp-site-query.php\' );\n	require( ABSPATH . WPINC . \'/class-wp-network-query.php\' );\n	require( ABSPATH . WPINC . \'/ms-blogs.php\' );\n	require( ABSPATH . WPINC . \'/ms-settings.php\' );\n} elseif ( ! defined( \'MULTISITE\' ) ) {\n	define( \'MULTISITE\', false );\n}\n\n//関数：shutdown_action_hookをシャットダウン時に実行する\nregister_shutdown_function( \'shutdown_action_hook\' );\n\n// 基本的な機能を使いたいだけなら、大半のWordPressをロードしないようにしてください。\nif ( SHORTINIT ) {\n	return false;\n}\n\n// L10nライブラリをロードする\nrequire_once( ABSPATH . WPINC . \'/l10n.php\' );\nrequire_once( ABSPATH . WPINC . \'/class-wp-locale.php\' );\nrequire_once( ABSPATH . WPINC . \'/class-wp-locale-switcher.php\' );\n\n// WordPressがインストールされていない場合はインストーラを実行してください\nwp_not_installed();\n</pre>\n<p>&nbsp;</p>\n\n<!-- wp:heading -->\n<h2> コアファイルの読み込み ～ まで</h2>\n<!-- /wp:heading -->\n\n<pre class=\"\"><!--?php\n/**\n * 一般的な変数を設定および修正するために使用され、\n * WordPressの手続き型およびクラスライブラリを含みます。\n *\n * wp-config.phpでの設定を許可します（default-constants.phpを参照）\n *\n * @package WordPress\n */\n\n/**\n * WordPressの関数、クラス、およびコアコンテンツのディレクトリの場所を格納します。\n *\n * @since 1.0.0\n */\n\n//「WPINC」をwp-includesディレクトリと定義する\ndefine( \'WPINC\', \'wp-includes\' );\n\n// 初期化に必要なファイルを含めます。\nrequire( ABSPATH . WPINC . \'/load.php\' );\nrequire( ABSPATH . WPINC . \'/default-constants.php\' );\nrequire_once( ABSPATH . WPINC . \'/plugin.php\' );\n\n/*\n * これらはversion.phpで直接グローバル化することはできません。 更新するとき、\n * 私たちは他のインストールからのversion.phpをインクルードしています。\n * そしてすでに設定されているならこれらの値を上書きされたくないです。\n */\n\n//以下の変数をグローバル宣言する\nglobal $wp_version, $wp_db_version, $tinymce_version, $required_php_version, $required_mysql_version, $wp_local_package;\n//ドキュメントルート/wp-includes/version.phpを読み込む\nrequire( ABSPATH . WPINC . \'/version.php\' );\n\n/**\n * まだ設定されていない場合 blog_idは単一サイト設定でデフォルトの1になります。\n * マルチサイトでは、ms-settings.phpでデフォルトで上書きされます。\n *\n * @global int $blog_id\n * @since 2.0.0\n */\n//\nglobal $blog_id;\n\n// WP_MEMORY_LIMIT、WP_MAX_MEMORY_LIMIT、WP_DEBUG、SCRIPT_DEBUG、WP_CONTENT_DIRおよびWP_CACHEを含む初期デフォルト定数を設定します。\nwp_initial_constants();\n\n// 必要なPHPバージョンとMySQLエクステンションまたはデータベースドロップインをチェックしてください。\nwp_check_php_mysql_versions();\n\n// 実行時にマジッククォートを無効にします。魔法の引用符は後でwp-settings.phpでwpdbを使って追加されます\n@ini_set( \'magic_quotes_runtime\', 0 );\n@ini_set( \'magic_quotes_sybase\', 0 );\n\n// WordPressはUTCからのオフセットを計算します。\ndate_default_timezone_set( \'UTC\' );\n\n// register_globalsをオフにします。\nwp_unregister_GLOBALS();\n\n// 設定間で$ _SERVER変数を標準化します。\nwp_fix_server_vars();\n\n// favicon.icoが見つからないため、リクエストを受信したかどうかを確認します\nwp_favicon_request();\n\n// メンテナンスモードになっているか確認してください。\nwp_maintenance();\n\n// タイマーをロードします。\ntimer_start();\n\n// WP_DEBUGモードになっているか確認してください。\nwp_debug_mode();\n\n/**\n * advanced-cache.phpドロップインのロードを有効にするかどうかをフィルタリングします。\n *\n * このフィルタはプラグインによって使用される前に実行されます。 Web以外のランタイム用に設計されています。\n * falseが返された場合、advanced-cache.phpはロードされません。\n *\n * @since 4.6.0\n *\n * @param bool $enable_advanced_cache_advanced-cache.php（存在する場合）の読み込みを有効にするかどうか\n *                                    Default true.\n */\n\nif ( WP_CACHE && apply_filters( \'enable_loading_advanced_cache_dropin\', true ) ) {\n	// 高度なキャッシングプラグインを使うために。必要なのは静的ドロップインだけです。\n	WP_DEBUG ? include( WP_CONTENT_DIR . \'/advanced-cache.php\' ) : @include( WP_CONTENT_DIR . \'/advanced-cache.php\' );\n\n	// advanced-cache.phpによって手動で追加されたフックを再初期化します\n	if ( $wp_filter ) {\n		$wp_filter = WP_Hook::build_preinitialized_hooks( $wp_filter );\n	}\n}\n\n// 設定されていない場合はWP_LANG_DIRを定義します。\nwp_set_lang_dir();\n\n// 初期のWordPressファイルを読み込む.\nrequire( ABSPATH . WPINC . \'/compat.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-list-util.php\' );\nrequire( ABSPATH . WPINC . \'/formatting.php\' );\nrequire( ABSPATH . WPINC . \'/meta.php\' );\nrequire( ABSPATH . WPINC . \'/functions.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-meta-query.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-matchesmapregex.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-error.php\' );\nrequire( ABSPATH . WPINC . \'/pomo/mo.php\' );\n\n// wpdbクラスと、存在する場合はdb.phpデータベースドロップインを含めます。\nglobal $wpdb;\nrequire_wp_db();\n\n// データベーステーブルのプレフィックスとデータベーステーブル列のフォーマット指定子を設定します。\n$GLOBALS[\'table_prefix\'] = $table_prefix;\nwp_set_wpdb_vars();\n\n// WordPressオブジェクトキャッシュ、またはドロップインが存在する場合は外部オブジェクトキャッシュを起動します。\nwp_start_object_cache();\n\n// デフォルトのフィルタを添付してください。\nrequire( ABSPATH . WPINC . \'/default-filters.php\' );\n\n// 有効な場合はマルチサイトを初期化します。\nif ( is_multisite() ) {\n	require( ABSPATH . WPINC . \'/class-wp-site-query.php\' );\n	require( ABSPATH . WPINC . \'/class-wp-network-query.php\' );\n	require( ABSPATH . WPINC . \'/ms-blogs.php\' );\n	require( ABSPATH . WPINC . \'/ms-settings.php\' );\n} elseif ( ! defined( \'MULTISITE\' ) ) {\n	define( \'MULTISITE\', false );\n}\n\n//関数：shutdown_action_hookをシャットダウン時に実行する\nregister_shutdown_function( \'shutdown_action_hook\' );\n\n// 基本的な機能を使いたいだけなら、大半のWordPressをロードしないようにしてください。\nif ( SHORTINIT ) {\n	return false;\n}\n\n// L10nライブラリをロードする\nrequire_once( ABSPATH . WPINC . \'/l10n.php\' );\nrequire_once( ABSPATH . WPINC . \'/class-wp-locale.php\' );\nrequire_once( ABSPATH . WPINC . \'/class-wp-locale-switcher.php\' );\n\n// WordPressがインストールされていない場合はインストーラを実行してください\nwp_not_installed();\n\n// WordPressコアファイルの大半をロードする\nrequire( ABSPATH . WPINC . \'/class-wp-walker.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-ajax-response.php\' );\nrequire( ABSPATH . WPINC . \'/capabilities.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-roles.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-role.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-user.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-query.php\' );\nrequire( ABSPATH . WPINC . \'/query.php\' );\nrequire( ABSPATH . WPINC . \'/date.php\' );\nrequire( ABSPATH . WPINC . \'/theme.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-theme.php\' );\nrequire( ABSPATH . WPINC . \'/template.php\' );\nrequire( ABSPATH . WPINC . \'/user.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-user-query.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-session-tokens.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-user-meta-session-tokens.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-metadata-lazyloader.php\' );\nrequire( ABSPATH . WPINC . \'/general-template.php\' );\nrequire( ABSPATH . WPINC . \'/link-template.php\' );\nrequire( ABSPATH . WPINC . \'/author-template.php\' );\nrequire( ABSPATH . WPINC . \'/post.php\' );\nrequire( ABSPATH . WPINC . \'/class-walker-page.php\' );\nrequire( ABSPATH . WPINC . \'/class-walker-page-dropdown.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-post-type.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-post.php\' );\nrequire( ABSPATH . WPINC . \'/post-template.php\' );\nrequire( ABSPATH . WPINC . \'/revision.php\' );\nrequire( ABSPATH . WPINC . \'/post-formats.php\' );\nrequire( ABSPATH . WPINC . \'/post-thumbnail-template.php\' );\nrequire( ABSPATH . WPINC . \'/category.php\' );\nrequire( ABSPATH . WPINC . \'/class-walker-category.php\' );\nrequire( ABSPATH . WPINC . \'/class-walker-category-dropdown.php\' );\nrequire( ABSPATH . WPINC . \'/category-template.php\' );\nrequire( ABSPATH . WPINC . \'/comment.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-comment.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-comment-query.php\' );\nrequire( ABSPATH . WPINC . \'/class-walker-comment.php\' );\nrequire( ABSPATH . WPINC . \'/comment-template.php\' );\nrequire( ABSPATH . WPINC . \'/rewrite.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-rewrite.php\' );\nrequire( ABSPATH . WPINC . \'/feed.php\' );\nrequire( ABSPATH . WPINC . \'/bookmark.php\' );\nrequire( ABSPATH . WPINC . \'/bookmark-template.php\' );\nrequire( ABSPATH . WPINC . \'/kses.php\' );\nrequire( ABSPATH . WPINC . \'/cron.php\' );\nrequire( ABSPATH . WPINC . \'/deprecated.php\' );\nrequire( ABSPATH . WPINC . \'/script-loader.php\' );\nrequire( ABSPATH . WPINC . \'/taxonomy.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-taxonomy.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-term.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-term-query.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-tax-query.php\' );\nrequire( ABSPATH . WPINC . \'/update.php\' );\nrequire( ABSPATH . WPINC . \'/canonical.php\' );\nrequire( ABSPATH . WPINC . \'/shortcodes.php\' );\nrequire( ABSPATH . WPINC . \'/embed.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-embed.php\' );\nrequire( ABSPATH . WPINC . \'/class-oembed.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-oembed-controller.php\' );\nrequire( ABSPATH . WPINC . \'/media.php\' );\nrequire( ABSPATH . WPINC . \'/http.php\' );\nrequire( ABSPATH . WPINC . \'/class-http.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-streams.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-curl.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-proxy.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-cookie.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-encoding.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-response.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-requests-response.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-requests-hooks.php\' );\nrequire( ABSPATH . WPINC . \'/widgets.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-widget.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-widget-factory.php\' );\nrequire( ABSPATH . WPINC . \'/nav-menu.php\' );\nrequire( ABSPATH . WPINC . \'/nav-menu-template.php\' );\nrequire( ABSPATH . WPINC . \'/admin-bar.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/class-wp-rest-server.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/class-wp-rest-response.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/class-wp-rest-request.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-posts-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-attachments-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-post-types-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-post-statuses-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-revisions-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-autosaves-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-taxonomies-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-terms-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-users-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-comments-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-search-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-blocks-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-block-renderer-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-settings-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-themes-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-comment-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-post-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-term-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-user-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/search/class-wp-rest-search-handler.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/search/class-wp-rest-post-search-handler.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-block-type.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-block-type-registry.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-block-parser.php\' );\nrequire( ABSPATH . WPINC . \'/blocks.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/archives.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/block.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/categories.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/latest-comments.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/latest-posts.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/shortcode.php\' );\n\n$GLOBALS[\'wp_embed\'] = new WP_Embed();\n\n// マルチサイト固有のファイルをロードします。\nif ( is_multisite() ) {\n	require( ABSPATH . WPINC . \'/ms-functions.php\' );\n	require( ABSPATH . WPINC . \'/ms-default-filters.php\' );\n	require( ABSPATH . WPINC . \'/ms-deprecated.php\' );\n}\n\n// デフォルト値を取得するためにAPIに依存する定数を定義します。\n// sunrise.phpドロップインで上書きされる可能性のある、必ず使用するプラグインディレクトリ定数を定義します。.\nwp_plugin_directory_constants();\n\n$GLOBALS[\'wp_plugin_paths\'] = array();\n\n// マストユーズプラグインをロードします\nforeach ( wp_get_mu_plugins() as $mu_plugin ) {\n	include_once( $mu_plugin );\n\n	/**\n	 * 一つのマストユーズプラグインがロードされたら起動する\n	 *\n	 * @since 5.1.0\n	 *\n	 * @param string $mu_plugin Full path to the plugin\'s main file.\n	 */\n	do_action( \'mu_plugin_loaded\', $mu_plugin );\n}\nunset( $mu_plugin );\n\n// ネットワーク起動プラグインをロードします\nif ( is_multisite() ) {\n	foreach ( wp_get_active_network_plugins() as $network_plugin ) {\n		wp_register_plugin_realpath( $network_plugin );\n		include_once( $network_plugin );\n\n		/**\n		 * 一つのネットワーク起動プラグインがロードされたら起動する\n		 *\n		 * @since 5.1.0\n		 *\n		 * @param string $network_plugin Full path to the plugin\'s main file.\n		 */\n		do_action( \'network_plugin_loaded\', $network_plugin );\n	}\n	unset( $network_plugin );\n}\n\n/**\n * すべての必須使用およびネットワーク起動プラグインがロードされると起動します。\n *\n * @since 2.8.0\n */\n\n//関数：muplugins_loadedを実行する\ndo_action( \'muplugins_loaded\' );\n\nif ( is_multisite() ) {\n	ms_cookie_constants();\n}\n\n// マルチサイトがロードされた後に定数を定義します。\nwp_cookie_constants();\n\n// SSL定数を定義して実施する\nwp_ssl_constants();\n\n// 共通グローバルを作成する\nrequire( ABSPATH . WPINC . \'/vars.php\' );\n\n// タクソノミーや投稿をプラグインやテーマで利用できるようにします。\n// @プラグインの作成者：警告：これらはinitフックに再度登録されます。\ncreate_initial_taxonomies();\ncreate_initial_post_types();\n\nwp_start_scraping_edited_file_errors();\n\n// デフォルトのテーマディレクトリのルートを登録する\nregister_theme_directory( get_theme_root() );\n\n// 有効化されてるプラグインをよみこむ\nforeach ( wp_get_active_and_valid_plugins() as $plugin ) {\n	wp_register_plugin_realpath( $plugin );\n	include_once( $plugin );\n\n	/**\n	 * 一度有効化されたプラグインをよみこむと起動する\n	 *\n	 * @since 5.1.0\n	 *\n	 * @param string $plugin Full path to the plugin\'s main file.\n	 */\n	do_action( \'plugin_loaded\', $plugin );\n}\nunset( $plugin );\n\n// プラガブル関数を読み込む.\nrequire( ABSPATH . WPINC . \'/pluggable.php\' );\nrequire( ABSPATH . WPINC . \'/pluggable-deprecated.php\' );\n\n// 内部エンコーディングを設定します。\nwp_set_internal_encoding();\n\n// オブジェクトキャッシュが有効で、関数が存在する場合は、wp_cache_postload（）を実行する\nif ( WP_CACHE && function_exists( \'wp_cache_postload\' ) ) {\n	wp_cache_postload();\n}\n\n/**\n * 一度有効化されたプラグインをよみこむと起動する\n *\n * 読み込まれているこの時点でプラガブル機能も利用可能です。\n *\n * @since 1.5.0\n */\ndo_action( \'plugins_loaded\' );\n\n// まだ定義されていない場合、機能に影響を与える定数を定義します。\nwp_functionality_constants();\n\n// マジッククオートを追加して$ _REQUEST（$ _GET + $ _POST）を設定する\nwp_magic_quotes();\n\n/**\n * コメントクッキーがサニタイズされたときに起動します。\n *\n * @since 2.0.11\n */\ndo_action( \'sanitize_comment_cookies\' );\n\n/**\n * WordPress Query object\n *\n * @global WP_Query $wp_the_query\n * @since 2.0.0\n */\n$GLOBALS[\'wp_the_query\'] = new WP_Query();\n\n/**\n * $ wp_the_queryへの参照を保持しています\n * WordPressクエリにこのグローバルを使用\n *\n * @global WP_Query $wp_query\n * @since 1.5.0\n */\n$GLOBALS[\'wp_query\'] = $GLOBALS[\'wp_the_query\'];\n\n/**\n * きれいなURLを作成するためのWordPressリライトオブジェクトを保持します。\n * @global WP_Rewrite $wp_rewrite\n * @since 1.5.0\n */\n$GLOBALS[\'wp_rewrite\'] = new WP_Rewrite();\n\n/**\n * WordPress オブジェクト\n *\n * @global WP $wp\n * @since 2.0.0\n */\n$GLOBALS[\'wp\'] = new WP();\n\n/**\n * WordPress Widget Factory Object\n *\n * @global WP_Widget_Factory $wp_widget_factory\n * @since 2.8.0\n */\n$GLOBALS[\'wp_widget_factory\'] = new WP_Widget_Factory();\n\n/**\n * WordPress User Roles\n *\n * @global WP_Roles $wp_roles\n * @since 2.0.0\n */\n$GLOBALS[\'wp_roles\'] = new WP_Roles();\n\n/**\n * テーマが読み込まれる前に発生します。\n *\n * @since 2.6.0\n */\ndo_action( \'setup_theme\' );\n\n// テンプレート関連定数を定義します。\nwp_templating_constants();\n\n// デフォルトのテキストローカライゼーションドメインを読み込む。\nload_default_textdomain();\n\n$locale      = get_locale();\n$locale_file = WP_LANG_DIR . \"/$locale.php\";\nif ( ( 0 === validate_file( $locale ) ) && is_readable( $locale_file ) ) {\n	require( $locale_file );\n}\nunset( $locale_file );\n\n/**\n * ロケールドメインの日付とさまざまな文字列をロードするためのWordPress Localeオブジェクト。\n *\n * @global WP_Locale $wp_locale\n * @since 2.1.0\n */\n$GLOBALS[\'wp_locale\'] = new WP_Locale();\n\n/**\n *  ロケールを切り替えるためのWordPress Locale Switcherオブジェクト\n *\n * @since 4.7.0\n *\n * @global WP_Locale_Switcher $ wp_locale_switcher WordPressロケール切り替えオブジェクト。\n */\n$GLOBALS[\'wp_locale_switcher\'] = new WP_Locale_Switcher();\n$GLOBALS[\'wp_locale_switcher\']--->init();\n\n// 該当する場合は、親テーマと子テーマの両方について、アクティブなテーマの機能をロードします。\nforeach ( wp_get_active_and_valid_themes() as $theme ) {\n	if ( file_exists( $theme . \'/functions.php\' ) ) {\n		include $theme . \'/functions.php\';\n	}\n}\nunset( $theme );\n\n/**\n * テーマが読まれた後に起動する\n *\n * @since 3.0.0\n */\ndo_action( \'after_setup_theme\' );\n\n// 現在のユーザーを設定します。\n$GLOBALS[\'wp\']-&gt;init();\n\n/**\n * WordPressの読み込みが完了した後、ヘッダーが送信される前に起動ます。\n *\n * WPの大部分はこの段階でロードされ、ユーザーは認証されます。\n * WPは{@see \'init\'}フック（例えばウィジェット）に読み込みそれに続いて読み込まれます、多くのプラグインがインスタンス化します\n * WP自身はあらゆる種類の理由で分類します。（例えば、ユーザー、タクソノミーなど）\n *\n * WPがロードされた後にアクションをプラグインしたい場合は、以下の{@see \'wp_loaded\'}フックを使用してください。\n *\n * @since 1.5.0\n */\ndo_action( \'init\' );\n\n// マルチサイトの場合\nif ( is_multisite() ) {\n	if ( true !== ( $file = ms_site_check() ) ) {\n		require( $file );\n		die();\n	}\n	unset( $file );\n}\n\n/**\n * このフックは、WP、すべてのプラグイン、およびテーマが完全に読み込まれてインスタンス化されると起動します。\n *\n * Ajaxリクエストはwp-admin / admin-ajax.phpを使うべきです。\n * ajax.phpは、ログインしていないユーザーに対するリクエストを処理できます。\n * @link https://codex.wordpress.org/AJAX_in_Plugins\n *\n * @since 3.0.0\n */\ndo_action( \'wp_loaded\' );\n\n</pre>\n\n<!-- wp:heading {\"level\":3} -->\n<h3></h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2> まとめ：このファイルで行ってること </h2>\n<!-- /wp:heading -->\n\n<p>・</p>\n\n<!-- wp:heading -->\n<h2> おまけ：このファイルで使われた関数 </h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3> php関数 </h3>\n<!-- /wp:heading -->\n\n<p>date_default_timezone_set( \'UTC\' );</p>\n<p></p>\n<p>register_shutdown_function( \'関数名\' );</p>\n<p>シャットダウン時に実行する関数を登録します</p>\n<p></p>\n<h4>$GLOBALS[\' 変数名 \']</h4>\n<p>phpの定義済み変数のうち、$GLOBALS（グローバル変数）は</p>\n<p>できる変数です。</p>\n<p></p>\n<p>ex)</p>\n<p>この関数に関しては詳しくは以下のページにて↓</p>\n<p></p>\n<p></p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3> wp関数 </h3>\n<!-- /wp:heading -->\n\n<p>いろいろありましたが、大事そうなやつだけピックアップ。</p>\n<p> </p>\n<p>wp_initial_constants();</p>\n<p>wp_unregister_GLOBALS();</p>\n<p>wp_favicon_request();</p>\n<p>wp_maintenance();</p>\n<p>timer_start();</p>\n<p>wp_debug_mode();</p>\n<p> </p>\n<p>apply_filters();</p>\n<p> </p>\n<p>wp_not_installed();</p>\n<p>wp_plugin_directory_constants();</p>\n<p>wp_set_internal_encoding();</p>\n<p>wp_functionality_constants();</p>','wp-setting.phpを解読してみた','','inherit','closed','closed','','1816-revision-v1','','','2019-05-22 09:15:42','2019-05-22 00:15:42','',1816,'http://localhost:8080/anothor/1816-revision-v1',0,'revision','',0),(2187,1,'2019-05-30 14:44:45','2019-05-30 05:44:45','<!-- wp:heading -->\n<h2> wordpressにおけるwp-setting.phpとは </h2>\n<!-- /wp:heading -->\n\n<p>wp-setting.phpはwordpressのコアファイルを読み込んでいく際のおよそ3番目に読まれるファイルになります。</p>\n<p> </p>\n<p>wp-load.php</p>\n<p>↓</p>\n<p>wp-config.php</p>\n<p>↓</p>\n<p><strong><span style=\"color: #ff0000;\">wp-setting.php</span></strong></p>\n<p>↓</p>\n<p>・wordpressのコアファイル群</p>\n<p>・/wp-include/wp-db.php（データベースに接続しているファイル）</p>\n<p> </p>\n<p>wp-setting.phpで行っていることはざっくりいうと、wordpressを起動させる際の設定をし、コアファイルたちを次々実行していき実質的にwordpressを起動させるファイルになります。</p>\n<p> </p>\n<p> </p>\n\n<!-- wp:heading -->\n<h2> 実際に翻訳してみた </h2>\n<!-- /wp:heading -->\n\n<p>400行ちょっとあるファイルなので行っている処理ごとに分割していきます。</p>\n<p> </p>\n\n<!-- wp:heading -->\n<h2>冒頭～メンテナンスモードまで</h2>\n<!-- /wp:heading -->\n\n<p>行数でいえば、最初から70行目あたりまで。</p>\n<p>wp_debug_mode();という関数があるとこまでです。</p>\n<pre class=\"lang:php decode:true\" title=\"wp-setting.php\">&lt;?php\n/**\n * 一般的な変数を設定および修正するために使用され、\n * WordPressの手続き型およびクラスライブラリを含みます。\n *\n * wp-config.phpでの設定を許可します（default-constants.phpを参照）\n *\n * @package WordPress\n */\n\n/**\n * WordPressの関数、クラス、およびコアコンテンツのディレクトリの場所を格納します。\n *\n * @since 1.0.0\n */\n\n//「WPINC」をwp-includesディレクトリと定義する\ndefine( \'WPINC\', \'wp-includes\' );\n\n// 初期化に必要なファイルを含めます。\nrequire( ABSPATH . WPINC . \'/load.php\' );\nrequire( ABSPATH . WPINC . \'/default-constants.php\' );\nrequire_once( ABSPATH . WPINC . \'/plugin.php\' );\n\n/*\n * これらはversion.phpで直接グローバル化することはできません。 更新するとき、\n * 私たちは他のインストールからのversion.phpをインクルードしています。\n * そしてすでに設定されているならこれらの値を上書きされたくないです。\n */\n\n//以下の変数をグローバル宣言する\nglobal $wp_version, $wp_db_version, $tinymce_version, $required_php_version, $required_mysql_version, $wp_local_package;\n//ドキュメントルート/wp-includes/version.phpを読み込む\nrequire( ABSPATH . WPINC . \'/version.php\' );\n\n/**\n * まだ設定されていない場合 blog_idは単一サイト設定でデフォルトの1になります。\n * マルチサイトでは、ms-settings.phpでデフォルトで上書きされます。\n *\n * @global int $blog_id\n * @since 2.0.0\n */\n//\nglobal $blog_id;\n\n// WP_MEMORY_LIMIT、WP_MAX_MEMORY_LIMIT、WP_DEBUG、SCRIPT_DEBUG、WP_CONTENT_DIRおよびWP_CACHEを含む初期デフォルト定数を設定します。\nwp_initial_constants();\n\n// 必要なPHPバージョンとMySQLエクステンションまたはデータベースドロップインをチェックしてください。\nwp_check_php_mysql_versions();\n\n// 実行時にマジッククォートを無効にします。魔法の引用符は後でwp-settings.phpでwpdbを使って追加されます\n@ini_set( \'magic_quotes_runtime\', 0 );\n@ini_set( \'magic_quotes_sybase\', 0 );\n\n// WordPressはUTCからのオフセットを計算します。\ndate_default_timezone_set( \'UTC\' );\n\n// register_globalsをオフにします。\nwp_unregister_GLOBALS();\n\n// 設定間で$ _SERVER変数を標準化します。\nwp_fix_server_vars();\n\n// favicon.icoが見つからないため、リクエストを受信したかどうかを確認します\nwp_favicon_request();\n\n// メンテナンスモードになっているか確認してください。\nwp_maintenance();\n</pre>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n\n<!-- wp:heading -->\n<h2>メンテナンスモード～ コアファイルの読み込みまで </h2>\n<!-- /wp:heading -->\n\n<p>行数でいえば、最初から71～152行目あたりまで。</p>\n<p>wp_not_installed();という関数があるとこまでです。</p>\n<p></p>\n<p>&nbsp;</p>\n<pre class=\"\">// タイマーをロードします。\ntimer_start();\n\n// WP_DEBUGモードになっているか確認してください。\nwp_debug_mode();\n\n/**\n * advanced-cache.phpドロップインのロードを有効にするかどうかをフィルタリングします。\n *\n * このフィルタはプラグインによって使用される前に実行されます。 Web以外のランタイム用に設計されています。\n * falseが返された場合、advanced-cache.phpはロードされません。\n *\n * @since 4.6.0\n *\n * @param bool $enable_advanced_cache_advanced-cache.php（存在する場合）の読み込みを有効にするかどうか\n *                                    Default true.\n */\n\nif ( WP_CACHE &amp;&amp; apply_filters( \'enable_loading_advanced_cache_dropin\', true ) ) {\n	// 高度なキャッシングプラグインを使うために。必要なのは静的ドロップインだけです。\n	WP_DEBUG ? include( WP_CONTENT_DIR . \'/advanced-cache.php\' ) : @include( WP_CONTENT_DIR . \'/advanced-cache.php\' );\n\n	// advanced-cache.phpによって手動で追加されたフックを再初期化します\n	if ( $wp_filter ) {\n		$wp_filter = WP_Hook::build_preinitialized_hooks( $wp_filter );\n	}\n}\n\n// 設定されていない場合はWP_LANG_DIRを定義します。\nwp_set_lang_dir();\n\n// 初期のWordPressファイルを読み込む.\nrequire( ABSPATH . WPINC . \'/compat.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-list-util.php\' );\nrequire( ABSPATH . WPINC . \'/formatting.php\' );\nrequire( ABSPATH . WPINC . \'/meta.php\' );\nrequire( ABSPATH . WPINC . \'/functions.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-meta-query.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-matchesmapregex.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-error.php\' );\nrequire( ABSPATH . WPINC . \'/pomo/mo.php\' );\n\n// wpdbクラスと、存在する場合はdb.phpデータベースドロップインを含めます。\nglobal $wpdb;\nrequire_wp_db();\n\n// データベーステーブルのプレフィックスとデータベーステーブル列のフォーマット指定子を設定します。\n$GLOBALS[\'table_prefix\'] = $table_prefix;\nwp_set_wpdb_vars();\n\n// WordPressオブジェクトキャッシュ、またはドロップインが存在する場合は外部オブジェクトキャッシュを起動します。\nwp_start_object_cache();\n\n// デフォルトのフィルタを添付してください。\nrequire( ABSPATH . WPINC . \'/default-filters.php\' );\n\n// 有効な場合はマルチサイトを初期化します。\nif ( is_multisite() ) {\n	require( ABSPATH . WPINC . \'/class-wp-site-query.php\' );\n	require( ABSPATH . WPINC . \'/class-wp-network-query.php\' );\n	require( ABSPATH . WPINC . \'/ms-blogs.php\' );\n	require( ABSPATH . WPINC . \'/ms-settings.php\' );\n} elseif ( ! defined( \'MULTISITE\' ) ) {\n	define( \'MULTISITE\', false );\n}\n\n//関数：shutdown_action_hookをシャットダウン時に実行する\nregister_shutdown_function( \'shutdown_action_hook\' );\n\n// 基本的な機能を使いたいだけなら、大半のWordPressをロードしないようにしてください。\nif ( SHORTINIT ) {\n	return false;\n}\n\n// L10nライブラリをロードする\nrequire_once( ABSPATH . WPINC . \'/l10n.php\' );\nrequire_once( ABSPATH . WPINC . \'/class-wp-locale.php\' );\nrequire_once( ABSPATH . WPINC . \'/class-wp-locale-switcher.php\' );\n\n// WordPressがインストールされていない場合はインストーラを実行してください\nwp_not_installed();\n</pre>\n<p>&nbsp;</p>\n\n<!-- wp:heading -->\n<h2> コアファイルの読み込み ～ まで</h2>\n<!-- /wp:heading -->\n\n<pre class=\"\"><!--?php\n/**\n * 一般的な変数を設定および修正するために使用され、\n * WordPressの手続き型およびクラスライブラリを含みます。\n *\n * wp-config.phpでの設定を許可します（default-constants.phpを参照）\n *\n * @package WordPress\n */\n\n/**\n * WordPressの関数、クラス、およびコアコンテンツのディレクトリの場所を格納します。\n *\n * @since 1.0.0\n */\n\n//「WPINC」をwp-includesディレクトリと定義する\ndefine( \'WPINC\', \'wp-includes\' );\n\n// 初期化に必要なファイルを含めます。\nrequire( ABSPATH . WPINC . \'/load.php\' );\nrequire( ABSPATH . WPINC . \'/default-constants.php\' );\nrequire_once( ABSPATH . WPINC . \'/plugin.php\' );\n\n/*\n * これらはversion.phpで直接グローバル化することはできません。 更新するとき、\n * 私たちは他のインストールからのversion.phpをインクルードしています。\n * そしてすでに設定されているならこれらの値を上書きされたくないです。\n */\n\n//以下の変数をグローバル宣言する\nglobal $wp_version, $wp_db_version, $tinymce_version, $required_php_version, $required_mysql_version, $wp_local_package;\n//ドキュメントルート/wp-includes/version.phpを読み込む\nrequire( ABSPATH . WPINC . \'/version.php\' );\n\n/**\n * まだ設定されていない場合 blog_idは単一サイト設定でデフォルトの1になります。\n * マルチサイトでは、ms-settings.phpでデフォルトで上書きされます。\n *\n * @global int $blog_id\n * @since 2.0.0\n */\n//\nglobal $blog_id;\n\n// WP_MEMORY_LIMIT、WP_MAX_MEMORY_LIMIT、WP_DEBUG、SCRIPT_DEBUG、WP_CONTENT_DIRおよびWP_CACHEを含む初期デフォルト定数を設定します。\nwp_initial_constants();\n\n// 必要なPHPバージョンとMySQLエクステンションまたはデータベースドロップインをチェックしてください。\nwp_check_php_mysql_versions();\n\n// 実行時にマジッククォートを無効にします。魔法の引用符は後でwp-settings.phpでwpdbを使って追加されます\n@ini_set( \'magic_quotes_runtime\', 0 );\n@ini_set( \'magic_quotes_sybase\', 0 );\n\n// WordPressはUTCからのオフセットを計算します。\ndate_default_timezone_set( \'UTC\' );\n\n// register_globalsをオフにします。\nwp_unregister_GLOBALS();\n\n// 設定間で$ _SERVER変数を標準化します。\nwp_fix_server_vars();\n\n// favicon.icoが見つからないため、リクエストを受信したかどうかを確認します\nwp_favicon_request();\n\n// メンテナンスモードになっているか確認してください。\nwp_maintenance();\n\n// タイマーをロードします。\ntimer_start();\n\n// WP_DEBUGモードになっているか確認してください。\nwp_debug_mode();\n\n/**\n * advanced-cache.phpドロップインのロードを有効にするかどうかをフィルタリングします。\n *\n * このフィルタはプラグインによって使用される前に実行されます。 Web以外のランタイム用に設計されています。\n * falseが返された場合、advanced-cache.phpはロードされません。\n *\n * @since 4.6.0\n *\n * @param bool $enable_advanced_cache_advanced-cache.php（存在する場合）の読み込みを有効にするかどうか\n *                                    Default true.\n */\n\nif ( WP_CACHE && apply_filters( \'enable_loading_advanced_cache_dropin\', true ) ) {\n	// 高度なキャッシングプラグインを使うために。必要なのは静的ドロップインだけです。\n	WP_DEBUG ? include( WP_CONTENT_DIR . \'/advanced-cache.php\' ) : @include( WP_CONTENT_DIR . \'/advanced-cache.php\' );\n\n	// advanced-cache.phpによって手動で追加されたフックを再初期化します\n	if ( $wp_filter ) {\n		$wp_filter = WP_Hook::build_preinitialized_hooks( $wp_filter );\n	}\n}\n\n// 設定されていない場合はWP_LANG_DIRを定義します。\nwp_set_lang_dir();\n\n// 初期のWordPressファイルを読み込む.\nrequire( ABSPATH . WPINC . \'/compat.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-list-util.php\' );\nrequire( ABSPATH . WPINC . \'/formatting.php\' );\nrequire( ABSPATH . WPINC . \'/meta.php\' );\nrequire( ABSPATH . WPINC . \'/functions.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-meta-query.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-matchesmapregex.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-error.php\' );\nrequire( ABSPATH . WPINC . \'/pomo/mo.php\' );\n\n// wpdbクラスと、存在する場合はdb.phpデータベースドロップインを含めます。\nglobal $wpdb;\nrequire_wp_db();\n\n// データベーステーブルのプレフィックスとデータベーステーブル列のフォーマット指定子を設定します。\n$GLOBALS[\'table_prefix\'] = $table_prefix;\nwp_set_wpdb_vars();\n\n// WordPressオブジェクトキャッシュ、またはドロップインが存在する場合は外部オブジェクトキャッシュを起動します。\nwp_start_object_cache();\n\n// デフォルトのフィルタを添付してください。\nrequire( ABSPATH . WPINC . \'/default-filters.php\' );\n\n// 有効な場合はマルチサイトを初期化します。\nif ( is_multisite() ) {\n	require( ABSPATH . WPINC . \'/class-wp-site-query.php\' );\n	require( ABSPATH . WPINC . \'/class-wp-network-query.php\' );\n	require( ABSPATH . WPINC . \'/ms-blogs.php\' );\n	require( ABSPATH . WPINC . \'/ms-settings.php\' );\n} elseif ( ! defined( \'MULTISITE\' ) ) {\n	define( \'MULTISITE\', false );\n}\n\n//関数：shutdown_action_hookをシャットダウン時に実行する\nregister_shutdown_function( \'shutdown_action_hook\' );\n\n// 基本的な機能を使いたいだけなら、大半のWordPressをロードしないようにしてください。\nif ( SHORTINIT ) {\n	return false;\n}\n\n// L10nライブラリをロードする\nrequire_once( ABSPATH . WPINC . \'/l10n.php\' );\nrequire_once( ABSPATH . WPINC . \'/class-wp-locale.php\' );\nrequire_once( ABSPATH . WPINC . \'/class-wp-locale-switcher.php\' );\n\n// WordPressがインストールされていない場合はインストーラを実行してください\nwp_not_installed();\n\n// WordPressコアファイルの大半をロードする\nrequire( ABSPATH . WPINC . \'/class-wp-walker.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-ajax-response.php\' );\nrequire( ABSPATH . WPINC . \'/capabilities.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-roles.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-role.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-user.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-query.php\' );\nrequire( ABSPATH . WPINC . \'/query.php\' );\nrequire( ABSPATH . WPINC . \'/date.php\' );\nrequire( ABSPATH . WPINC . \'/theme.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-theme.php\' );\nrequire( ABSPATH . WPINC . \'/template.php\' );\nrequire( ABSPATH . WPINC . \'/user.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-user-query.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-session-tokens.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-user-meta-session-tokens.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-metadata-lazyloader.php\' );\nrequire( ABSPATH . WPINC . \'/general-template.php\' );\nrequire( ABSPATH . WPINC . \'/link-template.php\' );\nrequire( ABSPATH . WPINC . \'/author-template.php\' );\nrequire( ABSPATH . WPINC . \'/post.php\' );\nrequire( ABSPATH . WPINC . \'/class-walker-page.php\' );\nrequire( ABSPATH . WPINC . \'/class-walker-page-dropdown.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-post-type.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-post.php\' );\nrequire( ABSPATH . WPINC . \'/post-template.php\' );\nrequire( ABSPATH . WPINC . \'/revision.php\' );\nrequire( ABSPATH . WPINC . \'/post-formats.php\' );\nrequire( ABSPATH . WPINC . \'/post-thumbnail-template.php\' );\nrequire( ABSPATH . WPINC . \'/category.php\' );\nrequire( ABSPATH . WPINC . \'/class-walker-category.php\' );\nrequire( ABSPATH . WPINC . \'/class-walker-category-dropdown.php\' );\nrequire( ABSPATH . WPINC . \'/category-template.php\' );\nrequire( ABSPATH . WPINC . \'/comment.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-comment.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-comment-query.php\' );\nrequire( ABSPATH . WPINC . \'/class-walker-comment.php\' );\nrequire( ABSPATH . WPINC . \'/comment-template.php\' );\nrequire( ABSPATH . WPINC . \'/rewrite.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-rewrite.php\' );\nrequire( ABSPATH . WPINC . \'/feed.php\' );\nrequire( ABSPATH . WPINC . \'/bookmark.php\' );\nrequire( ABSPATH . WPINC . \'/bookmark-template.php\' );\nrequire( ABSPATH . WPINC . \'/kses.php\' );\nrequire( ABSPATH . WPINC . \'/cron.php\' );\nrequire( ABSPATH . WPINC . \'/deprecated.php\' );\nrequire( ABSPATH . WPINC . \'/script-loader.php\' );\nrequire( ABSPATH . WPINC . \'/taxonomy.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-taxonomy.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-term.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-term-query.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-tax-query.php\' );\nrequire( ABSPATH . WPINC . \'/update.php\' );\nrequire( ABSPATH . WPINC . \'/canonical.php\' );\nrequire( ABSPATH . WPINC . \'/shortcodes.php\' );\nrequire( ABSPATH . WPINC . \'/embed.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-embed.php\' );\nrequire( ABSPATH . WPINC . \'/class-oembed.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-oembed-controller.php\' );\nrequire( ABSPATH . WPINC . \'/media.php\' );\nrequire( ABSPATH . WPINC . \'/http.php\' );\nrequire( ABSPATH . WPINC . \'/class-http.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-streams.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-curl.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-proxy.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-cookie.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-encoding.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-response.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-requests-response.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-requests-hooks.php\' );\nrequire( ABSPATH . WPINC . \'/widgets.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-widget.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-widget-factory.php\' );\nrequire( ABSPATH . WPINC . \'/nav-menu.php\' );\nrequire( ABSPATH . WPINC . \'/nav-menu-template.php\' );\nrequire( ABSPATH . WPINC . \'/admin-bar.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/class-wp-rest-server.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/class-wp-rest-response.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/class-wp-rest-request.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-posts-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-attachments-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-post-types-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-post-statuses-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-revisions-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-autosaves-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-taxonomies-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-terms-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-users-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-comments-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-search-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-blocks-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-block-renderer-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-settings-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-themes-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-comment-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-post-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-term-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-user-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/search/class-wp-rest-search-handler.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/search/class-wp-rest-post-search-handler.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-block-type.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-block-type-registry.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-block-parser.php\' );\nrequire( ABSPATH . WPINC . \'/blocks.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/archives.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/block.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/categories.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/latest-comments.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/latest-posts.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/shortcode.php\' );\n\n$GLOBALS[\'wp_embed\'] = new WP_Embed();\n\n// マルチサイト固有のファイルをロードします。\nif ( is_multisite() ) {\n	require( ABSPATH . WPINC . \'/ms-functions.php\' );\n	require( ABSPATH . WPINC . \'/ms-default-filters.php\' );\n	require( ABSPATH . WPINC . \'/ms-deprecated.php\' );\n}\n\n// デフォルト値を取得するためにAPIに依存する定数を定義します。\n// sunrise.phpドロップインで上書きされる可能性のある、必ず使用するプラグインディレクトリ定数を定義します。.\nwp_plugin_directory_constants();\n\n$GLOBALS[\'wp_plugin_paths\'] = array();\n\n// マストユーズプラグインをロードします\nforeach ( wp_get_mu_plugins() as $mu_plugin ) {\n	include_once( $mu_plugin );\n\n	/**\n	 * 一つのマストユーズプラグインがロードされたら起動する\n	 *\n	 * @since 5.1.0\n	 *\n	 * @param string $mu_plugin Full path to the plugin\'s main file.\n	 */\n	do_action( \'mu_plugin_loaded\', $mu_plugin );\n}\nunset( $mu_plugin );\n\n// ネットワーク起動プラグインをロードします\nif ( is_multisite() ) {\n	foreach ( wp_get_active_network_plugins() as $network_plugin ) {\n		wp_register_plugin_realpath( $network_plugin );\n		include_once( $network_plugin );\n\n		/**\n		 * 一つのネットワーク起動プラグインがロードされたら起動する\n		 *\n		 * @since 5.1.0\n		 *\n		 * @param string $network_plugin Full path to the plugin\'s main file.\n		 */\n		do_action( \'network_plugin_loaded\', $network_plugin );\n	}\n	unset( $network_plugin );\n}\n\n/**\n * すべての必須使用およびネットワーク起動プラグインがロードされると起動します。\n *\n * @since 2.8.0\n */\n\n//関数：muplugins_loadedを実行する\ndo_action( \'muplugins_loaded\' );\n\nif ( is_multisite() ) {\n	ms_cookie_constants();\n}\n\n// マルチサイトがロードされた後に定数を定義します。\nwp_cookie_constants();\n\n// SSL定数を定義して実施する\nwp_ssl_constants();\n\n// 共通グローバルを作成する\nrequire( ABSPATH . WPINC . \'/vars.php\' );\n\n// タクソノミーや投稿をプラグインやテーマで利用できるようにします。\n// @プラグインの作成者：警告：これらはinitフックに再度登録されます。\ncreate_initial_taxonomies();\ncreate_initial_post_types();\n\nwp_start_scraping_edited_file_errors();\n\n// デフォルトのテーマディレクトリのルートを登録する\nregister_theme_directory( get_theme_root() );\n\n// 有効化されてるプラグインをよみこむ\nforeach ( wp_get_active_and_valid_plugins() as $plugin ) {\n	wp_register_plugin_realpath( $plugin );\n	include_once( $plugin );\n\n	/**\n	 * 一度有効化されたプラグインをよみこむと起動する\n	 *\n	 * @since 5.1.0\n	 *\n	 * @param string $plugin Full path to the plugin\'s main file.\n	 */\n	do_action( \'plugin_loaded\', $plugin );\n}\nunset( $plugin );\n\n// プラガブル関数を読み込む.\nrequire( ABSPATH . WPINC . \'/pluggable.php\' );\nrequire( ABSPATH . WPINC . \'/pluggable-deprecated.php\' );\n\n// 内部エンコーディングを設定します。\nwp_set_internal_encoding();\n\n// オブジェクトキャッシュが有効で、関数が存在する場合は、wp_cache_postload（）を実行する\nif ( WP_CACHE && function_exists( \'wp_cache_postload\' ) ) {\n	wp_cache_postload();\n}\n\n/**\n * 一度有効化されたプラグインをよみこむと起動する\n *\n * 読み込まれているこの時点でプラガブル機能も利用可能です。\n *\n * @since 1.5.0\n */\ndo_action( \'plugins_loaded\' );\n\n// まだ定義されていない場合、機能に影響を与える定数を定義します。\nwp_functionality_constants();\n\n// マジッククオートを追加して$ _REQUEST（$ _GET + $ _POST）を設定する\nwp_magic_quotes();\n\n/**\n * コメントクッキーがサニタイズされたときに起動します。\n *\n * @since 2.0.11\n */\ndo_action( \'sanitize_comment_cookies\' );\n\n/**\n * WordPress Query object\n *\n * @global WP_Query $wp_the_query\n * @since 2.0.0\n */\n$GLOBALS[\'wp_the_query\'] = new WP_Query();\n\n/**\n * $ wp_the_queryへの参照を保持しています\n * WordPressクエリにこのグローバルを使用\n *\n * @global WP_Query $wp_query\n * @since 1.5.0\n */\n$GLOBALS[\'wp_query\'] = $GLOBALS[\'wp_the_query\'];\n\n/**\n * きれいなURLを作成するためのWordPressリライトオブジェクトを保持します。\n * @global WP_Rewrite $wp_rewrite\n * @since 1.5.0\n */\n$GLOBALS[\'wp_rewrite\'] = new WP_Rewrite();\n\n/**\n * WordPress オブジェクト\n *\n * @global WP $wp\n * @since 2.0.0\n */\n$GLOBALS[\'wp\'] = new WP();\n\n/**\n * WordPress Widget Factory Object\n *\n * @global WP_Widget_Factory $wp_widget_factory\n * @since 2.8.0\n */\n$GLOBALS[\'wp_widget_factory\'] = new WP_Widget_Factory();\n\n/**\n * WordPress User Roles\n *\n * @global WP_Roles $wp_roles\n * @since 2.0.0\n */\n$GLOBALS[\'wp_roles\'] = new WP_Roles();\n\n/**\n * テーマが読み込まれる前に発生します。\n *\n * @since 2.6.0\n */\ndo_action( \'setup_theme\' );\n\n// テンプレート関連定数を定義します。\nwp_templating_constants();\n\n// デフォルトのテキストローカライゼーションドメインを読み込む。\nload_default_textdomain();\n\n$locale      = get_locale();\n$locale_file = WP_LANG_DIR . \"/$locale.php\";\nif ( ( 0 === validate_file( $locale ) ) && is_readable( $locale_file ) ) {\n	require( $locale_file );\n}\nunset( $locale_file );\n\n/**\n * ロケールドメインの日付とさまざまな文字列をロードするためのWordPress Localeオブジェクト。\n *\n * @global WP_Locale $wp_locale\n * @since 2.1.0\n */\n$GLOBALS[\'wp_locale\'] = new WP_Locale();\n\n/**\n *  ロケールを切り替えるためのWordPress Locale Switcherオブジェクト\n *\n * @since 4.7.0\n *\n * @global WP_Locale_Switcher $ wp_locale_switcher WordPressロケール切り替えオブジェクト。\n */\n$GLOBALS[\'wp_locale_switcher\'] = new WP_Locale_Switcher();\n$GLOBALS[\'wp_locale_switcher\']--->init();\n\n// 該当する場合は、親テーマと子テーマの両方について、アクティブなテーマの機能をロードします。\nforeach ( wp_get_active_and_valid_themes() as $theme ) {\n	if ( file_exists( $theme . \'/functions.php\' ) ) {\n		include $theme . \'/functions.php\';\n	}\n}\nunset( $theme );\n\n/**\n * テーマが読まれた後に起動する\n *\n * @since 3.0.0\n */\ndo_action( \'after_setup_theme\' );\n\n// 現在のユーザーを設定します。\n$GLOBALS[\'wp\']-&gt;init();\n\n/**\n * WordPressの読み込みが完了した後、ヘッダーが送信される前に起動ます。\n *\n * WPの大部分はこの段階でロードされ、ユーザーは認証されます。\n * WPは{@see \'init\'}フック（例えばウィジェット）に読み込みそれに続いて読み込まれます、多くのプラグインがインスタンス化します\n * WP自身はあらゆる種類の理由で分類します。（例えば、ユーザー、タクソノミーなど）\n *\n * WPがロードされた後にアクションをプラグインしたい場合は、以下の{@see \'wp_loaded\'}フックを使用してください。\n *\n * @since 1.5.0\n */\ndo_action( \'init\' );\n\n// マルチサイトの場合\nif ( is_multisite() ) {\n	if ( true !== ( $file = ms_site_check() ) ) {\n		require( $file );\n		die();\n	}\n	unset( $file );\n}\n\n/**\n * このフックは、WP、すべてのプラグイン、およびテーマが完全に読み込まれてインスタンス化されると起動します。\n *\n * Ajaxリクエストはwp-admin / admin-ajax.phpを使うべきです。\n * ajax.phpは、ログインしていないユーザーに対するリクエストを処理できます。\n * @link https://codex.wordpress.org/AJAX_in_Plugins\n *\n * @since 3.0.0\n */\ndo_action( \'wp_loaded\' );\n\n</pre>\n\n<!-- wp:heading {\"level\":3} -->\n<h3></h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2> まとめ：このファイルで行ってること </h2>\n<!-- /wp:heading -->\n\n<p>・</p>\n\n<!-- wp:heading -->\n<h2> おまけ：このファイルで使われた関数 </h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3> php関数 </h3>\n<!-- /wp:heading -->\n\n<p>date_default_timezone_set( \'UTC\' );</p>\n<p></p>\n<p>register_shutdown_function( \'関数名\' );</p>\n<p>シャットダウン時に実行する関数を登録します</p>\n<p></p>\n<h4>$GLOBALS[\' 変数名 \']</h4>\n<p>phpの定義済み変数のうち、$GLOBALS（グローバル変数）は</p>\n<p>できる変数です。</p>\n<p></p>\n<p>ex)</p>\n<p>この関数に関しては詳しくは以下のページにて↓</p>\n<p></p>\n<p></p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3> wp関数 </h3>\n<!-- /wp:heading -->\n\n<p>いろいろありましたが、大事そうなやつだけピックアップ。</p>\n<p></p>\n<p>wp_initial_constants();</p>\n<p>wp_unregister_GLOBALS();</p>\n<p>wp_favicon_request();</p>\n<p>wp_maintenance();</p>\n<p>timer_start();</p>\n<p>wp_debug_mode();</p>\n<p></p>\n<p>apply_filters();</p>\n<p></p>\n<p>wp_not_installed();</p>\n<p>wp_plugin_directory_constants();</p>\n<p>wp_set_internal_encoding();</p>\n<p>wp_functionality_constants();</p>','wp-setting.phpを解読してみた','','inherit','closed','closed','','1816-revision-v1','','','2019-05-30 14:44:45','2019-05-30 05:44:45','',1816,'http://localhost:8080/anothor/1816-revision-v1',0,'revision','',0),(2211,1,'2019-05-30 15:02:40','2019-05-30 06:02:40','<!-- wp:heading -->\n<h2> wordpressにおけるwp-setting.phpとは </h2>\n<!-- /wp:heading -->\n\n<!-- wp:image {\"id\":2185} -->\n<figure class=\"wp-block-image\"><img src=\"http://localhost:8080/wp-content/uploads/2019/05/wp_core-flow-640x663.png\" alt=\"\" class=\"wp-image-2185\"/></figure>\n<!-- /wp:image -->\n\n<p>wp-setting.phpはwordpressのコアファイルを読み込んでいく際のおよそ3番目に読まれるファイルになります。</p>\n<p> </p>\n<p>wp-load.php</p>\n<p>↓</p>\n<p>wp-config.php</p>\n<p>↓</p>\n<p><strong><span style=\"color: #ff0000;\">wp-setting.php</span></strong></p>\n<p>↓</p>\n<p>・wordpressのコアファイル群</p>\n<p>・/wp-include/wp-db.php（データベースに接続しているファイル）</p>\n<p> </p>\n<p>wp-setting.phpで行っていることはざっくりいうと、wordpressを起動させる際の設定をし、コアファイルたちを次々実行していき実質的にwordpressを起動させるファイルになります。</p>\n<p> </p>\n<p> </p>\n\n<!-- wp:heading -->\n<h2> 実際に翻訳してみた </h2>\n<!-- /wp:heading -->\n\n<p>400行ちょっとあるファイルなので行っている処理ごとに分割していきます。</p>\n<p> </p>\n\n<!-- wp:heading -->\n<h2>冒頭～メンテナンスモードまで</h2>\n<!-- /wp:heading -->\n\n<p>行数でいえば、最初から70行目あたりまで。</p>\n<p>wp_debug_mode();という関数があるとこまでです。</p>\n<pre class=\"lang:php decode:true\" title=\"wp-setting.php\">&lt;?php\n/**\n * 一般的な変数を設定および修正するために使用され、\n * WordPressの手続き型およびクラスライブラリを含みます。\n *\n * wp-config.phpでの設定を許可します（default-constants.phpを参照）\n *\n * @package WordPress\n */\n\n/**\n * WordPressの関数、クラス、およびコアコンテンツのディレクトリの場所を格納します。\n *\n * @since 1.0.0\n */\n\n//「WPINC」をwp-includesディレクトリと定義する\ndefine( \'WPINC\', \'wp-includes\' );\n\n// 初期化に必要なファイルを含めます。\nrequire( ABSPATH . WPINC . \'/load.php\' );\nrequire( ABSPATH . WPINC . \'/default-constants.php\' );\nrequire_once( ABSPATH . WPINC . \'/plugin.php\' );\n\n/*\n * これらはversion.phpで直接グローバル化することはできません。 更新するとき、\n * 私たちは他のインストールからのversion.phpをインクルードしています。\n * そしてすでに設定されているならこれらの値を上書きされたくないです。\n */\n\n//以下の変数をグローバル宣言する\nglobal $wp_version, $wp_db_version, $tinymce_version, $required_php_version, $required_mysql_version, $wp_local_package;\n//ドキュメントルート/wp-includes/version.phpを読み込む\nrequire( ABSPATH . WPINC . \'/version.php\' );\n\n/**\n * まだ設定されていない場合 blog_idは単一サイト設定でデフォルトの1になります。\n * マルチサイトでは、ms-settings.phpでデフォルトで上書きされます。\n *\n * @global int $blog_id\n * @since 2.0.0\n */\n//\nglobal $blog_id;\n\n// WP_MEMORY_LIMIT、WP_MAX_MEMORY_LIMIT、WP_DEBUG、SCRIPT_DEBUG、WP_CONTENT_DIRおよびWP_CACHEを含む初期デフォルト定数を設定します。\nwp_initial_constants();\n\n// 必要なPHPバージョンとMySQLエクステンションまたはデータベースドロップインをチェックしてください。\nwp_check_php_mysql_versions();\n\n// 実行時にマジッククォートを無効にします。魔法の引用符は後でwp-settings.phpでwpdbを使って追加されます\n@ini_set( \'magic_quotes_runtime\', 0 );\n@ini_set( \'magic_quotes_sybase\', 0 );\n\n// WordPressはUTCからのオフセットを計算します。\ndate_default_timezone_set( \'UTC\' );\n\n// register_globalsをオフにします。\nwp_unregister_GLOBALS();\n\n// 設定間で$ _SERVER変数を標準化します。\nwp_fix_server_vars();\n\n// favicon.icoが見つからないため、リクエストを受信したかどうかを確認します\nwp_favicon_request();\n\n// メンテナンスモードになっているか確認してください。\nwp_maintenance();\n</pre>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n\n<!-- wp:heading -->\n<h2>メンテナンスモード～ コアファイルの読み込みまで </h2>\n<!-- /wp:heading -->\n\n<p>行数でいえば、最初から71～152行目あたりまで。</p>\n<p>wp_not_installed();という関数があるとこまでです。</p>\n<p></p>\n<p>&nbsp;</p>\n<pre class=\"\">// タイマーをロードします。\ntimer_start();\n\n// WP_DEBUGモードになっているか確認してください。\nwp_debug_mode();\n\n/**\n * advanced-cache.phpドロップインのロードを有効にするかどうかをフィルタリングします。\n *\n * このフィルタはプラグインによって使用される前に実行されます。 Web以外のランタイム用に設計されています。\n * falseが返された場合、advanced-cache.phpはロードされません。\n *\n * @since 4.6.0\n *\n * @param bool $enable_advanced_cache_advanced-cache.php（存在する場合）の読み込みを有効にするかどうか\n *                                    Default true.\n */\n\nif ( WP_CACHE &amp;&amp; apply_filters( \'enable_loading_advanced_cache_dropin\', true ) ) {\n	// 高度なキャッシングプラグインを使うために。必要なのは静的ドロップインだけです。\n	WP_DEBUG ? include( WP_CONTENT_DIR . \'/advanced-cache.php\' ) : @include( WP_CONTENT_DIR . \'/advanced-cache.php\' );\n\n	// advanced-cache.phpによって手動で追加されたフックを再初期化します\n	if ( $wp_filter ) {\n		$wp_filter = WP_Hook::build_preinitialized_hooks( $wp_filter );\n	}\n}\n\n// 設定されていない場合はWP_LANG_DIRを定義します。\nwp_set_lang_dir();\n\n// 初期のWordPressファイルを読み込む.\nrequire( ABSPATH . WPINC . \'/compat.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-list-util.php\' );\nrequire( ABSPATH . WPINC . \'/formatting.php\' );\nrequire( ABSPATH . WPINC . \'/meta.php\' );\nrequire( ABSPATH . WPINC . \'/functions.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-meta-query.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-matchesmapregex.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-error.php\' );\nrequire( ABSPATH . WPINC . \'/pomo/mo.php\' );\n\n// wpdbクラスと、存在する場合はdb.phpデータベースドロップインを含めます。\nglobal $wpdb;\nrequire_wp_db();\n\n// データベーステーブルのプレフィックスとデータベーステーブル列のフォーマット指定子を設定します。\n$GLOBALS[\'table_prefix\'] = $table_prefix;\nwp_set_wpdb_vars();\n\n// WordPressオブジェクトキャッシュ、またはドロップインが存在する場合は外部オブジェクトキャッシュを起動します。\nwp_start_object_cache();\n\n// デフォルトのフィルタを添付してください。\nrequire( ABSPATH . WPINC . \'/default-filters.php\' );\n\n// 有効な場合はマルチサイトを初期化します。\nif ( is_multisite() ) {\n	require( ABSPATH . WPINC . \'/class-wp-site-query.php\' );\n	require( ABSPATH . WPINC . \'/class-wp-network-query.php\' );\n	require( ABSPATH . WPINC . \'/ms-blogs.php\' );\n	require( ABSPATH . WPINC . \'/ms-settings.php\' );\n} elseif ( ! defined( \'MULTISITE\' ) ) {\n	define( \'MULTISITE\', false );\n}\n\n//関数：shutdown_action_hookをシャットダウン時に実行する\nregister_shutdown_function( \'shutdown_action_hook\' );\n\n// 基本的な機能を使いたいだけなら、大半のWordPressをロードしないようにしてください。\nif ( SHORTINIT ) {\n	return false;\n}\n\n// L10nライブラリをロードする\nrequire_once( ABSPATH . WPINC . \'/l10n.php\' );\nrequire_once( ABSPATH . WPINC . \'/class-wp-locale.php\' );\nrequire_once( ABSPATH . WPINC . \'/class-wp-locale-switcher.php\' );\n\n// WordPressがインストールされていない場合はインストーラを実行してください\nwp_not_installed();\n</pre>\n<p>&nbsp;</p>\n\n<!-- wp:heading -->\n<h2> コアファイルの読み込み ～ まで</h2>\n<!-- /wp:heading -->\n\n<pre class=\"\"><!--?php\n/**\n * 一般的な変数を設定および修正するために使用され、\n * WordPressの手続き型およびクラスライブラリを含みます。\n *\n * wp-config.phpでの設定を許可します（default-constants.phpを参照）\n *\n * @package WordPress\n */\n\n/**\n * WordPressの関数、クラス、およびコアコンテンツのディレクトリの場所を格納します。\n *\n * @since 1.0.0\n */\n\n//「WPINC」をwp-includesディレクトリと定義する\ndefine( \'WPINC\', \'wp-includes\' );\n\n// 初期化に必要なファイルを含めます。\nrequire( ABSPATH . WPINC . \'/load.php\' );\nrequire( ABSPATH . WPINC . \'/default-constants.php\' );\nrequire_once( ABSPATH . WPINC . \'/plugin.php\' );\n\n/*\n * これらはversion.phpで直接グローバル化することはできません。 更新するとき、\n * 私たちは他のインストールからのversion.phpをインクルードしています。\n * そしてすでに設定されているならこれらの値を上書きされたくないです。\n */\n\n//以下の変数をグローバル宣言する\nglobal $wp_version, $wp_db_version, $tinymce_version, $required_php_version, $required_mysql_version, $wp_local_package;\n//ドキュメントルート/wp-includes/version.phpを読み込む\nrequire( ABSPATH . WPINC . \'/version.php\' );\n\n/**\n * まだ設定されていない場合 blog_idは単一サイト設定でデフォルトの1になります。\n * マルチサイトでは、ms-settings.phpでデフォルトで上書きされます。\n *\n * @global int $blog_id\n * @since 2.0.0\n */\n//\nglobal $blog_id;\n\n// WP_MEMORY_LIMIT、WP_MAX_MEMORY_LIMIT、WP_DEBUG、SCRIPT_DEBUG、WP_CONTENT_DIRおよびWP_CACHEを含む初期デフォルト定数を設定します。\nwp_initial_constants();\n\n// 必要なPHPバージョンとMySQLエクステンションまたはデータベースドロップインをチェックしてください。\nwp_check_php_mysql_versions();\n\n// 実行時にマジッククォートを無効にします。魔法の引用符は後でwp-settings.phpでwpdbを使って追加されます\n@ini_set( \'magic_quotes_runtime\', 0 );\n@ini_set( \'magic_quotes_sybase\', 0 );\n\n// WordPressはUTCからのオフセットを計算します。\ndate_default_timezone_set( \'UTC\' );\n\n// register_globalsをオフにします。\nwp_unregister_GLOBALS();\n\n// 設定間で$ _SERVER変数を標準化します。\nwp_fix_server_vars();\n\n// favicon.icoが見つからないため、リクエストを受信したかどうかを確認します\nwp_favicon_request();\n\n// メンテナンスモードになっているか確認してください。\nwp_maintenance();\n\n// タイマーをロードします。\ntimer_start();\n\n// WP_DEBUGモードになっているか確認してください。\nwp_debug_mode();\n\n/**\n * advanced-cache.phpドロップインのロードを有効にするかどうかをフィルタリングします。\n *\n * このフィルタはプラグインによって使用される前に実行されます。 Web以外のランタイム用に設計されています。\n * falseが返された場合、advanced-cache.phpはロードされません。\n *\n * @since 4.6.0\n *\n * @param bool $enable_advanced_cache_advanced-cache.php（存在する場合）の読み込みを有効にするかどうか\n *                                    Default true.\n */\n\nif ( WP_CACHE && apply_filters( \'enable_loading_advanced_cache_dropin\', true ) ) {\n	// 高度なキャッシングプラグインを使うために。必要なのは静的ドロップインだけです。\n	WP_DEBUG ? include( WP_CONTENT_DIR . \'/advanced-cache.php\' ) : @include( WP_CONTENT_DIR . \'/advanced-cache.php\' );\n\n	// advanced-cache.phpによって手動で追加されたフックを再初期化します\n	if ( $wp_filter ) {\n		$wp_filter = WP_Hook::build_preinitialized_hooks( $wp_filter );\n	}\n}\n\n// 設定されていない場合はWP_LANG_DIRを定義します。\nwp_set_lang_dir();\n\n// 初期のWordPressファイルを読み込む.\nrequire( ABSPATH . WPINC . \'/compat.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-list-util.php\' );\nrequire( ABSPATH . WPINC . \'/formatting.php\' );\nrequire( ABSPATH . WPINC . \'/meta.php\' );\nrequire( ABSPATH . WPINC . \'/functions.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-meta-query.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-matchesmapregex.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-error.php\' );\nrequire( ABSPATH . WPINC . \'/pomo/mo.php\' );\n\n// wpdbクラスと、存在する場合はdb.phpデータベースドロップインを含めます。\nglobal $wpdb;\nrequire_wp_db();\n\n// データベーステーブルのプレフィックスとデータベーステーブル列のフォーマット指定子を設定します。\n$GLOBALS[\'table_prefix\'] = $table_prefix;\nwp_set_wpdb_vars();\n\n// WordPressオブジェクトキャッシュ、またはドロップインが存在する場合は外部オブジェクトキャッシュを起動します。\nwp_start_object_cache();\n\n// デフォルトのフィルタを添付してください。\nrequir