require( ABSPATH . WPINC . \'/class-wp-oembed-controller.php\' );\nrequire( ABSPATH . WPINC . \'/media.php\' );\nrequire( ABSPATH . WPINC . \'/http.php\' );\nrequire( ABSPATH . WPINC . \'/class-http.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-streams.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-curl.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-proxy.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-cookie.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-encoding.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-response.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-requests-response.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-http-requests-hooks.php\' );\nrequire( ABSPATH . WPINC . \'/widgets.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-widget.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-widget-factory.php\' );\nrequire( ABSPATH . WPINC . \'/nav-menu.php\' );\nrequire( ABSPATH . WPINC . \'/nav-menu-template.php\' );\nrequire( ABSPATH . WPINC . \'/admin-bar.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/class-wp-rest-server.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/class-wp-rest-response.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/class-wp-rest-request.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-posts-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-attachments-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-post-types-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-post-statuses-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-revisions-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-autosaves-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-taxonomies-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-terms-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-users-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-comments-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-search-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-blocks-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-block-renderer-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-settings-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/endpoints/class-wp-rest-themes-controller.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-comment-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-post-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-term-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/fields/class-wp-rest-user-meta-fields.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/search/class-wp-rest-search-handler.php\' );\nrequire( ABSPATH . WPINC . \'/rest-api/search/class-wp-rest-post-search-handler.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-block-type.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-block-type-registry.php\' );\nrequire( ABSPATH . WPINC . \'/class-wp-block-parser.php\' );\nrequire( ABSPATH . WPINC . \'/blocks.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/archives.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/block.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/categories.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/latest-comments.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/latest-posts.php\' );\nrequire( ABSPATH . WPINC . \'/blocks/shortcode.php\' );\n\n$GLOBALS[\'wp_embed\'] = new WP_Embed();\n\n// マルチサイト固有のファイルをロードします。\nif ( is_multisite() ) {\n	require( ABSPATH . WPINC . \'/ms-functions.php\' );\n	require( ABSPATH . WPINC . \'/ms-default-filters.php\' );\n	require( ABSPATH . WPINC . \'/ms-deprecated.php\' );\n}\n\n// デフォルト値を取得するためにAPIに依存する定数を定義します。\n// sunrise.phpドロップインで上書きされる可能性のある、必ず使用するプラグインディレクトリ定数を定義します。.\nwp_plugin_directory_constants();\n\n$GLOBALS[\'wp_plugin_paths\'] = array();\n\n// マストユーズプラグインをロードします\nforeach ( wp_get_mu_plugins() as $mu_plugin ) {\n	include_once( $mu_plugin );\n\n	/**\n	 * 一つのマストユーズプラグインがロードされたら起動する\n	 *\n	 * @since 5.1.0\n	 *\n	 * @param string $mu_plugin Full path to the plugin\'s main file.\n	 */\n	do_action( \'mu_plugin_loaded\', $mu_plugin );\n}\nunset( $mu_plugin );\n\n// ネットワーク起動プラグインをロードします\nif ( is_multisite() ) {\n	foreach ( wp_get_active_network_plugins() as $network_plugin ) {\n		wp_register_plugin_realpath( $network_plugin );\n		include_once( $network_plugin );\n\n		/**\n		 * 一つのネットワーク起動プラグインがロードされたら起動する\n		 *\n		 * @since 5.1.0\n		 *\n		 * @param string $network_plugin Full path to the plugin\'s main file.\n		 */\n		do_action( \'network_plugin_loaded\', $network_plugin );\n	}\n	unset( $network_plugin );\n}\n\n/**\n * すべての必須使用およびネットワーク起動プラグインがロードされると起動します。\n *\n * @since 2.8.0\n */\n\n//関数：muplugins_loadedを実行する\ndo_action( \'muplugins_loaded\' );\n\nif ( is_multisite() ) {\n	ms_cookie_constants();\n}\n\n// マルチサイトがロードされた後に定数を定義します。\nwp_cookie_constants();\n\n// SSL定数を定義して実施する\nwp_ssl_constants();\n\n// 共通グローバルを作成する\nrequire( ABSPATH . WPINC . \'/vars.php\' );\n\n// タクソノミーや投稿をプラグインやテーマで利用できるようにします。\n// @プラグインの作成者：警告：これらはinitフックに再度登録されます。\ncreate_initial_taxonomies();\ncreate_initial_post_types();\n\nwp_start_scraping_edited_file_errors();\n\n// デフォルトのテーマディレクトリのルートを登録する\nregister_theme_directory( get_theme_root() );\n\n// 有効化されてるプラグインをよみこむ\nforeach ( wp_get_active_and_valid_plugins() as $plugin ) {\n	wp_register_plugin_realpath( $plugin );\n	include_once( $plugin );\n\n	/**\n	 * 一度有効化されたプラグインをよみこむと起動する\n	 *\n	 * @since 5.1.0\n	 *\n	 * @param string $plugin Full path to the plugin\'s main file.\n	 */\n	do_action( \'plugin_loaded\', $plugin );\n}\nunset( $plugin );\n\n// プラガブル関数を読み込む.\nrequire( ABSPATH . WPINC . \'/pluggable.php\' );\nrequire( ABSPATH . WPINC . \'/pluggable-deprecated.php\' );\n\n// 内部エンコーディングを設定します。\nwp_set_internal_encoding();\n\n// オブジェクトキャッシュが有効で、関数が存在する場合は、wp_cache_postload（）を実行する\nif ( WP_CACHE && function_exists( \'wp_cache_postload\' ) ) {\n	wp_cache_postload();\n}\n\n/**\n * 一度有効化されたプラグインをよみこむと起動する\n *\n * 読み込まれているこの時点でプラガブル機能も利用可能です。\n *\n * @since 1.5.0\n */\ndo_action( \'plugins_loaded\' );\n\n// まだ定義されていない場合、機能に影響を与える定数を定義します。\nwp_functionality_constants();\n\n// マジッククオートを追加して$ _REQUEST（$ _GET + $ _POST）を設定する\nwp_magic_quotes();\n\n/**\n * コメントクッキーがサニタイズされたときに起動します。\n *\n * @since 2.0.11\n */\ndo_action( \'sanitize_comment_cookies\' );\n\n/**\n * WordPress Query object\n *\n * @global WP_Query $wp_the_query\n * @since 2.0.0\n */\n$GLOBALS[\'wp_the_query\'] = new WP_Query();\n\n/**\n * $ wp_the_queryへの参照を保持しています\n * WordPressクエリにこのグローバルを使用\n *\n * @global WP_Query $wp_query\n * @since 1.5.0\n */\n$GLOBALS[\'wp_query\'] = $GLOBALS[\'wp_the_query\'];\n\n/**\n * きれいなURLを作成するためのWordPressリライトオブジェクトを保持します。\n * @global WP_Rewrite $wp_rewrite\n * @since 1.5.0\n */\n$GLOBALS[\'wp_rewrite\'] = new WP_Rewrite();\n\n/**\n * WordPress オブジェクト\n *\n * @global WP $wp\n * @since 2.0.0\n */\n$GLOBALS[\'wp\'] = new WP();\n\n/**\n * WordPress Widget Factory Object\n *\n * @global WP_Widget_Factory $wp_widget_factory\n * @since 2.8.0\n */\n$GLOBALS[\'wp_widget_factory\'] = new WP_Widget_Factory();\n\n/**\n * WordPress User Roles\n *\n * @global WP_Roles $wp_roles\n * @since 2.0.0\n */\n$GLOBALS[\'wp_roles\'] = new WP_Roles();\n\n/**\n * テーマが読み込まれる前に発生します。\n *\n * @since 2.6.0\n */\ndo_action( \'setup_theme\' );\n\n// テンプレート関連定数を定義します。\nwp_templating_constants();\n\n// デフォルトのテキストローカライゼーションドメインを読み込む。\nload_default_textdomain();\n\n$locale      = get_locale();\n$locale_file = WP_LANG_DIR . \"/$locale.php\";\nif ( ( 0 === validate_file( $locale ) ) && is_readable( $locale_file ) ) {\n	require( $locale_file );\n}\nunset( $locale_file );\n\n/**\n * ロケールドメインの日付とさまざまな文字列をロードするためのWordPress Localeオブジェクト。\n *\n * @global WP_Locale $wp_locale\n * @since 2.1.0\n */\n$GLOBALS[\'wp_locale\'] = new WP_Locale();\n\n/**\n *  ロケールを切り替えるためのWordPress Locale Switcherオブジェクト\n *\n * @since 4.7.0\n *\n * @global WP_Locale_Switcher $ wp_locale_switcher WordPressロケール切り替えオブジェクト。\n */\n$GLOBALS[\'wp_locale_switcher\'] = new WP_Locale_Switcher();\n$GLOBALS[\'wp_locale_switcher\']--->init();\n\n// 該当する場合は、親テーマと子テーマの両方について、アクティブなテーマの機能をロードします。\nforeach ( wp_get_active_and_valid_themes() as $theme ) {\n	if ( file_exists( $theme . \'/functions.php\' ) ) {\n		include $theme . \'/functions.php\';\n	}\n}\nunset( $theme );\n\n/**\n * テーマが読まれた後に起動する\n *\n * @since 3.0.0\n */\ndo_action( \'after_setup_theme\' );\n\n// 現在のユーザーを設定します。\n$GLOBALS[\'wp\']-&gt;init();\n\n/**\n * WordPressの読み込みが完了した後、ヘッダーが送信される前に起動ます。\n *\n * WPの大部分はこの段階でロードされ、ユーザーは認証されます。\n * WPは{@see \'init\'}フック（例えばウィジェット）に読み込みそれに続いて読み込まれます、多くのプラグインがインスタンス化します\n * WP自身はあらゆる種類の理由で分類します。（例えば、ユーザー、タクソノミーなど）\n *\n * WPがロードされた後にアクションをプラグインしたい場合は、以下の{@see \'wp_loaded\'}フックを使用してください。\n *\n * @since 1.5.0\n */\ndo_action( \'init\' );\n\n// マルチサイトの場合\nif ( is_multisite() ) {\n	if ( true !== ( $file = ms_site_check() ) ) {\n		require( $file );\n		die();\n	}\n	unset( $file );\n}\n\n/**\n * このフックは、WP、すべてのプラグイン、およびテーマが完全に読み込まれてインスタンス化されると起動します。\n *\n * Ajaxリクエストはwp-admin / admin-ajax.phpを使うべきです。\n * ajax.phpは、ログインしていないユーザーに対するリクエストを処理できます。\n * @link https://codex.wordpress.org/AJAX_in_Plugins\n *\n * @since 3.0.0\n */\ndo_action( \'wp_loaded\' );\n\n</pre>\n\n<!-- wp:heading {\"level\":3} -->\n<h3></h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2> まとめ：このファイルで行ってること </h2>\n<!-- /wp:heading -->\n\n<p>・</p>\n\n<!-- wp:heading -->\n<h2> おまけ：このファイルで使われた関数 </h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3> php関数 </h3>\n<!-- /wp:heading -->\n\n<p>date_default_timezone_set( \'UTC\' );</p>\n<p></p>\n<p>register_shutdown_function( \'関数名\' );</p>\n<p>シャットダウン時に実行する関数を登録します</p>\n<p></p>\n<h4>$GLOBALS[\' 変数名 \']</h4>\n<p>phpの定義済み変数のうち、$GLOBALS（グローバル変数）は</p>\n<p>できる変数です。</p>\n<p></p>\n<p>ex)</p>\n<p>この関数に関しては詳しくは以下のページにて↓</p>\n<p></p>\n<p></p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3> wp関数 </h3>\n<!-- /wp:heading -->\n\n<p>いろいろありましたが、大事そうなやつだけピックアップ。</p>\n<p></p>\n<p>wp_initial_constants();</p>\n<p>wp_unregister_GLOBALS();</p>\n<p>wp_favicon_request();</p>\n<p>wp_maintenance();</p>\n<p>timer_start();</p>\n<p>wp_debug_mode();</p>\n<p></p>\n<p>apply_filters();</p>\n<p></p>\n<p>wp_not_installed();</p>\n<p>wp_plugin_directory_constants();</p>\n<p>wp_set_internal_encoding();</p>\n<p>wp_functionality_constants();</p>','wp-setting.phpを解読してみた','','inherit','closed','closed','','1816-revision-v1','','','2019-06-03 09:35:21','2019-06-03 00:35:21','',1816,'http://localhost:8080/anothor/1816-revision-v1',0,'revision','',0),(2351,0,'2019-10-04 11:46:45','2019-10-04 02:46:45','<p>プロフェッショナルに出てくるcloudfrontはざっくり言うと以下の内容が多いんじゃないかなと思います。</p>\n<p>↓</p>\n<p>・ディストリビューション</p>\n<p>・HTTPS通信</p>\n<p>・コンテンツを提供するユーザを限定したい時</p>\n<p>・キャッシュ</p>\n<p>・DDos攻撃を防ぐ手段の一つとして</p>\n\n<!-- wp:heading -->\n<h2>ディストリビューション</h2>\n<!-- /wp:heading -->\n\n<p>Lambda @ Edge</p>\n<p>udemy2-56</p>\n\n<!-- wp:heading -->\n<h2>HTTPS通信</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>エンドツーエンドのHTTPS通信</h3>\n<!-- /wp:heading -->\n\n<p>エンドツーエンドと言うのは、端から端まで、つまりビューワーからオリジンまでを意味します。</p>\n<p>図</p>\n<p></p>\n<p>エンドツーエンドHTTPS通信をするには、２つの証明書を適用する必要があります。</p>\n<p>⑴ ビューワーからcloudfront間</p>\n<p>⑵ cloudfrontからオリジンの間</p>\n<p></p>\n<h4>⑴ ビューワーからcloudfront間</h4>\n<p>証明書をcloudfrontに入れることで、ビューワーからcloudfront間のHTTPS通信が有効になります。</p>\n<p>ビューワーからcloudfrontの間には３種類の証明書を入れることが出来ます。</p>\n<p>１、ACM（AWS Certificate Manager）が提供する証明書</p>\n<p>２、信頼できるCAからの証明書（symantec）</p>\n<p>３、オレオレ証明書（自己署名証明書）</p>\n<p></p>\n<h4>⑵ cloudfrontからオリジンの間</h4>\n<p>証明書をオリジンに入れることで、cloudfrontからオリジンの間のHTTPS通信が有効になります。</p>\n<p>cloudfrontからオリジンの間で使える証明書はオリジンが何であるかによって異なります。</p>\n<p>オリジンが ELBやEC2の場合：</p>\n<p></p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>ビューアプロトコルポリシーとオリジンプロトコルポリシー</h3>\n<!-- /wp:heading -->\n\n<p>プロトコルポリシーとは、ざっくり言うとcloudfrontの通信をHTTPにするかHTTPSにするかを定義するものになります。</p>\n<p></p>\n<p>上記の⑴のビューワーとCloudFront間のプロトコルを決めるのが<strong>「ビューアープロトコルポリシー」</strong></p>\n<p>⑵のcloudfrontからオリジンの間を決めるのが「<strong>オリジンプロトコルポリシー」</strong>になります。</p>\n<p></p>\n<h4>ビューワープロトコルポリシー</h4>\n<p>ビューワープロトコルポリシーは</p>\n<p>・HTTPとHTTPSに両方使う</p>\n<p>・HTTPSのみにする</p>\n<p>・すべてのHTTPリクエストをHTTPSにリダイレクトする</p>\n<p></p>\n<p>具体的に定義する方法：</p>\n<p>１、CloudFrontディストリビューションを作成する</p>\n<p>２、ビューアープロトコルポリシーに以下の設定する</p>\n<p>・HTTP＆HTTPSにする→<span style=\"color: #ff0000;\">HTTP and HTTPS</span></p>\n<p>・HTTPSのみにする→<span style=\"color: #ff0000;\">HTTPS only</span></p>\n<p>・すべてのHTTPリクエストをHTTPSにリダイレクトする→<span style=\"color: #ff0000;\">Redirect HTTP to HTTPS</span></p>\n<p></p>\n<h4>オリジンプロトコルポリシー</h4>\n<p>オリジンプロトコルポリシーは、</p>\n<p></p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>練習問題</h3>\n<!-- /wp:heading -->\n\n<p>例題は３問。</p>\n<p>例題１）</p>\n<p>ユーザーのブラウザから CloudFront 経由でエンドツーエンドの HTTPS 接続を有効にするには、以下のオプションのどれが有効ですか。（3 つの回答を選択)</p>\n<p></p>\n<p>１、ビューワーはサードパーティCA 証明書を使用する。CloudFront は自己署名証明書を使用する</p>\n<p>２、ビューワーと CloudFront との間の HTTPS 通信でサードパーティの CA 証明書を使用する</p>\n<p>３、ビューワーと CloudFront との間の HTTPS 通信で自己署名証明書を使用します</p>\n<p>４、CloudFront とオリジンとの間の HTTPS 通信で自己署名証明書を使用します</p>\n<p>５、CloudFront とオリジンとの間の HTTPS 通信で自己署名証明書を使用します。(オリジンが ELB ロードバランサー (Amazon EC2 など) でない場合)</p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p>答え：１、２、３</p>\n<p>解説：</p>\n<p></p>\n<p></p>\n<p>例題２）</p>\n<p>世界中で電気自動車を販売する自動化会社は、「自動操縦」機能とも呼ばれる半自動運転技術を備えた最新の自動車モデルをリリースします。新製品の人気のため、静的アセットのキャッシュにCloudFrontを使用して、世界中の視聴者への新しいモデルの画像やその他の静的コンテンツの配信を高速化することを計画しています。静的コンテンツは、独自のドメイン名を使用してHTTPS経由で配信する必要があります。これにより、Webサイトの訪問者はSSL接続で必要なセキュリティに加えて、遅延が少なく信頼性が高くなります。CloudFrontを使用してこのセットアップをAWSに実装するにはどうすればよいですか？（2つ選択）</p>\n<p></p>\n<p>⑴ AWS Certificate Manager（ACM）に保存されているデフォルトのCloudFront証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑵ AWS Certificate Manager（ACM）に保存されているカスタムSSL証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑶ 署名付きCookieを使用してCloudFrontディストリビューションを作成します。 IAMに保存されているデフォルトのCloudFront証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑷ 署名付きURLを使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑸ IAMに保存されているカスタムSSL証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p>答え：２、５</p>\n<p>解説：</p>\n<p></p>\n<p>例題３）</p>\n<p></p>\n\n<!-- wp:heading -->\n<h2>コンテンツを提供するユーザを限定する</h2>\n<!-- /wp:heading -->\n\n<p>問題でよくあるのが、特定の会員だけプライベートコンテンツを見せるにはどうしたらいいか？というもの。</p>\n<p></p>\n<p>署名付きURL</p>\n<p>署名付きcookie</p>\n<p>OAI</p>\n<p></p>\n<p>信頼できる署名者</p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>練習問題</h3>\n<!-- /wp:heading -->\n\n<p>例題１）</p>\n\n<!-- wp:heading -->\n<h2>キャッシュについて</h2>\n<!-- /wp:heading -->\n\n<p>ttlを０にする</p>\n<p>Cache-Control max-age</p>\n\n<!-- wp:heading -->\n<h2>DDos攻撃を防ぐ</h2>\n<!-- /wp:heading -->\n\n<p>別にDDos攻撃防止だけじゃなく、予期しないトラフィックの増加が見込まれる場合にもcloudfrontは使用されますが。</p>\n<p> </p>','AWS認定ソリューションアーキテクトプロフェッショナル-CloudFrontのまとめ','AWS 認定ソリューションアーキテクト – プロフェッショナルに出てくるcloudfrontの自分用のまとめです。','publish','closed','closed','','certified-solutions-architect-professional-cloudfront','','','2019-10-03 11:19:04','2019-10-03 02:19:04','',0,'http://localhost:8080/?post_type=infrastructure&#038;p=2351',0,'infrastructure','',0),(2354,1,'2019-06-04 11:49:40','2019-06-04 02:49:40','','Amazon-CloudFront@4x','','inherit','open','closed','','amazon-cloudfront4x','','','2019-06-04 11:50:16','2019-06-04 02:50:16','',2351,'http://localhost:8080/wp-content/uploads/2019/06/bc90f48b43ea887ca26661f0e910aa7e.png',0,'attachment','image/png',0),(2509,1,'2019-06-13 17:51:27','2019-06-13 08:51:27','<!-- wp:table -->\n<table class=\"wp-block-table\"><tbody><tr><td></td><td>スコープ</td><td>変数</td><td></td></tr><tr><td></td><td></td><td> ローカル変数 </td><td></td></tr><tr><td></td><td></td><td> グローバル変数 </td><td></td></tr><tr><td></td><td> スタスティックスコープ</td><td>  スタスティック変数 </td><td></td></tr><tr><td></td><td> 関数の引数 </td><td> 関数の引数 </td><td></td></tr></tbody></table>\n<!-- /wp:table -->','無題の再利用ブロック','','publish','closed','closed','','%e7%84%a1%e9%a1%8c%e3%81%ae%e5%86%8d%e5%88%a9%e7%94%a8%e3%83%96%e3%83%ad%e3%83%83%e3%82%af','','','2019-06-13 17:51:27','2019-06-13 08:51:27','',0,'http://localhost:8080/anothor/%e7%84%a1%e9%a1%8c%e3%81%ae%e5%86%8d%e5%88%a9%e7%94%a8%e3%83%96%e3%83%ad%e3%83%83%e3%82%af',0,'wp_block','',0),(2521,1,'2019-08-13 10:30:27','2019-08-13 01:30:27','<h2>このブログについて</h2>\nこのブログは筆者の個人用のメモとして使っております。\n<h2>かいてる人について</h2>\n・平成３年生の女性。\n\n・イヌかネコかと言ったらネコ派。\n\n・観葉植物とスマホアプリの脱出ゲームが好きです。\n\n・絵心は皆無。\n\n持ってる資格\n\n・ 2019/08 AWS ソリューションアーキテクト　アソシエイト','Author','','inherit','closed','closed','','8-revision-v1','','','2019-08-13 10:30:27','2019-08-13 01:30:27','',8,'http://localhost:8080/anothor/8-revision-v1',0,'revision','',0),(2522,1,'2019-08-13 10:31:36','2019-08-13 01:31:36','<h2>このブログについて</h2>\nこのブログは筆者の個人用のメモとして使っております。\n<h2>かいてる人について</h2>\n・平成３年生の女性。\n\n・イヌかネコかと言ったらネコ派。\n\n・観葉植物とスマホアプリの脱出ゲームが好きです。\n\n・絵心は皆無。\n<h2>持ってる資格</h2>\n・ 2019/08 AWS ソリューションアーキテクト　アソシエイト','Author','','inherit','closed','closed','','8-revision-v1','','','2019-08-13 10:31:36','2019-08-13 01:31:36','',8,'http://localhost:8080/anothor/8-revision-v1',0,'revision','',0),(2526,1,'2019-09-05 07:35:00','2019-09-04 22:35:00','<h2>このブログについて</h2>\nこのブログは筆者の個人用のメモとして使っております。\n<h2>かいてる人について</h2>\n・平成３年生の女性。\n\n・イヌかネコかと言ったらネコ派。\n\n・観葉植物とスマホアプリの脱出ゲームが好きです。\n\n・絵心は皆無。\n<h2>持ってる資格</h2>\n・ 2019/08/12   AWS ソリューションアーキテクト　アソシエイト','Author','','inherit','closed','closed','','8-revision-v1','','','2019-09-05 07:35:00','2019-09-04 22:35:00','',8,'http://localhost:8080/anothor/8-revision-v1',0,'revision','',0),(2531,1,'2019-09-13 22:16:56','2019-09-13 13:16:56','<h2>作る目的</h2>\n<p class=\"p1\">これから様々な物を作ってはアップしたいと思っていたので、まずは<span class=\"s1\">wordpress</span>を用いたブログサイトを勉強がてら作ってみようと考えました。</p>\n\n<h2>どんなサイトにしたいか</h2>\n見た目はノート風で以下の内容をまとめたブログサイトにしたい。\n固定ページは・・・\n\n・各カスタム投稿の最新の記事が何件か表示されるトップページ\n\n・筆者のプロフィールページ\n\n・全記事一覧が表示されるサイトマップページ\n\nブログの内容は・・・\n\n・作ったものとその作成手順の記事\n\n・作成した際に使用されたフレームワーク、サーバ、DB、OSの設定などのまとめ\n\n・フレームワークやサーバ、OSの基礎知識\n\n・開発するに当たって便利なツールの使い方まとめ\n\n・webマーケティングのまとめ\n\nなど\n<h2>設計</h2>\n<h4>開発環境</h4>\nOS：windows10\n\nサーバ：xampp\n<h4>本番環境 (2016)</h4>\nserversman@VPS\n\nOS：<span class=\"s1\">CentOS Linux release 7.0.1406 (Core)</span>\n\nhttpd:apache\n\nDB:mysql\n\n言語：php 5.4、JQuery\n\nフレームワーク：wordpress\n<h4>引越し後 (2018)</h4>\nさくらのVPSサーバ\n\nCentOS Linux release 7.2.1511 (Core)\n\nhttpd:nginx 1.12\n\nDB:mariadb\n\n言語：php 7.1、JQuery\n\nフレームワーク：wordpress\n<h4>UI設計</h4>\n<a href=\"http://localhost:8080/development_and_tool/prototype_of_blog/\" target=\"_blank\" rel=\"noopener noreferrer\">このサイト全体の構成をざっくりと図にしてみた<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a>\n<h2>作成フロー</h2>\n<h3 class=\"p1\"><span class=\"s1\">wordpress</span>の開発環境をインストールする<b> </b></h3>\n<p class=\"p2\">まずこのブログにあった<span class=\"s2\">wordpress</span>テーマから作成したいので、ローカル環境をインストールして実験できる環境を整えます。</p>\n<p class=\"p3\"><a href=\"http://localhost:8080/development_and_tool/wordpress_install_xampp\" target=\"_blank\" rel=\"noopener noreferrer\"><span class=\"s3\">XAMPPでwordpressのインストールしてみた<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></span></a></p>\n\n<h3 class=\"p1\">wordpressテーマを作成する<b> </b></h3>\n<p class=\"p2\">ローカル環境が整ったら、テーマを作成します。</p>\n<p class=\"p2\">手順としては<span class=\"s2\">html</span>でサイトの構成を作り、<span class=\"s2\">CSS</span>で装飾や配置を決め、<span class=\"s2\">html</span>ファイルを<span class=\"s2\">php</span>テキストに変換し、<span class=\"s2\">wordpress</span>テーマのフォルダを完成させます。</p>\n\n<h4>2016年</h4>\n<p class=\"p3\"><a href=\"http://localhost:8080/web_and_aplication/css_of_this-blog\" target=\"_blank\" rel=\"noopener noreferrer\"><span class=\"s3\"><span class=\"s4\">・このブログで使ったcss<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></span></span></a></p>\n<p class=\"p3\"><a href=\"http://localhost:8080/web_and_aplication/wp-thema/\" target=\"_blank\" rel=\"noopener noreferrer\"><span class=\"s3\">・wordpressテーマのファイル構成と中身<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></span></a></p>\n\n<h4>それ以降に追加した機能</h4>\n・<a href=\"http://localhost:8080/web_and_aplication/breadcrumb_customtype_and_taxonomy/\" target=\"_blank\" rel=\"noopener noreferrer\">パンくずリストの作り方<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a>\n\n・<a href=\"http://localhost:8080/web_and_aplication/tag-archive\" target=\"_blank\" rel=\"noopener noreferrer\">タグアーカイブ ページの作り方<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a>\n<h3 class=\"p1\">本番サーバの設定</h3>\n<p class=\"p2\">xamppで作った物を本番サーバでアップするにあたって、ドメインとサーバー会社に申し込みます。共有サーバーでもよかったのですが、それだと勉強にならないので<span class=\"s2\">vps</span>サーバーを借りることにしました。</p>\n\n<h4 class=\"p1\">xampp→serversman@VPS（2016）</h4>\n<p class=\"p3\"><span class=\"s4\">1 <span class=\"s5\">, <a href=\"http://localhost:8080/infrastructure/root_login/\" target=\"_blank\" rel=\"noopener noreferrer\">ユーザの追加と<span class=\"s3\">root</span>での接続を禁止する<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a></span></span></p>\n<p class=\"p3\">2<span class=\"s7\">, <a href=\"http://localhost:8080/infrastructure/iptables_centos7/\" target=\"_blank\" rel=\"noopener noreferrer\">Centos7で<span class=\"s9\">iptables<span class=\"s8\">の設定<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></span></span></a><span class=\"s8\">\n</span></span></p>\n<p class=\"p3\"><span class=\"s7\">3 , <a href=\"http://localhost:8080/infrastructure/generating_keys_on_teraterm/\" target=\"_blank\" rel=\"noopener noreferrer\">tera termで<span class=\"s8\">秘密鍵と公開鍵の構築をしてみた<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></span></a></span><span class=\"s7\"><span class=\"s8\">\n</span></span></p>\n<p class=\"p3\">4, <a href=\"http://localhost:8080/backend_and_server/set_apache/\" target=\"_blank\" rel=\"noopener noreferrer\"><span class=\"s4\">web<span class=\"s5\">サーバー（</span><span class=\"s3\">apache</span><span class=\"s5\">）のインストールと初期設定</span></span><img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a></p>\n<p class=\"p3\"><span class=\"s4\">5, <a href=\"http://localhost:8080/backend_and_server/mysql_install_and_setting/\" target=\"_blank\" rel=\"noopener noreferrer\"><span class=\"s3\">MySQL</span><span class=\"s5\">のインストールと初期設定</span><img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a><span class=\"s5\">\n</span></span></p>\n<p class=\"p3\"><a href=\"http://localhost:8080/development_and_tool/deploy_wordpress/\" target=\"_blank\" rel=\"noopener noreferrer\"><span class=\"s4\">6,</span>ローカルにあるxamppからserversman@VPSサーバへWPサイトを引っ越し<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a></p>\n\n<h4 class=\"p1\">serversman@VPS→さくらVPS（2018）</h4>\n1は一緒です。\n<span id=\"selinux\"></span>\n\n<span id=\"selinux\">2 ,<a href=\"http://localhost:8080/infrastructure/setting_centos7/\" target=\"_blank\" rel=\"noopener noreferrer\">Centos7の初期設定<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a></span>\n\n<span class=\"s7\">3, <a href=\"http://localhost:8080/infrastructure/firewalld_centos7/\" target=\"_blank\" rel=\"noopener noreferrer\">Centos7でFirewalld<span class=\"s8\">の設定<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></span></a></span>\n\n<span class=\"s7\"><span class=\"s8\">4, <a href=\"http://localhost:8080/infrastructure/generating_keys_on_openssh/\" target=\"_blank\" rel=\"noopener noreferrer\">Opensshで秘密鍵と公開鍵の構築をしてみた<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a></span></span>\n\n5, <a href=\"http://localhost:8080/backend_and_server/multiple_domein_on_nginx/\" target=\"_blank\" rel=\"noopener noreferrer\">1台のnginx上に複数のドメインでそれぞれのページを表示できるように設定する<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a>\n\n6, <a href=\"http://localhost:8080/infrastructure/ssl_at_lets-encrypt/\" target=\"_blank\" rel=\"noopener noreferrer\">Let’s Encryptを使って無料でSSL設定をする<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a>\n\n7,<a href=\"http://localhost:8080/backend_and_server/lamp_on_virtialhosts/\" target=\"_blank\" rel=\"noopener noreferrer\">,nginxのバーチャルホスト上にLamp環境を作る<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /> </a>\n\n8,<a href=\"http://localhost:8080/development_and_tool/wordpress_on_vertialhosts/\" target=\"_blank\" rel=\"noopener noreferrer\">バーチャルホスト上にwordpressを引っ越しする<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a>\n<h2 class=\"p1\"><b>まとめ</b><b> </b></h2>\n<p class=\"p2\">自作<span class=\"s2\">wordpress</span>テーマを使ったブログサイトを<span class=\"s2\">vps</span>サーバーでアップするに必要なもの・覚えておきたいもの一覧</p>\n<p class=\"p5\"><span class=\"s11\">・テーマの作成</span>→HTML<span class=\"s11\">、</span>CSS<span class=\"s11\">、</span>php<span class=\"s11\">、Jquery、</span>wordpress</p>\n<p class=\"p5\">・sshサーバーにログイン<span class=\"s2\">→ssh</span>、<span class=\"s2\">vi</span>エディタの使い方、<span class=\"s2\">Linux\n</span></p>\n<p class=\"p5\">・セキュリティ <span class=\"s2\">→ssh</span>、パーミッションの知識、SSL/TLS</p>\n<p class=\"p5\">・ファイアーウォールの起動<span class=\"s2\">→iptables,firewalld\n</span></p>\n<p class=\"p5\"><span class=\"s11\">・</span>web<span class=\"s11\">サーバーの設置</span>→Apache,nginx</p>\n<p class=\"p5\">・データベースの設置<span class=\"s2\">→MySQL,mariadb\n</span></p>\n<p class=\"p5\"><span class=\"s11\">・</span>wordpress<span class=\"s11\">の設置</span>→phpmyadmin<span class=\"s11\">、</span>wordpress</p>\n\n\n初めて思いつきで作ってみましたが、背景の木の画像と方眼紙が、文章を見るにはちょっと見づらいかも・・・と感じました。\n\n次また何かアプリを作る際は、もうちょっとUI、UXにも気を配ったものを作りたいと思います。','このブログ','自分が覚えたことや調べたこと、どのように作ったのかを確認するためのノート代わりになるブログをwordpressで作ってみました。','inherit','closed','closed','','671-revision-v1','','','2019-09-13 22:16:56','2019-09-13 13:16:56','',671,'http://localhost:8080/anothor/671-revision-v1',0,'revision','',0),(2532,1,'2019-09-13 22:20:09','2019-09-13 13:20:09','<h2>作る目的</h2>\n<p class=\"p1\">これから様々な物を作ってはアップしたいと思っていたので、まずは<span class=\"s1\">wordpress</span>を用いたブログサイトを勉強がてら作ってみようと考えました。</p>\n\n<h2>どんなサイトにしたいか</h2>\n見た目はノート風で以下の内容をまとめたブログサイトにしたい。\n固定ページは・・・\n\n・各カスタム投稿の最新の記事が何件か表示されるトップページ\n\n・筆者のプロフィールページ\n\n・全記事一覧が表示されるサイトマップページ\n\nブログの内容は・・・\n\n・作ったものとその作成手順の記事\n\n・作成した際に使用されたフレームワーク、サーバ、DB、OSの設定などのまとめ\n\n・フレームワークやサーバ、OSの基礎知識\n\n・開発するに当たって便利なツールの使い方まとめ\n\n・webマーケティングのまとめ\n\nなど\n<h2>設計</h2>\n<h4>開発環境</h4>\nOS：windows10\n\nサーバ：xampp\n<h4>本番環境 (2016)</h4>\nserversman@VPS\n\nOS：<span class=\"s1\">CentOS Linux release 7.0.1406 (Core)</span>\n\nhttpd:apache\n\nDB:mysql\n\n言語：php 5.4、JQuery\n\nフレームワーク：wordpress\n<h4>引越し後 (2018)</h4>\nさくらのVPSサーバ\n\nCentOS Linux release 7.2.1511 (Core)\n\nhttpd:nginx 1.12\n\nDB:mariadb\n\n言語：php 7.1、JQuery\n\nフレームワーク：wordpress\n<h4>UI設計</h4>\n<a href=\"http://localhost:8080/development_and_tool/prototype_of_blog/\" target=\"_blank\" rel=\"noopener noreferrer\">このサイト全体の構成をざっくりと図にしてみた<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a>\n<h2>作成フロー</h2>\n<h3 class=\"p1\"><span class=\"s1\">wordpress</span>の開発環境をインストールする<b> </b></h3>\n<p class=\"p2\">まずこのブログにあった<span class=\"s2\">wordpress</span>テーマから作成したいので、ローカル環境をインストールして実験できる環境を整えます。</p>\n<p class=\"p3\"><a href=\"http://localhost:8080/development_and_tool/wordpress_install_xampp\" target=\"_blank\" rel=\"noopener noreferrer\"><span class=\"s3\">XAMPPでwordpressのインストールしてみた<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></span></a></p>\n\n<h3 class=\"p1\">wordpressテーマを作成する<b> </b></h3>\n<p class=\"p2\">ローカル環境が整ったら、テーマを作成します。</p>\n<p class=\"p2\">手順としては<span class=\"s2\">html</span>でサイトの構成を作り、<span class=\"s2\">CSS</span>で装飾や配置を決め、<span class=\"s2\">html</span>ファイルを<span class=\"s2\">php</span>テキストに変換し、<span class=\"s2\">wordpress</span>テーマのフォルダを完成させます。</p>\n\n<h4>2016年</h4>\n<p class=\"p3\"><a href=\"http://localhost:8080/web_and_aplication/css_of_this-blog\" target=\"_blank\" rel=\"noopener noreferrer\"><span class=\"s3\"><span class=\"s4\">・このブログで使ったcss<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></span></span></a></p>\n<p class=\"p3\"><a href=\"http://localhost:8080/web_and_aplication/wp-thema/\" target=\"_blank\" rel=\"noopener noreferrer\"><span class=\"s3\">・wordpressテーマのファイル構成と中身<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></span></a></p>\n\n<h4>それ以降に追加した機能</h4>\n・<a href=\"http://localhost:8080/web_and_aplication/breadcrumb_customtype_and_taxonomy/\" target=\"_blank\" rel=\"noopener noreferrer\">パンくずリストの作り方<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a>\n\n・<a href=\"http://localhost:8080/web_and_aplication/tag-archive\" target=\"_blank\" rel=\"noopener noreferrer\">タグアーカイブ ページの作り方<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a>\n<h3 class=\"p1\">本番サーバの設定</h3>\n<p class=\"p2\">xamppで作った物を本番サーバでアップするにあたって、ドメインとサーバー会社に申し込みます。共有サーバーでもよかったのですが、それだと勉強にならないので<span class=\"s2\">vps</span>サーバーを借りることにしました。</p>\n\n<h4 class=\"p1\">xampp→serversman@VPS（2016）</h4>\n<p class=\"p3\"><span class=\"s4\">1 <span class=\"s5\">, <a href=\"http://localhost:8080/infrastructure/root_login\" target=\"_blank\" rel=\"noopener noreferrer\">ユーザの追加と<span class=\"s3\">root</span>での接続を禁止する<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a></span></span></p>\n<p class=\"p3\">2<span class=\"s7\">, <a href=\"http://localhost:8080/infrastructure/iptables_centos7\" target=\"_blank\" rel=\"noopener noreferrer\">Centos7で<span class=\"s9\">iptables<span class=\"s8\">の設定<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></span></span></a><span class=\"s8\">\n</span></span></p>\n<p class=\"p3\"><span class=\"s7\">3 , <a href=\"http://localhost:8080/infrastructure/generating_keys_on_teraterm\" target=\"_blank\" rel=\"noopener noreferrer\">tera termで<span class=\"s8\">秘密鍵と公開鍵の構築をしてみた<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></span></a></span><span class=\"s7\"><span class=\"s8\">\n</span></span></p>\n<p class=\"p3\">4, <a href=\"http://localhost:8080/infrastructure/set_apache\" target=\"_blank\" rel=\"noopener noreferrer\"><span class=\"s4\">web<span class=\"s5\">サーバー（</span><span class=\"s3\">apache</span><span class=\"s5\">）のインストールと初期設定</span></span><img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a></p>\n<p class=\"p3\"><span class=\"s4\">5, <a href=\"http://localhost:8080/infrastructure/mysql_install_and_setting\" target=\"_blank\" rel=\"noopener noreferrer\"><span class=\"s3\">MySQL</span><span class=\"s5\">のインストールと初期設定</span><img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a><span class=\"s5\">\n</span></span></p>\n<p class=\"p3\"><a href=\"http://localhost:8080/development_and_tool/deploy_wordpress\" target=\"_blank\" rel=\"noopener noreferrer\"><span class=\"s4\">6,</span>ローカルにあるxamppからserversman@VPSサーバへWPサイトを引っ越し<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a></p>\n\n<h4 class=\"p1\">serversman@VPS→さくらVPS（2018）</h4>\n1は一緒です。\n<span id=\"selinux\"></span>\n\n<span id=\"selinux\">2 ,<a href=\"http://localhost:8080/infrastructure/setting_centos7/\" target=\"_blank\" rel=\"noopener noreferrer\">Centos7の初期設定<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a></span>\n\n<span class=\"s7\">3, <a href=\"http://localhost:8080/infrastructure/firewalld_centos7/\" target=\"_blank\" rel=\"noopener noreferrer\">Centos7でFirewalld<span class=\"s8\">の設定<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></span></a></span>\n\n<span class=\"s7\"><span class=\"s8\">4, <a href=\"http://localhost:8080/infrastructure/generating_keys_on_openssh/\" target=\"_blank\" rel=\"noopener noreferrer\">Opensshで秘密鍵と公開鍵の構築をしてみた<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a></span></span>\n\n5, <a href=\"http://localhost:8080/backend_and_server/multiple_domein_on_nginx/\" target=\"_blank\" rel=\"noopener noreferrer\">1台のnginx上に複数のドメインでそれぞれのページを表示できるように設定する<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a>\n\n6, <a href=\"http://localhost:8080/infrastructure/ssl_at_lets-encrypt/\" target=\"_blank\" rel=\"noopener noreferrer\">Let’s Encryptを使って無料でSSL設定をする<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a>\n\n7,<a href=\"http://localhost:8080/backend_and_server/lamp_on_virtialhosts/\" target=\"_blank\" rel=\"noopener noreferrer\">,nginxのバーチャルホスト上にLamp環境を作る<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /> </a>\n\n8,<a href=\"http://localhost:8080/development_and_tool/wordpress_on_vertialhosts/\" target=\"_blank\" rel=\"noopener noreferrer\">バーチャルホスト上にwordpressを引っ越しする<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a>\n<h2 class=\"p1\"><b>まとめ</b><b> </b></h2>\n<p class=\"p2\">自作<span class=\"s2\">wordpress</span>テーマを使ったブログサイトを<span class=\"s2\">vps</span>サーバーでアップするに必要なもの・覚えておきたいもの一覧</p>\n<p class=\"p5\"><span class=\"s11\">・テーマの作成</span>→HTML<span class=\"s11\">、</span>CSS<span class=\"s11\">、</span>php<span class=\"s11\">、Jquery、</span>wordpress</p>\n<p class=\"p5\">・sshサーバーにログイン<span class=\"s2\">→ssh</span>、<span class=\"s2\">vi</span>エディタの使い方、<span class=\"s2\">Linux\n</span></p>\n<p class=\"p5\">・セキュリティ <span class=\"s2\">→ssh</span>、パーミッションの知識、SSL/TLS</p>\n<p class=\"p5\">・ファイアーウォールの起動<span class=\"s2\">→iptables,firewalld\n</span></p>\n<p class=\"p5\"><span class=\"s11\">・</span>web<span class=\"s11\">サーバーの設置</span>→Apache,nginx</p>\n<p class=\"p5\">・データベースの設置<span class=\"s2\">→MySQL,mariadb\n</span></p>\n<p class=\"p5\"><span class=\"s11\">・</span>wordpress<span class=\"s11\">の設置</span>→phpmyadmin<span class=\"s11\">、</span>wordpress</p>\n\n\n初めて思いつきで作ってみましたが、背景の木の画像と方眼紙が、文章を見るにはちょっと見づらいかも・・・と感じました。\n\n次また何かアプリを作る際は、もうちょっとUI、UXにも気を配ったものを作りたいと思います。','このブログ','自分が覚えたことや調べたこと、どのように作ったのかを確認するためのノート代わりになるブログをwordpressで作ってみました。','inherit','closed','closed','','671-revision-v1','','','2019-09-13 22:20:09','2019-09-13 13:20:09','',671,'http://localhost:8080/anothor/671-revision-v1',0,'revision','',0),(2533,1,'2019-09-13 22:23:32','2019-09-13 13:23:32','<h2>作る目的</h2>\n<p class=\"p1\">これから様々な物を作ってはアップしたいと思っていたので、まずは<span class=\"s1\">wordpress</span>を用いたブログサイトを勉強がてら作ってみようと考えました。</p>\n\n<h2>どんなサイトにしたいか</h2>\n見た目はノート風で以下の内容をまとめたブログサイトにしたい。\n固定ページは・・・\n\n・各カスタム投稿の最新の記事が何件か表示されるトップページ\n\n・筆者のプロフィールページ\n\n・全記事一覧が表示されるサイトマップページ\n\nブログの内容は・・・\n\n・作ったものとその作成手順の記事\n\n・作成した際に使用されたフレームワーク、サーバ、DB、OSの設定などのまとめ\n\n・フレームワークやサーバ、OSの基礎知識\n\n・開発するに当たって便利なツールの使い方まとめ\n\n・webマーケティングのまとめ\n\nなど\n<h2>設計</h2>\n<h4>開発環境</h4>\nOS：windows10\n\nサーバ：xampp\n<h4>本番環境 (2016)</h4>\nserversman@VPS\n\nOS：<span class=\"s1\">CentOS Linux release 7.0.1406 (Core)</span>\n\nhttpd:apache\n\nDB:mysql\n\n言語：php 5.4、JQuery\n\nフレームワーク：wordpress\n<h4>引越し後 (2018)</h4>\nさくらのVPSサーバ\n\nCentOS Linux release 7.2.1511 (Core)\n\nhttpd:nginx 1.12\n\nDB:mariadb\n\n言語：php 7.1、JQuery\n\nフレームワーク：wordpress\n<h4>UI設計</h4>\n<a href=\"http://localhost:8080/development_and_tool/prototype_of_blog/\" target=\"_blank\" rel=\"noopener noreferrer\">このサイト全体の構成をざっくりと図にしてみた<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a>\n<h2>作成フロー</h2>\n<h3 class=\"p1\"><span class=\"s1\">wordpress</span>の開発環境をインストールする<b> </b></h3>\n<p class=\"p2\">まずこのブログにあった<span class=\"s2\">wordpress</span>テーマから作成したいので、ローカル環境をインストールして実験できる環境を整えます。</p>\n<p class=\"p3\"><a href=\"http://localhost:8080/development_and_tool/wordpress_install_xampp\" target=\"_blank\" rel=\"noopener noreferrer\"><span class=\"s3\">XAMPPでwordpressのインストールしてみた<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></span></a></p>\n\n<h3 class=\"p1\">wordpressテーマを作成する<b> </b></h3>\n<p class=\"p2\">ローカル環境が整ったら、テーマを作成します。</p>\n<p class=\"p2\">手順としては<span class=\"s2\">html</span>でサイトの構成を作り、<span class=\"s2\">CSS</span>で装飾や配置を決め、<span class=\"s2\">html</span>ファイルを<span class=\"s2\">php</span>テキストに変換し、<span class=\"s2\">wordpress</span>テーマのフォルダを完成させます。</p>\n\n<h4>2016年</h4>\n<p class=\"p3\"><a href=\"http://localhost:8080/web_and_aplication/css_of_this-blog\" target=\"_blank\" rel=\"noopener noreferrer\"><span class=\"s3\"><span class=\"s4\">・このブログで使ったcss<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></span></span></a></p>\n<p class=\"p3\"><a href=\"http://localhost:8080/web_and_aplication/wp-thema/\" target=\"_blank\" rel=\"noopener noreferrer\"><span class=\"s3\">・wordpressテーマのファイル構成と中身<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></span></a></p>\n\n<h4>それ以降に追加した機能</h4>\n・<a href=\"http://localhost:8080/web_and_aplication/breadcrumb_customtype_and_taxonomy/\" target=\"_blank\" rel=\"noopener noreferrer\">パンくずリストの作り方<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a>\n\n・<a href=\"http://localhost:8080/web_and_aplication/tag-archive\" target=\"_blank\" rel=\"noopener noreferrer\">タグアーカイブ ページの作り方<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a>\n<h3 class=\"p1\">本番サーバの設定</h3>\n<p class=\"p2\">xamppで作った物を本番サーバでアップするにあたって、ドメインとサーバー会社に申し込みます。共有サーバーでもよかったのですが、それだと勉強にならないので<span class=\"s2\">vps</span>サーバーを借りることにしました。</p>\n\n<h4 class=\"p1\">xampp→serversman@VPS（2016）</h4>\n<p class=\"p3\"><span class=\"s4\">1 <span class=\"s5\">, <a href=\"http://localhost:8080/infrastructure/root_login\" target=\"_blank\" rel=\"noopener noreferrer\">ユーザの追加と<span class=\"s3\">root</span>での接続を禁止する<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a></span></span></p>\n<p class=\"p3\">2<span class=\"s7\">, <a href=\"http://localhost:8080/infrastructure/iptables_centos7\" target=\"_blank\" rel=\"noopener noreferrer\">Centos7で<span class=\"s9\">iptables<span class=\"s8\">の設定<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></span></span></a><span class=\"s8\">\n</span></span></p>\n<p class=\"p3\"><span class=\"s7\">3 , <a href=\"http://localhost:8080/infrastructure/generating_keys_on_teraterm\" target=\"_blank\" rel=\"noopener noreferrer\">tera termで<span class=\"s8\">秘密鍵と公開鍵の構築をしてみた<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></span></a></span><span class=\"s7\"><span class=\"s8\">\n</span></span></p>\n<p class=\"p3\">4, <a href=\"http://localhost:8080/infrastructure/set_apache\" target=\"_blank\" rel=\"noopener noreferrer\"><span class=\"s4\">web<span class=\"s5\">サーバー（</span><span class=\"s3\">apache</span><span class=\"s5\">）のインストールと初期設定</span></span><img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a></p>\n<p class=\"p3\"><span class=\"s4\">5, <a href=\"http://localhost:8080/infrastructure/mysql_install_and_setting\" target=\"_blank\" rel=\"noopener noreferrer\"><span class=\"s3\">MySQL</span><span class=\"s5\">のインストールと初期設定</span><img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a><span class=\"s5\">\n</span></span></p>\n<p class=\"p3\"><a href=\"http://localhost:8080/development_and_tool/deploy_wordpress\" target=\"_blank\" rel=\"noopener noreferrer\"><span class=\"s4\">6,</span>ローカルにあるxamppからserversman@VPSサーバへWPサイトを引っ越し<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a></p>\n\n<h4 class=\"p1\">serversman@VPS→さくらVPS（2018）</h4>\n1は一緒です。\n<span id=\"selinux\"></span>\n\n<span id=\"selinux\">2 ,<a href=\"http://localhost:8080/infrastructure/setting_centos7\" target=\"_blank\" rel=\"noopener noreferrer\">Centos7の初期設定<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a></span>\n\n<span class=\"s7\">3, <a href=\"http://localhost:8080/infrastructure/firewalld_centos7\" target=\"_blank\" rel=\"noopener noreferrer\">Centos7でFirewalld<span class=\"s8\">の設定<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></span></a></span>\n\n<span class=\"s7\"><span class=\"s8\">4, <a href=\"http://localhost:8080/infrastructure/generating_keys_on_openssh\" target=\"_blank\" rel=\"noopener noreferrer\">Opensshで秘密鍵と公開鍵の構築をしてみた<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a></span></span>\n\n5, <a href=\"http://localhost:8080/infrastructure/multiple_domein_on_nginx\" target=\"_blank\" rel=\"noopener noreferrer\">1台のnginx上に複数のドメインでそれぞれのページを表示できるように設定する<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a>\n\n6, <a href=\"http://localhost:8080/infrastructure/ssl_at_lets-encrypt\" target=\"_blank\" rel=\"noopener noreferrer\">Let’s Encryptを使って無料でSSL設定をする<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a>\n\n7,<a href=\"http://localhost:8080/infrastructure/lamp_on_virtialhosts\" target=\"_blank\" rel=\"noopener noreferrer\">,nginxのバーチャルホスト上にLamp環境を作る<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /> </a>\n\n8,<a href=\"http://localhost:8080/development_and_tool/wordpress_on_vertialhosts\" target=\"_blank\" rel=\"noopener noreferrer\">バーチャルホスト上にwordpressを引っ越しする<img class=\"alignnone size-full wp-image-1330\" src=\"http://localhost:8080/wp-content/uploads/2018/10/c6c4bc5672813b976d29583d24b9f572.png\" alt=\"\" width=\"16\" height=\"16\" /></a>\n<h2 class=\"p1\"><b>まとめ</b><b> </b></h2>\n<p class=\"p2\">自作<span class=\"s2\">wordpress</span>テーマを使ったブログサイトを<span class=\"s2\">vps</span>サーバーでアップするに必要なもの・覚えておきたいもの一覧</p>\n<p class=\"p5\"><span class=\"s11\">・テーマの作成</span>→HTML<span class=\"s11\">、</span>CSS<span class=\"s11\">、</span>php<span class=\"s11\">、Jquery、</span>wordpress</p>\n<p class=\"p5\">・sshサーバーにログイン<span class=\"s2\">→ssh</span>、<span class=\"s2\">vi</span>エディタの使い方、<span class=\"s2\">Linux\n</span></p>\n<p class=\"p5\">・セキュリティ <span class=\"s2\">→ssh</span>、パーミッションの知識、SSL/TLS</p>\n<p class=\"p5\">・ファイアーウォールの起動<span class=\"s2\">→iptables,firewalld\n</span></p>\n<p class=\"p5\"><span class=\"s11\">・</span>web<span class=\"s11\">サーバーの設置</span>→Apache,nginx</p>\n<p class=\"p5\">・データベースの設置<span class=\"s2\">→MySQL,mariadb\n</span></p>\n<p class=\"p5\"><span class=\"s11\">・</span>wordpress<span class=\"s11\">の設置</span>→phpmyadmin<span class=\"s11\">、</span>wordpress</p>\n\n\n初めて思いつきで作ってみましたが、背景の木の画像と方眼紙が、文章を見るにはちょっと見づらいかも・・・と感じました。\n\n次また何かアプリを作る際は、もうちょっとUI、UXにも気を配ったものを作りたいと思います。','このブログ','自分が覚えたことや調べたこと、どのように作ったのかを確認するためのノート代わりになるブログをwordpressで作ってみました。','inherit','closed','closed','','671-revision-v1','','','2019-09-13 22:23:32','2019-09-13 13:23:32','',671,'http://localhost:8080/anothor/671-revision-v1',0,'revision','',0),(2540,1,'2019-10-02 10:09:08','2019-10-02 01:09:08','<p id=\"AWS_Certified_Solutions_Architect_-_Professional\" class=\"lb-txt-bold lb-txt-white lb-txt-44 lb-none-v-margin lb-h1-large lb-title\">AWS 認定ソリューションアーキテクト – プロフェッショナルに出てくるcloudfrontの自分用のまとめです。</p>\n\n<!-- wp:heading -->\n<h2>出題される内容について</h2>\n<!-- /wp:heading -->\n\n<p>プロフェッショナルに出てくるcloudfrontはざっくり言うと以下の内容が多いんじゃないかなと思います。</p>\n<p>・ビューアとcloudfront間、cloudfrontとオリジン間のHTTPS通信→</p>\n<p>・DDos攻撃を防ぐ手段の一つとして</p>\n<p>・コンテンツを提供するユーザを限定したい時→署名付きURL・cookie、OAI</p>\n<p>・キャッシュの有効期限</p>\n<p>・ディストリビューション</p>\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','AWS認定ソリューションアーキテクトプロフェッショナル-CloudFrontのまとめ','AWS 認定ソリューションアーキテクト – プロフェッショナルに出てくるcloudfrontの自分用のまとめです。','inherit','closed','closed','','2351-revision-v1','','','2019-10-02 10:09:08','2019-10-02 01:09:08','',2351,'http://localhost:8080/anothor/2351-revision-v1',0,'revision','',0),(2542,1,'2019-10-02 10:18:36','2019-10-02 01:18:36','<p id=\"AWS_Certified_Solutions_Architect_-_Professional\" class=\"lb-txt-bold lb-txt-white lb-txt-44 lb-none-v-margin lb-h1-large lb-title\">AWS 認定ソリューションアーキテクト – プロフェッショナルに出てくるcloudfrontの自分用のまとめです。</p>\n\n<!-- wp:heading -->\n<h2>出題される内容について</h2>\n<!-- /wp:heading -->\n\n<p>プロフェッショナルに出てくるcloudfrontはざっくり言うと以下の内容が多いんじゃないかなと思います。</p>\n<p>・ディストリビューション（Lambda @ Edge、udemy2-56）</p>\n<p>・ビューアとcloudfront間、cloudfrontとオリジン間のHTTPS通信（エンドツーエンドのssl）→ビューアプロトコルポリシー、</p>\n<p>・コンテンツを提供するユーザを限定したい時→署名付きURL・cookie、OAI</p>\n<p>・キャッシュ（ttlを０、Cache-Control max-age）</p>\n<p>・DDos攻撃を防ぐ手段の一つとして</p>\n\n<!-- wp:heading -->\n<h2>ディストリビューション</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2>エンドツーエンドのHTTPS通信</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','AWS認定ソリューションアーキテクトプロフェッショナル-CloudFrontのまとめ','AWS 認定ソリューションアーキテクト – プロフェッショナルに出てくるcloudfrontの自分用のまとめです。','inherit','closed','closed','','2351-revision-v1','','','2019-10-02 10:18:36','2019-10-02 01:18:36','',2351,'http://localhost:8080/anothor/2351-revision-v1',0,'revision','',0),(2543,1,'2019-10-02 10:21:16','2019-10-02 01:21:16','<p>プロフェッショナルに出てくるcloudfrontはざっくり言うと以下の内容が多いんじゃないかなと思います。</p>\n<p>・ディストリビューション（Lambda @ Edge、udemy2-56）</p>\n<p>・ビューアとcloudfront間、cloudfrontとオリジン間のHTTPS通信（エンドツーエンドのssl）→ビューアプロトコルポリシー、</p>\n<p>・コンテンツを提供するユーザを限定したい時→署名付きURL・cookie、OAI</p>\n<p>・キャッシュ（ttlを０、Cache-Control max-age）</p>\n<p>・DDos攻撃を防ぐ手段の一つとして</p>\n<p> </p>\n\n<!-- wp:heading -->\n<h2>ディストリビューション</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2>エンドツーエンドのHTTPS通信</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2>コンテンツを提供するユーザを限定する</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2>キャッシュについて</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','AWS認定ソリューションアーキテクトプロフェッショナル-CloudFrontのまとめ','AWS 認定ソリューションアーキテクト – プロフェッショナルに出てくるcloudfrontの自分用のまとめです。','inherit','closed','closed','','2351-revision-v1','','','2019-10-02 10:21:16','2019-10-02 01:21:16','',2351,'http://localhost:8080/anothor/2351-revision-v1',0,'revision','',0),(2544,1,'2019-10-02 10:23:28','2019-10-02 01:23:28','<p>プロフェッショナルに出てくるcloudfrontはざっくり言うと以下の内容が多いんじゃないかなと思います。</p>\n<p> </p>\n<p>・ディストリビューション</p>\n<p>・ビューアとcloudfront間、cloudfrontとオリジン間のHTTPS通信（エンドツーエンドのssl）</p>\n<p>・コンテンツを提供するユーザを限定したい時</p>\n<p>・キャッシュ</p>\n<p>・DDos攻撃を防ぐ手段の一つとして</p>\n<p> </p>\n\n<!-- wp:heading -->\n<h2>ディストリビューション</h2>\n<!-- /wp:heading -->\n\n<p>Lambda @ Edge</p>\n<p>udemy2-56</p>\n\n<!-- wp:heading -->\n<h2>エンドツーエンドのHTTPS通信</h2>\n<!-- /wp:heading -->\n\n<p>ビューアプロトコルポリシー</p>\n<p>ACM</p>\n\n<!-- wp:heading -->\n<h2>コンテンツを提供するユーザを限定する</h2>\n<!-- /wp:heading -->\n\n<p>署名付きURL</p>\n<p>署名付きcookie</p>\n<p>OAI</p>\n\n<!-- wp:heading -->\n<h2>キャッシュについて</h2>\n<!-- /wp:heading -->\n\n<p>ttlを０にする</p>\n<p>Cache-Control max-age</p>','AWS認定ソリューションアーキテクトプロフェッショナル-CloudFrontのまとめ','AWS 認定ソリューションアーキテクト – プロフェッショナルに出てくるcloudfrontの自分用のまとめです。','inherit','closed','closed','','2351-revision-v1','','','2019-10-02 10:23:28','2019-10-02 01:23:28','',2351,'http://localhost:8080/anothor/2351-revision-v1',0,'revision','',0),(2546,1,'2019-10-02 11:03:24','2019-10-02 02:03:24','<p>プロフェッショナルに出てくるcloudfrontはざっくり言うと以下の内容が多いんじゃないかなと思います。</p>\n<p>↓</p>\n<p>・ディストリビューション</p>\n<p>・ビューアとcloudfront間、cloudfrontとオリジン間のHTTPS通信</p>\n<p>（エンドツーエンドのssl）</p>\n<p>・コンテンツを提供するユーザを限定したい時</p>\n<p>・キャッシュ</p>\n<p>・DDos攻撃を防ぐ手段の一つとして</p>\n\n<!-- wp:heading -->\n<h2>ディストリビューション</h2>\n<!-- /wp:heading -->\n\n<p>Lambda @ Edge</p>\n<p>udemy2-56</p>\n\n<!-- wp:heading -->\n<h2>エンドツーエンドのHTTPS通信</h2>\n<!-- /wp:heading -->\n\n<p> </p>\n<p>ビューアプロトコルポリシー</p>\n<p>ACM</p>\n\n<!-- wp:heading -->\n<h2>コンテンツを提供するユーザを限定する</h2>\n<!-- /wp:heading -->\n\n<p> </p>\n<p>署名付きURL</p>\n<p>署名付きcookie</p>\n<p>OAI</p>\n<p> </p>\n\n<!-- wp:heading -->\n<h2>キャッシュについて</h2>\n<!-- /wp:heading -->\n\n<p>ttlを０にする</p>\n<p>Cache-Control max-age</p>','AWS認定ソリューションアーキテクトプロフェッショナル-CloudFrontのまとめ','AWS 認定ソリューションアーキテクト – プロフェッショナルに出てくるcloudfrontの自分用のまとめです。','inherit','closed','closed','','2351-revision-v1','','','2019-10-02 11:03:24','2019-10-02 02:03:24','',2351,'http://localhost:8080/anothor/2351-revision-v1',0,'revision','',0),(2547,1,'2019-10-02 11:20:09','2019-10-02 02:20:09','<p>プロフェッショナルに出てくるcloudfrontはざっくり言うと以下の内容が多いんじゃないかなと思います。</p>\n<p>↓</p>\n<p>・ディストリビューション</p>\n<p>・ビューアとcloudfront間、cloudfrontとオリジン間のHTTPS通信</p>\n<p>（エンドツーエンドのssl）</p>\n<p>・コンテンツを提供するユーザを限定したい時</p>\n<p>・キャッシュ</p>\n<p>・DDos攻撃を防ぐ手段の一つとして</p>\n\n<!-- wp:heading -->\n<h2>ディストリビューション</h2>\n<!-- /wp:heading -->\n\n<p>Lambda @ Edge</p>\n<p>udemy2-56</p>\n\n<!-- wp:heading -->\n<h2>エンドツーエンドのHTTPS通信</h2>\n<!-- /wp:heading -->\n\n<p>エンドツーエンドと言うのは、端から端まで、つまりビューワーからオリジンまでを意味します。</p>\n<p>図</p>\n<p>SSL通信をするには、２つの証明書を適用する必要があります。</p>\n<p>⑴ ビューワーからcloudfront間</p>\n<p>⑵ cloudfrontからオリジンの間</p>\n<p> </p>\n<p>ビューアプロトコルポリシー</p>\n<p>ACM</p>\n\n<!-- wp:heading -->\n<h2>コンテンツを提供するユーザを限定する</h2>\n<!-- /wp:heading -->\n\n<p> </p>\n<p>署名付きURL</p>\n<p>署名付きcookie</p>\n<p>OAI</p>\n<p> </p>\n\n<!-- wp:heading -->\n<h2>キャッシュについて</h2>\n<!-- /wp:heading -->\n\n<p>ttlを０にする</p>\n<p>Cache-Control max-age</p>','AWS認定ソリューションアーキテクトプロフェッショナル-CloudFrontのまとめ','AWS 認定ソリューションアーキテクト – プロフェッショナルに出てくるcloudfrontの自分用のまとめです。','inherit','closed','closed','','2351-revision-v1','','','2019-10-02 11:20:09','2019-10-02 02:20:09','',2351,'http://localhost:8080/anothor/2351-revision-v1',0,'revision','',0),(2548,1,'2019-10-02 11:22:39','2019-10-02 02:22:39','<p>プロフェッショナルに出てくるcloudfrontはざっくり言うと以下の内容が多いんじゃないかなと思います。</p>\n<p>↓</p>\n<p>・ディストリビューション</p>\n<p>・ビューアとcloudfront間、cloudfrontとオリジン間のHTTPS通信</p>\n<p>（エンドツーエンドのssl）</p>\n<p>・コンテンツを提供するユーザを限定したい時</p>\n<p>・キャッシュ</p>\n<p>・DDos攻撃を防ぐ手段の一つとして</p>\n\n<!-- wp:heading -->\n<h2>ディストリビューション</h2>\n<!-- /wp:heading -->\n\n<p>Lambda @ Edge</p>\n<p>udemy2-56</p>\n\n<!-- wp:heading -->\n<h2>エンドツーエンドのHTTPS通信</h2>\n<!-- /wp:heading -->\n\n<p>エンドツーエンドと言うのは、端から端まで、つまりビューワーからオリジンまでを意味します。</p>\n<p>図</p>\n<p> </p>\n<p>SSL通信をするには、２つの証明書を適用する必要があります。</p>\n<p>⑴ ビューワーからcloudfront間</p>\n<p>⑵ cloudfrontからオリジンの間</p>\n<p> </p>\n<p>ビューアプロトコルポリシー</p>\n<p>ACM</p>\n\n<!-- wp:heading -->\n<h2>コンテンツを提供するユーザを限定する</h2>\n<!-- /wp:heading -->\n\n<p> </p>\n<p>署名付きURL</p>\n<p>署名付きcookie</p>\n<p>OAI</p>\n<p> </p>\n\n<!-- wp:heading -->\n<h2>キャッシュについて</h2>\n<!-- /wp:heading -->\n\n<p>ttlを０にする</p>\n<p>Cache-Control max-age</p>','AWS認定ソリューションアーキテクトプロフェッショナル-CloudFrontのまとめ','AWS 認定ソリューションアーキテクト – プロフェッショナルに出てくるcloudfrontの自分用のまとめです。','inherit','closed','closed','','2351-revision-v1','','','2019-10-02 11:22:39','2019-10-02 02:22:39','',2351,'http://localhost:8080/anothor/2351-revision-v1',0,'revision','',0),(2550,1,'2019-10-02 11:26:04','2019-10-02 02:26:04','<p>プロフェッショナルに出てくるcloudfrontはざっくり言うと以下の内容が多いんじゃないかなと思います。</p>\n<p>↓</p>\n<p>・ディストリビューション</p>\n<p>・ビューアとcloudfront間、cloudfrontとオリジン間のHTTPS通信</p>\n<p>（エンドツーエンドのssl）</p>\n<p>・コンテンツを提供するユーザを限定したい時</p>\n<p>・キャッシュ</p>\n<p>・DDos攻撃を防ぐ手段の一つとして</p>\n\n<!-- wp:heading -->\n<h2>ディストリビューション</h2>\n<!-- /wp:heading -->\n\n<p>Lambda @ Edge</p>\n<p>udemy2-56</p>\n\n<!-- wp:heading -->\n<h2>エンドツーエンドのHTTPS通信</h2>\n<!-- /wp:heading -->\n\n<p>エンドツーエンドと言うのは、端から端まで、つまりビューワーからオリジンまでを意味します。</p>\n<p>図</p>\n<p> </p>\n<p>SSL通信をするには、２つの証明書を適用する必要があります。</p>\n<p>⑴ ビューワーからcloudfront間</p>\n<p>⑵ cloudfrontからオリジンの間</p>\n<p> </p>\n<p>ビューアプロトコルポリシー</p>\n<p>ACM</p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>練習問題</h3>\n<!-- /wp:heading -->\n\n<p>例題１）世界中で電気自動車を販売する自動化会社は、「自動操縦」機能とも呼ばれる半自動運転技術を備えた最新の自動車モデルをリリースします。新製品の人気のため、静的アセットのキャッシュにCloudFrontを使用して、世界中の視聴者への新しいモデルの画像やその他の静的コンテンツの配信を高速化することを計画しています。静的コンテンツは、独自のドメイン名を使用してHTTPS経由で配信する必要があります。これにより、Webサイトの訪問者はSSL接続で必要なセキュリティに加えて、遅延が少なく信頼性が高くなります。CloudFrontを使用してこのセットアップをAWSに実装するにはどうすればよいですか？（2つ選択）</p>\n<p> </p>\n<p>⑴ AWS Certificate Manager（ACM）に保存されているデフォルトのCloudFront証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑵ AWS Certificate Manager（ACM）に保存されているカスタムSSL証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑶ 署名付きCookieを使用してCloudFrontディストリビューションを作成します。 IAMに保存されているデフォルトのCloudFront証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑷ 署名付きURLを使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑸ IAMに保存されているカスタムSSL証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p> </p>\n<p> </p>\n\n<!-- wp:heading -->\n<h2>コンテンツを提供するユーザを限定する</h2>\n<!-- /wp:heading -->\n\n<p> </p>\n<p>署名付きURL</p>\n<p>署名付きcookie</p>\n<p>OAI</p>\n<p> </p>\n\n<!-- wp:heading -->\n<h2>キャッシュについて</h2>\n<!-- /wp:heading -->\n\n<p>ttlを０にする</p>\n<p>Cache-Control max-age</p>','AWS認定ソリューションアーキテクトプロフェッショナル-CloudFrontのまとめ','AWS 認定ソリューションアーキテクト – プロフェッショナルに出てくるcloudfrontの自分用のまとめです。','inherit','closed','closed','','2351-revision-v1','','','2019-10-02 11:26:04','2019-10-02 02:26:04','',2351,'http://localhost:8080/anothor/2351-revision-v1',0,'revision','',0),(2552,1,'2019-10-02 11:29:32','2019-10-02 02:29:32','<p>プロフェッショナルに出てくるcloudfrontはざっくり言うと以下の内容が多いんじゃないかなと思います。</p>\n<p>↓</p>\n<p>・ディストリビューション</p>\n<p>・ビューアとcloudfront間、cloudfrontとオリジン間のHTTPS通信</p>\n<p>（エンドツーエンドのssl）</p>\n<p>・コンテンツを提供するユーザを限定したい時</p>\n<p>・キャッシュ</p>\n<p>・DDos攻撃を防ぐ手段の一つとして</p>\n\n<!-- wp:heading -->\n<h2>ディストリビューション</h2>\n<!-- /wp:heading -->\n\n<p>Lambda @ Edge</p>\n<p>udemy2-56</p>\n\n<!-- wp:heading -->\n<h2>エンドツーエンドのHTTPS通信</h2>\n<!-- /wp:heading -->\n\n<p>エンドツーエンドと言うのは、端から端まで、つまりビューワーからオリジンまでを意味します。</p>\n<p>図</p>\n<p> </p>\n<p>SSL通信をするには、２つの証明書を適用する必要があります。</p>\n<p>⑴ ビューワーからcloudfront間</p>\n<p>⑵ cloudfrontからオリジンの間</p>\n<p> </p>\n<p>ビューアプロトコルポリシー</p>\n<p>ACM</p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>練習問題</h3>\n<!-- /wp:heading -->\n\n<p>例題は３問。答えは最後にあります。</p>\n<p> </p>\n<p>例題１）</p>\n<p>世界中で電気自動車を販売する自動化会社は、「自動操縦」機能とも呼ばれる半自動運転技術を備えた最新の自動車モデルをリリースします。新製品の人気のため、静的アセットのキャッシュにCloudFrontを使用して、世界中の視聴者への新しいモデルの画像やその他の静的コンテンツの配信を高速化することを計画しています。静的コンテンツは、独自のドメイン名を使用してHTTPS経由で配信する必要があります。これにより、Webサイトの訪問者はSSL接続で必要なセキュリティに加えて、遅延が少なく信頼性が高くなります。CloudFrontを使用してこのセットアップをAWSに実装するにはどうすればよいですか？（2つ選択）</p>\n<p> </p>\n<p>⑴ AWS Certificate Manager（ACM）に保存されているデフォルトのCloudFront証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑵ AWS Certificate Manager（ACM）に保存されているカスタムSSL証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑶ 署名付きCookieを使用してCloudFrontディストリビューションを作成します。 IAMに保存されているデフォルトのCloudFront証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑷ 署名付きURLを使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑸ IAMに保存されているカスタムSSL証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>答え：２、５</p>\n<p>解説：</p>\n<p> </p>\n<p>例題２）</p>\n<p> </p>\n\n<!-- wp:heading -->\n<h2>コンテンツを提供するユーザを限定する</h2>\n<!-- /wp:heading -->\n\n<p> </p>\n<p>署名付きURL</p>\n<p>署名付きcookie</p>\n<p>OAI</p>\n<p> </p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>練習問題</h3>\n<!-- /wp:heading -->\n\n<p>例題１）</p>\n\n<!-- wp:heading -->\n<h2>キャッシュについて</h2>\n<!-- /wp:heading -->\n\n<p>ttlを０にする</p>\n<p>Cache-Control max-age</p>','AWS認定ソリューションアーキテクトプロフェッショナル-CloudFrontのまとめ','AWS 認定ソリューションアーキテクト – プロフェッショナルに出てくるcloudfrontの自分用のまとめです。','inherit','closed','closed','','2351-revision-v1','','','2019-10-02 11:29:32','2019-10-02 02:29:32','',2351,'http://localhost:8080/anothor/2351-revision-v1',0,'revision','',0),(2553,1,'2019-10-02 11:31:40','2019-10-02 02:31:40','<p>プロフェッショナルに出てくるcloudfrontはざっくり言うと以下の内容が多いんじゃないかなと思います。</p>\n<p>↓</p>\n<p>・ディストリビューション</p>\n<p>・ビューアとcloudfront間、cloudfrontとオリジン間のHTTPS通信</p>\n<p>（エンドツーエンドのssl）</p>\n<p>・コンテンツを提供するユーザを限定したい時</p>\n<p>・キャッシュ</p>\n<p>・DDos攻撃を防ぐ手段の一つとして</p>\n\n<!-- wp:heading -->\n<h2>ディストリビューション</h2>\n<!-- /wp:heading -->\n\n<p>Lambda @ Edge</p>\n<p>udemy2-56</p>\n\n<!-- wp:heading -->\n<h2>エンドツーエンドのHTTPS通信</h2>\n<!-- /wp:heading -->\n\n<p>エンドツーエンドと言うのは、端から端まで、つまりビューワーからオリジンまでを意味します。</p>\n<p>図</p>\n<p> </p>\n<p>SSL通信をするには、２つの証明書を適用する必要があります。</p>\n<p>⑴ ビューワーからcloudfront間</p>\n<p>⑵ cloudfrontからオリジンの間</p>\n<p> </p>\n<h4>⑴ ビューワーからcloudfront間</h4>\n<p> </p>\n<p>ビューアプロトコルポリシー</p>\n<p>ACM</p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>練習問題</h3>\n<!-- /wp:heading -->\n\n<p>例題は３問。答えは最後にあります。</p>\n<p> </p>\n<p>例題１）</p>\n<p>世界中で電気自動車を販売する自動化会社は、「自動操縦」機能とも呼ばれる半自動運転技術を備えた最新の自動車モデルをリリースします。新製品の人気のため、静的アセットのキャッシュにCloudFrontを使用して、世界中の視聴者への新しいモデルの画像やその他の静的コンテンツの配信を高速化することを計画しています。静的コンテンツは、独自のドメイン名を使用してHTTPS経由で配信する必要があります。これにより、Webサイトの訪問者はSSL接続で必要なセキュリティに加えて、遅延が少なく信頼性が高くなります。CloudFrontを使用してこのセットアップをAWSに実装するにはどうすればよいですか？（2つ選択）</p>\n<p> </p>\n<p>⑴ AWS Certificate Manager（ACM）に保存されているデフォルトのCloudFront証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑵ AWS Certificate Manager（ACM）に保存されているカスタムSSL証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑶ 署名付きCookieを使用してCloudFrontディストリビューションを作成します。 IAMに保存されているデフォルトのCloudFront証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑷ 署名付きURLを使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑸ IAMに保存されているカスタムSSL証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>答え：２、５</p>\n<p>解説：</p>\n<p> </p>\n<p>例題２）</p>\n<p> </p>\n\n<!-- wp:heading -->\n<h2>コンテンツを提供するユーザを限定する</h2>\n<!-- /wp:heading -->\n\n<p> </p>\n<p>署名付きURL</p>\n<p>署名付きcookie</p>\n<p>OAI</p>\n<p> </p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>練習問題</h3>\n<!-- /wp:heading -->\n\n<p>例題１）</p>\n\n<!-- wp:heading -->\n<h2>キャッシュについて</h2>\n<!-- /wp:heading -->\n\n<p>ttlを０にする</p>\n<p>Cache-Control max-age</p>','AWS認定ソリューションアーキテクトプロフェッショナル-CloudFrontのまとめ','AWS 認定ソリューションアーキテクト – プロフェッショナルに出てくるcloudfrontの自分用のまとめです。','inherit','closed','closed','','2351-revision-v1','','','2019-10-02 11:31:40','2019-10-02 02:31:40','',2351,'http://localhost:8080/anothor/2351-revision-v1',0,'revision','',0),(2554,1,'2019-10-02 11:42:40','2019-10-02 02:42:40','<p>プロフェッショナルに出てくるcloudfrontはざっくり言うと以下の内容が多いんじゃないかなと思います。</p>\n<p>↓</p>\n<p>・ディストリビューション</p>\n<p>・ビューアとcloudfront間、cloudfrontとオリジン間のHTTPS通信</p>\n<p>（エンドツーエンドのssl）</p>\n<p>・コンテンツを提供するユーザを限定したい時</p>\n<p>・キャッシュ</p>\n<p>・DDos攻撃を防ぐ手段の一つとして</p>\n\n<!-- wp:heading -->\n<h2>ディストリビューション</h2>\n<!-- /wp:heading -->\n\n<p>Lambda @ Edge</p>\n<p>udemy2-56</p>\n\n<!-- wp:heading -->\n<h2>エンドツーエンドのHTTPS通信</h2>\n<!-- /wp:heading -->\n\n<p>エンドツーエンドと言うのは、端から端まで、つまりビューワーからオリジンまでを意味します。</p>\n<p>図</p>\n<p> </p>\n<p>SSL通信をするには、２つの証明書を適用する必要があります。</p>\n<p>⑴ ビューワーからcloudfront間</p>\n<p>⑵ cloudfrontからオリジンの間</p>\n<p> </p>\n<h4>⑴ ビューワーからcloudfront間</h4>\n<p> </p>\n<p>ビューアプロトコルポリシー</p>\n<p>ACM</p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>練習問題</h3>\n<!-- /wp:heading -->\n\n<p>例題は３問。答えは最後にあります。</p>\n<p> </p>\n<p>例題１）</p>\n<p>世界中で電気自動車を販売する自動化会社は、「自動操縦」機能とも呼ばれる半自動運転技術を備えた最新の自動車モデルをリリースします。新製品の人気のため、静的アセットのキャッシュにCloudFrontを使用して、世界中の視聴者への新しいモデルの画像やその他の静的コンテンツの配信を高速化することを計画しています。静的コンテンツは、独自のドメイン名を使用してHTTPS経由で配信する必要があります。これにより、Webサイトの訪問者はSSL接続で必要なセキュリティに加えて、遅延が少なく信頼性が高くなります。CloudFrontを使用してこのセットアップをAWSに実装するにはどうすればよいですか？（2つ選択）</p>\n<p> </p>\n<p>⑴ AWS Certificate Manager（ACM）に保存されているデフォルトのCloudFront証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑵ AWS Certificate Manager（ACM）に保存されているカスタムSSL証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑶ 署名付きCookieを使用してCloudFrontディストリビューションを作成します。 IAMに保存されているデフォルトのCloudFront証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑷ 署名付きURLを使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑸ IAMに保存されているカスタムSSL証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>答え：２、５</p>\n<p>解説：</p>\n<p> </p>\n<p>例題２）</p>\n<p> </p>\n\n<!-- wp:heading -->\n<h2>コンテンツを提供するユーザを限定する</h2>\n<!-- /wp:heading -->\n\n<p>問題でよくあるのが、特定の会員だけプライベートコンテンツを見せるにはどうしたらいいか？というもの。</p>\n<p>署名付きURL</p>\n<p>署名付きcookie</p>\n<p>OAI</p>\n<p>信頼できる署名者</p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>練習問題</h3>\n<!-- /wp:heading -->\n\n<p>例題１）</p>\n\n<!-- wp:heading -->\n<h2>キャッシュについて</h2>\n<!-- /wp:heading -->\n\n<p>ttlを０にする</p>\n<p>Cache-Control max-age</p>','AWS認定ソリューションアーキテクトプロフェッショナル-CloudFrontのまとめ','AWS 認定ソリューションアーキテクト – プロフェッショナルに出てくるcloudfrontの自分用のまとめです。','inherit','closed','closed','','2351-revision-v1','','','2019-10-02 11:42:40','2019-10-02 02:42:40','',2351,'http://localhost:8080/anothor/2351-revision-v1',0,'revision','',0),(2556,1,'2019-10-02 12:16:45','2019-10-02 03:16:45','<p>プロフェッショナルに出てくるcloudfrontはざっくり言うと以下の内容が多いんじゃないかなと思います。</p>\n<p>↓</p>\n<p>・ディストリビューション</p>\n<p>・ビューアとcloudfront間、cloudfrontとオリジン間のHTTPS通信</p>\n<p>（エンドツーエンドのssl）</p>\n<p>・コンテンツを提供するユーザを限定したい時</p>\n<p>・キャッシュ</p>\n<p>・DDos攻撃を防ぐ手段の一つとして</p>\n\n<!-- wp:heading -->\n<h2>ディストリビューション</h2>\n<!-- /wp:heading -->\n\n<p>Lambda @ Edge</p>\n<p>udemy2-56</p>\n\n<!-- wp:heading -->\n<h2>HTTPS通信</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>ビューアプロトコルポリシー</h3>\n<!-- /wp:heading -->\n\n\n\n<!-- wp:heading {\"level\":3} -->\n<h3>エンドツーエンドのHTTPS通信</h3>\n<!-- /wp:heading -->\n\n<p>エンドツーエンドと言うのは、端から端まで、つまりビューワーからオリジンまでを意味します。</p>\n<p>図</p>\n<p> </p>\n<p>SSL通信をするには、２つの証明書を適用する必要があります。</p>\n<p>⑴ ビューワーからcloudfront間</p>\n<p>⑵ cloudfrontからオリジンの間</p>\n<p> </p>\n<h4>⑴ ビューワーからcloudfront間</h4>\n<p>ビューワーからcloudfrontの間には３種類の証明書を入れることが出来ます。</p>\n<p>証明書はcloudfrontに入れることで有効になります。</p>\n<p>１、ACM（AWS Certificate Manager）が提供する証明書</p>\n<p>２、信頼できるCAからの証明書（symantec）</p>\n<p>３、オレオレ証明書（自己署名証明書）</p>\n<p> </p>\n<h4>⑵ cloudfrontからオリジンの間</h4>\n<p>cloudfrontからオリジンの間で使える証明書はオリジンが何であるかによって異なります。</p>\n<p> </p>\n<p>しか使えませんが、ただし、オリジンが</p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>練習問題</h3>\n<!-- /wp:heading -->\n\n<p>例題は３問。答えは最後にあります。</p>\n<p> </p>\n<p>例題１）</p>\n<p>ユーザーのブラウザから CloudFront 経由でエンドツーエンドの HTTPS 接続を有効にするには、以下のオプションのどれが有効ですか。（3 つの回答を選択)</p>\n<p> </p>\n<p>１、ビューワーはサードパーティCA 証明書を使用する。CloudFront は自己署名証明書を使用する</p>\n<p>２、ビューワーと CloudFront との間の HTTPS 通信でサードパーティの CA 証明書を使用する</p>\n<p>３、ビューワーと CloudFront との間の HTTPS 通信で自己署名証明書を使用します</p>\n<p>４、CloudFront とオリジンとの間の HTTPS 通信で自己署名証明書を使用します</p>\n<p>５、CloudFront とオリジンとの間の HTTPS 通信で自己署名証明書を使用します。(オリジンが ELB ロードバランサー (Amazon EC2 など) でない場合)</p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>答え：１、２、３</p>\n<p>解説：</p>\n<p> </p>\n<p> </p>\n<p>例題２）</p>\n<p>世界中で電気自動車を販売する自動化会社は、「自動操縦」機能とも呼ばれる半自動運転技術を備えた最新の自動車モデルをリリースします。新製品の人気のため、静的アセットのキャッシュにCloudFrontを使用して、世界中の視聴者への新しいモデルの画像やその他の静的コンテンツの配信を高速化することを計画しています。静的コンテンツは、独自のドメイン名を使用してHTTPS経由で配信する必要があります。これにより、Webサイトの訪問者はSSL接続で必要なセキュリティに加えて、遅延が少なく信頼性が高くなります。CloudFrontを使用してこのセットアップをAWSに実装するにはどうすればよいですか？（2つ選択）</p>\n<p> </p>\n<p>⑴ AWS Certificate Manager（ACM）に保存されているデフォルトのCloudFront証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑵ AWS Certificate Manager（ACM）に保存されているカスタムSSL証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑶ 署名付きCookieを使用してCloudFrontディストリビューションを作成します。 IAMに保存されているデフォルトのCloudFront証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑷ 署名付きURLを使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑸ IAMに保存されているカスタムSSL証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>答え：２、５</p>\n<p>解説：</p>\n<p> </p>\n<p>例題３）</p>\n<p> </p>\n\n<!-- wp:heading -->\n<h2>コンテンツを提供するユーザを限定する</h2>\n<!-- /wp:heading -->\n\n<p>問題でよくあるのが、特定の会員だけプライベートコンテンツを見せるにはどうしたらいいか？というもの。</p>\n<p>署名付きURL</p>\n<p>署名付きcookie</p>\n<p>OAI</p>\n<p>信頼できる署名者</p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>練習問題</h3>\n<!-- /wp:heading -->\n\n<p>例題１）</p>\n\n<!-- wp:heading -->\n<h2>キャッシュについて</h2>\n<!-- /wp:heading -->\n\n<p>ttlを０にする</p>\n<p>Cache-Control max-age</p>','AWS認定ソリューションアーキテクトプロフェッショナル-CloudFrontのまとめ','AWS 認定ソリューションアーキテクト – プロフェッショナルに出てくるcloudfrontの自分用のまとめです。','inherit','closed','closed','','2351-revision-v1','','','2019-10-02 12:16:45','2019-10-02 03:16:45','',2351,'http://localhost:8080/anothor/2351-revision-v1',0,'revision','',0),(2558,1,'2019-10-02 12:28:29','2019-10-02 03:28:29','<p>プロフェッショナルに出てくるcloudfrontはざっくり言うと以下の内容が多いんじゃないかなと思います。</p>\n<p>↓</p>\n<p>・ディストリビューション</p>\n<p>・HTTPS通信</p>\n<p>・コンテンツを提供するユーザを限定したい時</p>\n<p>・キャッシュ</p>\n<p>・DDos攻撃を防ぐ手段の一つとして</p>\n\n<!-- wp:heading -->\n<h2>ディストリビューション</h2>\n<!-- /wp:heading -->\n\n<p>Lambda @ Edge</p>\n<p>udemy2-56</p>\n\n<!-- wp:heading -->\n<h2>HTTPS通信</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>エンドツーエンドのHTTPS通信</h3>\n<!-- /wp:heading -->\n\n<p>エンドツーエンドと言うのは、端から端まで、つまりビューワーからオリジンまでを意味します。</p>\n<p>図</p>\n<p> </p>\n<p>SSL通信をするには、２つの証明書を適用する必要があります。</p>\n<p>⑴ ビューワーからcloudfront間</p>\n<p>⑵ cloudfrontからオリジンの間</p>\n<p> </p>\n<h4>⑴ ビューワーからcloudfront間</h4>\n<p>証明書をcloudfrontに入れることで、ビューワーからcloudfront間のHTTPS通信が有効になります。</p>\n<p>ビューワーからcloudfrontの間には３種類の証明書を入れることが出来ます。</p>\n<p>１、ACM（AWS Certificate Manager）が提供する証明書</p>\n<p>２、信頼できるCAからの証明書（symantec）</p>\n<p>３、オレオレ証明書（自己署名証明書）</p>\n<p> </p>\n<h4>⑵ cloudfrontからオリジンの間</h4>\n<p>証明書をオリジンに入れることで、cloudfrontからオリジンの間のHTTPS通信が有効になります。</p>\n<p>cloudfrontからオリジンの間で使える証明書はオリジンが何であるかによって異なります。</p>\n<p>オリジンが ELBやEC2の場合：</p>\n<p> </p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>ビューアプロトコルポリシー</h3>\n<!-- /wp:heading -->\n\n<p>上記の⑴のビューワーとCloudFront間の通信が</p>\n<p>・HTTPまたはHTTPSにするか</p>\n<p>・HTTPSのみを使用するか</p>\n<p>・すべてのHTTPリクエストをHTTPSにリダイレクトする</p>\n<p>のかを定義するのが、このビューアープロトコルポリシーになります。</p>\n<p> </p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>練習問題</h3>\n<!-- /wp:heading -->\n\n<p>例題は３問。答えは最後にあります。</p>\n<p> </p>\n<p>例題１）</p>\n<p>ユーザーのブラウザから CloudFront 経由でエンドツーエンドの HTTPS 接続を有効にするには、以下のオプションのどれが有効ですか。（3 つの回答を選択)</p>\n<p> </p>\n<p>１、ビューワーはサードパーティCA 証明書を使用する。CloudFront は自己署名証明書を使用する</p>\n<p>２、ビューワーと CloudFront との間の HTTPS 通信でサードパーティの CA 証明書を使用する</p>\n<p>３、ビューワーと CloudFront との間の HTTPS 通信で自己署名証明書を使用します</p>\n<p>４、CloudFront とオリジンとの間の HTTPS 通信で自己署名証明書を使用します</p>\n<p>５、CloudFront とオリジンとの間の HTTPS 通信で自己署名証明書を使用します。(オリジンが ELB ロードバランサー (Amazon EC2 など) でない場合)</p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>答え：１、２、３</p>\n<p>解説：</p>\n<p> </p>\n<p> </p>\n<p>例題２）</p>\n<p>世界中で電気自動車を販売する自動化会社は、「自動操縦」機能とも呼ばれる半自動運転技術を備えた最新の自動車モデルをリリースします。新製品の人気のため、静的アセットのキャッシュにCloudFrontを使用して、世界中の視聴者への新しいモデルの画像やその他の静的コンテンツの配信を高速化することを計画しています。静的コンテンツは、独自のドメイン名を使用してHTTPS経由で配信する必要があります。これにより、Webサイトの訪問者はSSL接続で必要なセキュリティに加えて、遅延が少なく信頼性が高くなります。CloudFrontを使用してこのセットアップをAWSに実装するにはどうすればよいですか？（2つ選択）</p>\n<p> </p>\n<p>⑴ AWS Certificate Manager（ACM）に保存されているデフォルトのCloudFront証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑵ AWS Certificate Manager（ACM）に保存されているカスタムSSL証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑶ 署名付きCookieを使用してCloudFrontディストリビューションを作成します。 IAMに保存されているデフォルトのCloudFront証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑷ 署名付きURLを使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑸ IAMに保存されているカスタムSSL証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>答え：２、５</p>\n<p>解説：</p>\n<p> </p>\n<p>例題３）</p>\n<p> </p>\n\n<!-- wp:heading -->\n<h2>コンテンツを提供するユーザを限定する</h2>\n<!-- /wp:heading -->\n\n<p>問題でよくあるのが、特定の会員だけプライベートコンテンツを見せるにはどうしたらいいか？というもの。</p>\n<p>署名付きURL</p>\n<p>署名付きcookie</p>\n<p>OAI</p>\n<p>信頼できる署名者</p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>練習問題</h3>\n<!-- /wp:heading -->\n\n<p>例題１）</p>\n\n<!-- wp:heading -->\n<h2>キャッシュについて</h2>\n<!-- /wp:heading -->\n\n<p>ttlを０にする</p>\n<p>Cache-Control max-age</p>','AWS認定ソリューションアーキテクトプロフェッショナル-CloudFrontのまとめ','AWS 認定ソリューションアーキテクト – プロフェッショナルに出てくるcloudfrontの自分用のまとめです。','inherit','closed','closed','','2351-revision-v1','','','2019-10-02 12:28:29','2019-10-02 03:28:29','',2351,'http://localhost:8080/anothor/2351-revision-v1',0,'revision','',0),(2560,1,'2019-10-02 12:35:22','2019-10-02 03:35:22','<p>プロフェッショナルに出てくるcloudfrontはざっくり言うと以下の内容が多いんじゃないかなと思います。</p>\n<p>↓</p>\n<p>・ディストリビューション</p>\n<p>・HTTPS通信</p>\n<p>・コンテンツを提供するユーザを限定したい時</p>\n<p>・キャッシュ</p>\n<p>・DDos攻撃を防ぐ手段の一つとして</p>\n\n<!-- wp:heading -->\n<h2>ディストリビューション</h2>\n<!-- /wp:heading -->\n\n<p>Lambda @ Edge</p>\n<p>udemy2-56</p>\n\n<!-- wp:heading -->\n<h2>HTTPS通信</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>エンドツーエンドのHTTPS通信</h3>\n<!-- /wp:heading -->\n\n<p>エンドツーエンドと言うのは、端から端まで、つまりビューワーからオリジンまでを意味します。</p>\n<p>図</p>\n<p> </p>\n<p>エンドツーエンドHTTPS通信をするには、２つの証明書を適用する必要があります。</p>\n<p>⑴ ビューワーからcloudfront間</p>\n<p>⑵ cloudfrontからオリジンの間</p>\n<p> </p>\n<h4>⑴ ビューワーからcloudfront間</h4>\n<p>証明書をcloudfrontに入れることで、ビューワーからcloudfront間のHTTPS通信が有効になります。</p>\n<p>ビューワーからcloudfrontの間には３種類の証明書を入れることが出来ます。</p>\n<p>１、ACM（AWS Certificate Manager）が提供する証明書</p>\n<p>２、信頼できるCAからの証明書（symantec）</p>\n<p>３、オレオレ証明書（自己署名証明書）</p>\n<p> </p>\n<h4>⑵ cloudfrontからオリジンの間</h4>\n<p>証明書をオリジンに入れることで、cloudfrontからオリジンの間のHTTPS通信が有効になります。</p>\n<p>cloudfrontからオリジンの間で使える証明書はオリジンが何であるかによって異なります。</p>\n<p>オリジンが ELBやEC2の場合：</p>\n<p> </p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>ビューアプロトコルポリシー</h3>\n<!-- /wp:heading -->\n\n<p>上記の⑴のビューワーとCloudFront間の通信が</p>\n<p>・HTTPまたはHTTPSにするか</p>\n<p>・HTTPSのみにするか</p>\n<p>・すべてのHTTPリクエストをHTTPSにリダイレクトする</p>\n<p>のかを定義するのが、この<strong>「ビューアープロトコルポリシー」</strong>になります。</p>\n<p> </p>\n<p>具体的に定義する方法：</p>\n<p>１、CloudFrontディストリビューションを作成する</p>\n<p>２、ビューアープロトコルポリシーに以下の設定する</p>\n<p>・HTTPまたはHTTPSにする→<span style=\"color: #ff0000;\">HTTP and HTTPS</span></p>\n<p>・HTTPSのみにする→<span style=\"color: #ff0000;\">HTTPS only</span></p>\n<p>・すべてのHTTPリクエストをHTTPSにリダイレクトする→Redirect HTTP to HTTPS</p>\n<p> </p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>練習問題</h3>\n<!-- /wp:heading -->\n\n<p>例題は３問。答えは最後にあります。</p>\n<p> </p>\n<p>例題１）</p>\n<p>ユーザーのブラウザから CloudFront 経由でエンドツーエンドの HTTPS 接続を有効にするには、以下のオプションのどれが有効ですか。（3 つの回答を選択)</p>\n<p> </p>\n<p>１、ビューワーはサードパーティCA 証明書を使用する。CloudFront は自己署名証明書を使用する</p>\n<p>２、ビューワーと CloudFront との間の HTTPS 通信でサードパーティの CA 証明書を使用する</p>\n<p>３、ビューワーと CloudFront との間の HTTPS 通信で自己署名証明書を使用します</p>\n<p>４、CloudFront とオリジンとの間の HTTPS 通信で自己署名証明書を使用します</p>\n<p>５、CloudFront とオリジンとの間の HTTPS 通信で自己署名証明書を使用します。(オリジンが ELB ロードバランサー (Amazon EC2 など) でない場合)</p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>答え：１、２、３</p>\n<p>解説：</p>\n<p> </p>\n<p> </p>\n<p>例題２）</p>\n<p>世界中で電気自動車を販売する自動化会社は、「自動操縦」機能とも呼ばれる半自動運転技術を備えた最新の自動車モデルをリリースします。新製品の人気のため、静的アセットのキャッシュにCloudFrontを使用して、世界中の視聴者への新しいモデルの画像やその他の静的コンテンツの配信を高速化することを計画しています。静的コンテンツは、独自のドメイン名を使用してHTTPS経由で配信する必要があります。これにより、Webサイトの訪問者はSSL接続で必要なセキュリティに加えて、遅延が少なく信頼性が高くなります。CloudFrontを使用してこのセットアップをAWSに実装するにはどうすればよいですか？（2つ選択）</p>\n<p> </p>\n<p>⑴ AWS Certificate Manager（ACM）に保存されているデフォルトのCloudFront証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑵ AWS Certificate Manager（ACM）に保存されているカスタムSSL証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑶ 署名付きCookieを使用してCloudFrontディストリビューションを作成します。 IAMに保存されているデフォルトのCloudFront証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑷ 署名付きURLを使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑸ IAMに保存されているカスタムSSL証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>答え：２、５</p>\n<p>解説：</p>\n<p> </p>\n<p>例題３）</p>\n<p> </p>\n\n<!-- wp:heading -->\n<h2>コンテンツを提供するユーザを限定する</h2>\n<!-- /wp:heading -->\n\n<p>問題でよくあるのが、特定の会員だけプライベートコンテンツを見せるにはどうしたらいいか？というもの。</p>\n<p>署名付きURL</p>\n<p>署名付きcookie</p>\n<p>OAI</p>\n<p>信頼できる署名者</p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>練習問題</h3>\n<!-- /wp:heading -->\n\n<p>例題１）</p>\n\n<!-- wp:heading -->\n<h2>キャッシュについて</h2>\n<!-- /wp:heading -->\n\n<p>ttlを０にする</p>\n<p>Cache-Control max-age</p>','AWS認定ソリューションアーキテクトプロフェッショナル-CloudFrontのまとめ','AWS 認定ソリューションアーキテクト – プロフェッショナルに出てくるcloudfrontの自分用のまとめです。','inherit','closed','closed','','2351-revision-v1','','','2019-10-02 12:35:22','2019-10-02 03:35:22','',2351,'http://localhost:8080/anothor/2351-revision-v1',0,'revision','',0),(2562,1,'2019-10-02 13:14:10','2019-10-02 04:14:10','<p>プロフェッショナルに出てくるcloudfrontはざっくり言うと以下の内容が多いんじゃないかなと思います。</p>\n<p>↓</p>\n<p>・ディストリビューション</p>\n<p>・HTTPS通信</p>\n<p>・コンテンツを提供するユーザを限定したい時</p>\n<p>・キャッシュ</p>\n<p>・DDos攻撃を防ぐ手段の一つとして</p>\n\n<!-- wp:heading -->\n<h2>ディストリビューション</h2>\n<!-- /wp:heading -->\n\n<p>Lambda @ Edge</p>\n<p>udemy2-56</p>\n\n<!-- wp:heading -->\n<h2>HTTPS通信</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>エンドツーエンドのHTTPS通信</h3>\n<!-- /wp:heading -->\n\n<p>エンドツーエンドと言うのは、端から端まで、つまりビューワーからオリジンまでを意味します。</p>\n<p>図</p>\n<p> </p>\n<p>エンドツーエンドHTTPS通信をするには、２つの証明書を適用する必要があります。</p>\n<p>⑴ ビューワーからcloudfront間</p>\n<p>⑵ cloudfrontからオリジンの間</p>\n<p> </p>\n<h4>⑴ ビューワーからcloudfront間</h4>\n<p>証明書をcloudfrontに入れることで、ビューワーからcloudfront間のHTTPS通信が有効になります。</p>\n<p>ビューワーからcloudfrontの間には３種類の証明書を入れることが出来ます。</p>\n<p>１、ACM（AWS Certificate Manager）が提供する証明書</p>\n<p>２、信頼できるCAからの証明書（symantec）</p>\n<p>３、オレオレ証明書（自己署名証明書）</p>\n<p> </p>\n<h4>⑵ cloudfrontからオリジンの間</h4>\n<p>証明書をオリジンに入れることで、cloudfrontからオリジンの間のHTTPS通信が有効になります。</p>\n<p>cloudfrontからオリジンの間で使える証明書はオリジンが何であるかによって異なります。</p>\n<p>オリジンが ELBやEC2の場合：</p>\n<p> </p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>ビューアプロトコルポリシーとオリジンプロトコルポリシー</h3>\n<!-- /wp:heading -->\n\n<p>プロトコルポリシーとは、ざっくり言うとcloudfrontの通信をHTTPにするかHTTPSにするかを定義するものになります。</p>\n<p> </p>\n<p>上記の⑴のビューワーとCloudFront間のプロトコルを決めるのが<strong>「ビューアープロトコルポリシー」</strong></p>\n<p>⑵のcloudfrontからオリジンの間を決めるのが「<strong>オリジンプロトコルポリシー」</strong>になります。</p>\n<p> </p>\n<h4>ビューワープロトコルポリシー</h4>\n<p>ビューワープロトコルポリシーは</p>\n<p>・HTTPとHTTPSに両方使う</p>\n<p>・HTTPSのみにする</p>\n<p>・すべてのHTTPリクエストをHTTPSにリダイレクトする</p>\n<p> </p>\n<p>具体的に定義する方法：</p>\n<p>１、CloudFrontディストリビューションを作成する</p>\n<p>２、ビューアープロトコルポリシーに以下の設定する</p>\n<p>・HTTP＆HTTPSにする→<span style=\"color: #ff0000;\">HTTP and HTTPS</span></p>\n<p>・HTTPSのみにする→<span style=\"color: #ff0000;\">HTTPS only</span></p>\n<p>・すべてのHTTPリクエストをHTTPSにリダイレクトする→<span style=\"color: #ff0000;\">Redirect HTTP to HTTPS</span></p>\n<p> </p>\n<h4>オリジンプロトコルポリシー</h4>\n<p>オリジンプロトコルポリシーは、</p>\n<p> </p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>練習問題</h3>\n<!-- /wp:heading -->\n\n<p>例題は３問。</p>\n<p>例題１）</p>\n<p>ユーザーのブラウザから CloudFront 経由でエンドツーエンドの HTTPS 接続を有効にするには、以下のオプションのどれが有効ですか。（3 つの回答を選択)</p>\n<p> </p>\n<p>１、ビューワーはサードパーティCA 証明書を使用する。CloudFront は自己署名証明書を使用する</p>\n<p>２、ビューワーと CloudFront との間の HTTPS 通信でサードパーティの CA 証明書を使用する</p>\n<p>３、ビューワーと CloudFront との間の HTTPS 通信で自己署名証明書を使用します</p>\n<p>４、CloudFront とオリジンとの間の HTTPS 通信で自己署名証明書を使用します</p>\n<p>５、CloudFront とオリジンとの間の HTTPS 通信で自己署名証明書を使用します。(オリジンが ELB ロードバランサー (Amazon EC2 など) でない場合)</p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>答え：１、２、３</p>\n<p>解説：</p>\n<p> </p>\n<p> </p>\n<p>例題２）</p>\n<p>世界中で電気自動車を販売する自動化会社は、「自動操縦」機能とも呼ばれる半自動運転技術を備えた最新の自動車モデルをリリースします。新製品の人気のため、静的アセットのキャッシュにCloudFrontを使用して、世界中の視聴者への新しいモデルの画像やその他の静的コンテンツの配信を高速化することを計画しています。静的コンテンツは、独自のドメイン名を使用してHTTPS経由で配信する必要があります。これにより、Webサイトの訪問者はSSL接続で必要なセキュリティに加えて、遅延が少なく信頼性が高くなります。CloudFrontを使用してこのセットアップをAWSに実装するにはどうすればよいですか？（2つ選択）</p>\n<p> </p>\n<p>⑴ AWS Certificate Manager（ACM）に保存されているデフォルトのCloudFront証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑵ AWS Certificate Manager（ACM）に保存されているカスタムSSL証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑶ 署名付きCookieを使用してCloudFrontディストリビューションを作成します。 IAMに保存されているデフォルトのCloudFront証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑷ 署名付きURLを使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑸ IAMに保存されているカスタムSSL証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>答え：２、５</p>\n<p>解説：</p>\n<p> </p>\n<p>例題３）</p>\n<p> </p>\n\n<!-- wp:heading -->\n<h2>コンテンツを提供するユーザを限定する</h2>\n<!-- /wp:heading -->\n\n<p>問題でよくあるのが、特定の会員だけプライベートコンテンツを見せるにはどうしたらいいか？というもの。</p>\n<p>署名付きURL</p>\n<p>署名付きcookie</p>\n<p>OAI</p>\n<p> </p>\n<p>信頼できる署名者</p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>練習問題</h3>\n<!-- /wp:heading -->\n\n<p>例題１）</p>\n\n<!-- wp:heading -->\n<h2>キャッシュについて</h2>\n<!-- /wp:heading -->\n\n<p>ttlを０にする</p>\n<p>Cache-Control max-age</p>','AWS認定ソリューションアーキテクトプロフェッショナル-CloudFrontのまとめ','AWS 認定ソリューションアーキテクト – プロフェッショナルに出てくるcloudfrontの自分用のまとめです。','inherit','closed','closed','','2351-revision-v1','','','2019-10-02 13:14:10','2019-10-02 04:14:10','',2351,'http://localhost:8080/anothor/2351-revision-v1',0,'revision','',0),(2564,1,'2019-10-02 14:30:38','2019-10-02 05:30:38','<p>プロフェッショナルに出てくるcloudfrontはざっくり言うと以下の内容が多いんじゃないかなと思います。</p>\n<p>↓</p>\n<p>・ディストリビューション</p>\n<p>・HTTPS通信</p>\n<p>・コンテンツを提供するユーザを限定したい時</p>\n<p>・キャッシュ</p>\n<p>・DDos攻撃を防ぐ手段の一つとして</p>\n\n<!-- wp:heading -->\n<h2>ディストリビューション</h2>\n<!-- /wp:heading -->\n\n<p>Lambda @ Edge</p>\n<p>udemy2-56</p>\n\n<!-- wp:heading -->\n<h2>HTTPS通信</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>エンドツーエンドのHTTPS通信</h3>\n<!-- /wp:heading -->\n\n<p>エンドツーエンドと言うのは、端から端まで、つまりビューワーからオリジンまでを意味します。</p>\n<p>図</p>\n<p> </p>\n<p>エンドツーエンドHTTPS通信をするには、２つの証明書を適用する必要があります。</p>\n<p>⑴ ビューワーからcloudfront間</p>\n<p>⑵ cloudfrontからオリジンの間</p>\n<p> </p>\n<h4>⑴ ビューワーからcloudfront間</h4>\n<p>証明書をcloudfrontに入れることで、ビューワーからcloudfront間のHTTPS通信が有効になります。</p>\n<p>ビューワーからcloudfrontの間には３種類の証明書を入れることが出来ます。</p>\n<p>１、ACM（AWS Certificate Manager）が提供する証明書</p>\n<p>２、信頼できるCAからの証明書（symantec）</p>\n<p>３、オレオレ証明書（自己署名証明書）</p>\n<p> </p>\n<h4>⑵ cloudfrontからオリジンの間</h4>\n<p>証明書をオリジンに入れることで、cloudfrontからオリジンの間のHTTPS通信が有効になります。</p>\n<p>cloudfrontからオリジンの間で使える証明書はオリジンが何であるかによって異なります。</p>\n<p>オリジンが ELBやEC2の場合：</p>\n<p> </p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>ビューアプロトコルポリシーとオリジンプロトコルポリシー</h3>\n<!-- /wp:heading -->\n\n<p>プロトコルポリシーとは、ざっくり言うとcloudfrontの通信をHTTPにするかHTTPSにするかを定義するものになります。</p>\n<p> </p>\n<p>上記の⑴のビューワーとCloudFront間のプロトコルを決めるのが<strong>「ビューアープロトコルポリシー」</strong></p>\n<p>⑵のcloudfrontからオリジンの間を決めるのが「<strong>オリジンプロトコルポリシー」</strong>になります。</p>\n<p> </p>\n<h4>ビューワープロトコルポリシー</h4>\n<p>ビューワープロトコルポリシーは</p>\n<p>・HTTPとHTTPSに両方使う</p>\n<p>・HTTPSのみにする</p>\n<p>・すべてのHTTPリクエストをHTTPSにリダイレクトする</p>\n<p> </p>\n<p>具体的に定義する方法：</p>\n<p>１、CloudFrontディストリビューションを作成する</p>\n<p>２、ビューアープロトコルポリシーに以下の設定する</p>\n<p>・HTTP＆HTTPSにする→<span style=\"color: #ff0000;\">HTTP and HTTPS</span></p>\n<p>・HTTPSのみにする→<span style=\"color: #ff0000;\">HTTPS only</span></p>\n<p>・すべてのHTTPリクエストをHTTPSにリダイレクトする→<span style=\"color: #ff0000;\">Redirect HTTP to HTTPS</span></p>\n<p> </p>\n<h4>オリジンプロトコルポリシー</h4>\n<p>オリジンプロトコルポリシーは、</p>\n<p> </p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>練習問題</h3>\n<!-- /wp:heading -->\n\n<p>例題は３問。</p>\n<p>例題１）</p>\n<p>ユーザーのブラウザから CloudFront 経由でエンドツーエンドの HTTPS 接続を有効にするには、以下のオプションのどれが有効ですか。（3 つの回答を選択)</p>\n<p> </p>\n<p>１、ビューワーはサードパーティCA 証明書を使用する。CloudFront は自己署名証明書を使用する</p>\n<p>２、ビューワーと CloudFront との間の HTTPS 通信でサードパーティの CA 証明書を使用する</p>\n<p>３、ビューワーと CloudFront との間の HTTPS 通信で自己署名証明書を使用します</p>\n<p>４、CloudFront とオリジンとの間の HTTPS 通信で自己署名証明書を使用します</p>\n<p>５、CloudFront とオリジンとの間の HTTPS 通信で自己署名証明書を使用します。(オリジンが ELB ロードバランサー (Amazon EC2 など) でない場合)</p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>答え：１、２、３</p>\n<p>解説：</p>\n<p> </p>\n<p> </p>\n<p>例題２）</p>\n<p>世界中で電気自動車を販売する自動化会社は、「自動操縦」機能とも呼ばれる半自動運転技術を備えた最新の自動車モデルをリリースします。新製品の人気のため、静的アセットのキャッシュにCloudFrontを使用して、世界中の視聴者への新しいモデルの画像やその他の静的コンテンツの配信を高速化することを計画しています。静的コンテンツは、独自のドメイン名を使用してHTTPS経由で配信する必要があります。これにより、Webサイトの訪問者はSSL接続で必要なセキュリティに加えて、遅延が少なく信頼性が高くなります。CloudFrontを使用してこのセットアップをAWSに実装するにはどうすればよいですか？（2つ選択）</p>\n<p> </p>\n<p>⑴ AWS Certificate Manager（ACM）に保存されているデフォルトのCloudFront証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑵ AWS Certificate Manager（ACM）に保存されているカスタムSSL証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑶ 署名付きCookieを使用してCloudFrontディストリビューションを作成します。 IAMに保存されているデフォルトのCloudFront証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑷ 署名付きURLを使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑸ IAMに保存されているカスタムSSL証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p> </p>\n<p>答え：２、５</p>\n<p>解説：</p>\n<p> </p>\n<p>例題３）</p>\n<p> </p>\n\n<!-- wp:heading -->\n<h2>コンテンツを提供するユーザを限定する</h2>\n<!-- /wp:heading -->\n\n<p>問題でよくあるのが、特定の会員だけプライベートコンテンツを見せるにはどうしたらいいか？というもの。</p>\n<p> </p>\n<p>署名付きURL</p>\n<p>署名付きcookie</p>\n<p>OAI</p>\n<p> </p>\n<p>信頼できる署名者</p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>練習問題</h3>\n<!-- /wp:heading -->\n\n<p>例題１）</p>\n\n<!-- wp:heading -->\n<h2>キャッシュについて</h2>\n<!-- /wp:heading -->\n\n<p>ttlを０にする</p>\n<p>Cache-Control max-age</p>','AWS認定ソリューションアーキテクトプロフェッショナル-CloudFrontのまとめ','AWS 認定ソリューションアーキテクト – プロフェッショナルに出てくるcloudfrontの自分用のまとめです。','inherit','closed','closed','','2351-revision-v1','','','2019-10-02 14:30:38','2019-10-02 05:30:38','',2351,'http://localhost:8080/anothor/2351-revision-v1',0,'revision','',0),(2565,1,'2019-10-02 15:07:18','2019-10-02 06:07:18','<h2>このブログについて</h2>\nこのブログは筆者の個人用のメモとして使っております。\n<h2>かいてる人について</h2>\n・デザインが好きなインフラ/クラウドエンジニア。\n\n・イヌかネコかと言ったらネコ派。特にサバ白のスコティッシュフォールドやマンチカンがお気に入り。\n\n・電子工作、ミニチュアハウス製作、テラリウム作りなど、製作活動が好きでよくしてます。\n\n・あと、観葉植物を見てるのとスマホアプリの脱出ゲームもよくやってます。\n\n・文字を読んで内容を図に表したり、音楽を聞いてそれにあう風景をイメージするのが好きです。\n\n・絵心は皆無。\n<h2>持ってる資格</h2>\n・ 2019/08/12   AWS ソリューションアーキテクト　アソシエイト','Author','','inherit','closed','closed','','8-revision-v1','','','2019-10-02 15:07:18','2019-10-02 06:07:18','',8,'http://localhost:8080/anothor/8-revision-v1',0,'revision','',0),(2567,1,'2019-10-03 11:19:01','2019-10-03 02:19:01','<p>プロフェッショナルに出てくるcloudfrontはざっくり言うと以下の内容が多いんじゃないかなと思います。</p>\n<p>↓</p>\n<p>・ディストリビューション</p>\n<p>・HTTPS通信</p>\n<p>・コンテンツを提供するユーザを限定したい時</p>\n<p>・キャッシュ</p>\n<p>・DDos攻撃を防ぐ手段の一つとして</p>\n\n<!-- wp:heading -->\n<h2>ディストリビューション</h2>\n<!-- /wp:heading -->\n\n<p>Lambda @ Edge</p>\n<p>udemy2-56</p>\n\n<!-- wp:heading -->\n<h2>HTTPS通信</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>エンドツーエンドのHTTPS通信</h3>\n<!-- /wp:heading -->\n\n<p>エンドツーエンドと言うのは、端から端まで、つまりビューワーからオリジンまでを意味します。</p>\n<p>図</p>\n<p></p>\n<p>エンドツーエンドHTTPS通信をするには、２つの証明書を適用する必要があります。</p>\n<p>⑴ ビューワーからcloudfront間</p>\n<p>⑵ cloudfrontからオリジンの間</p>\n<p></p>\n<h4>⑴ ビューワーからcloudfront間</h4>\n<p>証明書をcloudfrontに入れることで、ビューワーからcloudfront間のHTTPS通信が有効になります。</p>\n<p>ビューワーからcloudfrontの間には３種類の証明書を入れることが出来ます。</p>\n<p>１、ACM（AWS Certificate Manager）が提供する証明書</p>\n<p>２、信頼できるCAからの証明書（symantec）</p>\n<p>３、オレオレ証明書（自己署名証明書）</p>\n<p></p>\n<h4>⑵ cloudfrontからオリジンの間</h4>\n<p>証明書をオリジンに入れることで、cloudfrontからオリジンの間のHTTPS通信が有効になります。</p>\n<p>cloudfrontからオリジンの間で使える証明書はオリジンが何であるかによって異なります。</p>\n<p>オリジンが ELBやEC2の場合：</p>\n<p></p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>ビューアプロトコルポリシーとオリジンプロトコルポリシー</h3>\n<!-- /wp:heading -->\n\n<p>プロトコルポリシーとは、ざっくり言うとcloudfrontの通信をHTTPにするかHTTPSにするかを定義するものになります。</p>\n<p></p>\n<p>上記の⑴のビューワーとCloudFront間のプロトコルを決めるのが<strong>「ビューアープロトコルポリシー」</strong></p>\n<p>⑵のcloudfrontからオリジンの間を決めるのが「<strong>オリジンプロトコルポリシー」</strong>になります。</p>\n<p></p>\n<h4>ビューワープロトコルポリシー</h4>\n<p>ビューワープロトコルポリシーは</p>\n<p>・HTTPとHTTPSに両方使う</p>\n<p>・HTTPSのみにする</p>\n<p>・すべてのHTTPリクエストをHTTPSにリダイレクトする</p>\n<p></p>\n<p>具体的に定義する方法：</p>\n<p>１、CloudFrontディストリビューションを作成する</p>\n<p>２、ビューアープロトコルポリシーに以下の設定する</p>\n<p>・HTTP＆HTTPSにする→<span style=\"color: #ff0000;\">HTTP and HTTPS</span></p>\n<p>・HTTPSのみにする→<span style=\"color: #ff0000;\">HTTPS only</span></p>\n<p>・すべてのHTTPリクエストをHTTPSにリダイレクトする→<span style=\"color: #ff0000;\">Redirect HTTP to HTTPS</span></p>\n<p></p>\n<h4>オリジンプロトコルポリシー</h4>\n<p>オリジンプロトコルポリシーは、</p>\n<p></p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>練習問題</h3>\n<!-- /wp:heading -->\n\n<p>例題は３問。</p>\n<p>例題１）</p>\n<p>ユーザーのブラウザから CloudFront 経由でエンドツーエンドの HTTPS 接続を有効にするには、以下のオプションのどれが有効ですか。（3 つの回答を選択)</p>\n<p></p>\n<p>１、ビューワーはサードパーティCA 証明書を使用する。CloudFront は自己署名証明書を使用する</p>\n<p>２、ビューワーと CloudFront との間の HTTPS 通信でサードパーティの CA 証明書を使用する</p>\n<p>３、ビューワーと CloudFront との間の HTTPS 通信で自己署名証明書を使用します</p>\n<p>４、CloudFront とオリジンとの間の HTTPS 通信で自己署名証明書を使用します</p>\n<p>５、CloudFront とオリジンとの間の HTTPS 通信で自己署名証明書を使用します。(オリジンが ELB ロードバランサー (Amazon EC2 など) でない場合)</p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p>答え：１、２、３</p>\n<p>解説：</p>\n<p></p>\n<p></p>\n<p>例題２）</p>\n<p>世界中で電気自動車を販売する自動化会社は、「自動操縦」機能とも呼ばれる半自動運転技術を備えた最新の自動車モデルをリリースします。新製品の人気のため、静的アセットのキャッシュにCloudFrontを使用して、世界中の視聴者への新しいモデルの画像やその他の静的コンテンツの配信を高速化することを計画しています。静的コンテンツは、独自のドメイン名を使用してHTTPS経由で配信する必要があります。これにより、Webサイトの訪問者はSSL接続で必要なセキュリティに加えて、遅延が少なく信頼性が高くなります。CloudFrontを使用してこのセットアップをAWSに実装するにはどうすればよいですか？（2つ選択）</p>\n<p></p>\n<p>⑴ AWS Certificate Manager（ACM）に保存されているデフォルトのCloudFront証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑵ AWS Certificate Manager（ACM）に保存されているカスタムSSL証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑶ 署名付きCookieを使用してCloudFrontディストリビューションを作成します。 IAMに保存されているデフォルトのCloudFront証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑷ 署名付きURLを使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑸ IAMに保存されているカスタムSSL証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p>答え：２、５</p>\n<p>解説：</p>\n<p></p>\n<p>例題３）</p>\n<p></p>\n\n<!-- wp:heading -->\n<h2>コンテンツを提供するユーザを限定する</h2>\n<!-- /wp:heading -->\n\n<p>問題でよくあるのが、特定の会員だけプライベートコンテンツを見せるにはどうしたらいいか？というもの。</p>\n<p></p>\n<p>署名付きURL</p>\n<p>署名付きcookie</p>\n<p>OAI</p>\n<p></p>\n<p>信頼できる署名者</p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>練習問題</h3>\n<!-- /wp:heading -->\n\n<p>例題１）</p>\n\n<!-- wp:heading -->\n<h2>キャッシュについて</h2>\n<!-- /wp:heading -->\n\n<p>ttlを０にする</p>\n<p>Cache-Control max-age</p>\n\n<!-- wp:heading -->\n<h2>DDos攻撃を防ぐ</h2>\n<!-- /wp:heading -->\n\n<p>別にDDos攻撃防止だけじゃなく、予期しないトラフィックの増加が見込まれる場合にもcloudfrontは使用されますが。</p>\n<p> </p>','AWS認定ソリューションアーキテクトプロフェッショナル-CloudFrontのまとめ','AWS 認定ソリューションアーキテクト – プロフェッショナルに出てくるcloudfrontの自分用のまとめです。','inherit','closed','closed','','2351-revision-v1','','','2019-10-03 11:19:01','2019-10-03 02:19:01','',2351,'http://localhost:8080/anothor/2351-revision-v1',0,'revision','',0),(2570,1,'2019-10-03 11:48:28','2019-10-03 02:48:28','<p>プロフェッショナルに出てくるcloudfrontはざっくり言うと以下の内容が多いんじゃないかなと思います。</p>\n<p>↓</p>\n<p>・ディストリビューション</p>\n<p>・HTTPS通信</p>\n<p>・コンテンツを提供するユーザを限定したい時</p>\n<p>・キャッシュ</p>\n<p>・DDos攻撃を防ぐ手段の一つとして</p>\n\n<!-- wp:heading -->\n<h2>ディストリビューション</h2>\n<!-- /wp:heading -->\n\n<p>Lambda @ Edge</p>\n<p>udemy2-56</p>\n\n<!-- wp:heading -->\n<h2>HTTPS通信</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3>エンドツーエンドのHTTPS通信</h3>\n<!-- /wp:heading -->\n\n<p>エンドツーエンドと言うのは、端から端まで、つまりビューワーからオリジンまでを意味します。</p>\n<p>図</p>\n<p> </p>\n<p>エンドツーエンドHTTPS通信をするには、２つの証明書を適用する必要があります。</p>\n<p>⑴ ビューワーからcloudfront間</p>\n<p>⑵ cloudfrontからオリジンの間</p>\n<p> </p>\n<h4>⑴ ビューワーからcloudfront間</h4>\n<p>証明書をcloudfrontに入れることで、ビューワーからcloudfront間のHTTPS通信が有効になります。</p>\n<p>ビューワーからcloudfrontの間には３種類の証明書を入れることが出来ます。</p>\n<p>１、ACM（AWS Certificate Manager）が提供する証明書</p>\n<p>２、信頼できるCAからの証明書（symantec）</p>\n<p>３、オレオレ証明書（自己署名証明書）</p>\n<p> </p>\n<h4>⑵ cloudfrontからオリジンの間</h4>\n<p>証明書をオリジンに入れることで、cloudfrontからオリジンの間のHTTPS通信が有効になります。</p>\n<p>cloudfrontからオリジンの間で使える証明書はオリジンが何であるかによって異なります。</p>\n<p>オリジンが ELBやEC2の場合：</p>\n<p> </p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>ビューアプロトコルポリシーとオリジンプロトコルポリシー</h3>\n<!-- /wp:heading -->\n\n<p>プロトコルポリシーとは、ざっくり言うとcloudfrontの通信をHTTPにするかHTTPSにするかを定義するものになります。</p>\n<p></p>\n<p>上記の⑴のビューワーとCloudFront間のプロトコルを決めるのが<strong>「ビューアープロトコルポリシー」</strong></p>\n<p>⑵のcloudfrontからオリジンの間を決めるのが「<strong>オリジンプロトコルポリシー」</strong>になります。</p>\n<p></p>\n<h4>ビューワープロトコルポリシー</h4>\n<p>ビューワープロトコルポリシーは</p>\n<p>・HTTPとHTTPSに両方使う</p>\n<p>・HTTPSのみにする</p>\n<p>・すべてのHTTPリクエストをHTTPSにリダイレクトする</p>\n<p></p>\n<p>具体的に定義する方法：</p>\n<p>１、CloudFrontディストリビューションを作成する</p>\n<p>２、ビューアープロトコルポリシーに以下の設定する</p>\n<p>・HTTP＆HTTPSにする→<span style=\"color: #ff0000;\">HTTP and HTTPS</span></p>\n<p>・HTTPSのみにする→<span style=\"color: #ff0000;\">HTTPS only</span></p>\n<p>・すべてのHTTPリクエストをHTTPSにリダイレクトする→<span style=\"color: #ff0000;\">Redirect HTTP to HTTPS</span></p>\n<p></p>\n<h4>オリジンプロトコルポリシー</h4>\n<p>オリジンプロトコルポリシーは、</p>\n<p></p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>練習問題</h3>\n<!-- /wp:heading -->\n\n<p>例題は３問。</p>\n<p>例題１）</p>\n<p>ユーザーのブラウザから CloudFront 経由でエンドツーエンドの HTTPS 接続を有効にするには、以下のオプションのどれが有効ですか。（3 つの回答を選択)</p>\n<p></p>\n<p>１、ビューワーはサードパーティCA 証明書を使用する。CloudFront は自己署名証明書を使用する</p>\n<p>２、ビューワーと CloudFront との間の HTTPS 通信でサードパーティの CA 証明書を使用する</p>\n<p>３、ビューワーと CloudFront との間の HTTPS 通信で自己署名証明書を使用します</p>\n<p>４、CloudFront とオリジンとの間の HTTPS 通信で自己署名証明書を使用します</p>\n<p>５、CloudFront とオリジンとの間の HTTPS 通信で自己署名証明書を使用します。(オリジンが ELB ロードバランサー (Amazon EC2 など) でない場合)</p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p>答え：１、２、３</p>\n<p>解説：</p>\n<p></p>\n<p></p>\n<p>例題２）</p>\n<p>世界中で電気自動車を販売する自動化会社は、「自動操縦」機能とも呼ばれる半自動運転技術を備えた最新の自動車モデルをリリースします。新製品の人気のため、静的アセットのキャッシュにCloudFrontを使用して、世界中の視聴者への新しいモデルの画像やその他の静的コンテンツの配信を高速化することを計画しています。静的コンテンツは、独自のドメイン名を使用してHTTPS経由で配信する必要があります。これにより、Webサイトの訪問者はSSL接続で必要なセキュリティに加えて、遅延が少なく信頼性が高くなります。CloudFrontを使用してこのセットアップをAWSに実装するにはどうすればよいですか？（2つ選択）</p>\n<p></p>\n<p>⑴ AWS Certificate Manager（ACM）に保存されているデフォルトのCloudFront証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑵ AWS Certificate Manager（ACM）に保存されているカスタムSSL証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑶ 署名付きCookieを使用してCloudFrontディストリビューションを作成します。 IAMに保存されているデフォルトのCloudFront証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑷ 署名付きURLを使用してCloudFrontディストリビューションを作成します。</p>\n<p>⑸ IAMに保存されているカスタムSSL証明書を使用してCloudFrontディストリビューションを作成します。</p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p></p>\n<p>答え：２、５</p>\n<p>解説：</p>\n<p></p>\n<p>例題３）</p>\n<p></p>\n\n<!-- wp:heading -->\n<h2>コンテンツを提供するユーザを限定する</h2>\n<!-- /wp:heading -->\n\n<p>問題でよくあるのが、特定の会員だけプライベートコンテンツを見せるにはどうしたらいいか？というもの。</p>\n<p></p>\n<p>署名付きURL</p>\n<p>署名付きcookie</p>\n<p>OAI</p>\n<p></p>\n<p>信頼できる署名者</p>\n\n<!-- wp:heading {\"level\":3} -->\n<h3>練習問題</h3>\n<!-- /wp:heading -->\n\n<p>例題１）</p>\n\n<!-- wp:heading -->\n<h2>キャッシュについて</h2>\n<!-- /wp:heading -->\n\n<p>ttlを０にする</p>\n<p>Cache-Control max-age</p>\n\n<!-- wp:heading -->\n<h2>DDos攻撃を防ぐ</h2>\n<!-- /wp:heading -->\n\n<p>別にDDos攻撃防止だけじゃなく、予期しないトラフィックの増加が見込まれる場合にもcloudfrontは使用されますが。</p>\n<p></p>','AWS認定ソリューションアーキテクトプロフェッショナル-CloudFrontのまとめ','AWS 認定ソリューションアーキテクト – プロフェッショナルに出てくるcloudfrontの自分用のまとめです。','inherit','closed','closed','','2351-autosave-v1','','','2019-10-03 11:48:28','2019-10-03 02:48:28','',2351,'http://localhost:8080/anothor/2351-autosave-v1',0,'revision','',0),(2612,1,'2026-02-23 16:21:42','0000-00-00 00:00:00','','自動下書き','','auto-draft','open','open','','','','','2026-02-23 16:21:42','0000-00-00 00:00:00','',0,'http://localhost:8080/?p=2612',0,'post','',0),(2613,1,'2026-02-23 16:22:17','2026-02-23 07:22:17','{\n    \"old_sidebars_widgets_data\": {\n        \"value\": {\n            \"sidebar-1\": [\n                \"search-2\",\n                \"recent-posts-2\",\n                \"recent-comments-2\",\n                \"archives-2\",\n                \"categories-2\",\n                \"meta-2\"\n            ],\n            \"wp_inactive_widgets\": [],\n            \"sidebar-widget12\": [\n                \"simple_ga_rankig-2\"\n            ],\n            \"sidebar-widget6\": [\n                \"nav_menu-4\"\n            ],\n            \"sidebar-widget5\": [\n                \"nav_menu-14\"\n            ],\n            \"sidebar-widget11\": [\n                \"nav_menu-5\"\n            ],\n            \"sidebar-widget9\": [\n                \"nav_menu-6\"\n            ],\n            \"sidebar-widget10\": [\n                \"nav_menu-2\"\n            ],\n            \"sidebar-widget1\": [\n                \"nav_menu-13\"\n            ],\n            \"sidebar-widget2\": [\n                \"nav_menu-7\"\n            ],\n            \"sidebar-widget7\": [\n                \"nav_menu-12\"\n            ],\n            \"sidebar-widget3\": [\n                \"nav_menu-11\"\n            ],\n            \"sidebar-widget4\": [],\n            \"sidebar-widget8\": [\n                \"tag_cloud-2\"\n            ],\n            \"footer_left\": [\n                \"nav_menu-10\"\n            ],\n            \"footer_center\": [\n                \"nav_menu-9\"\n            ],\n            \"footer_right\"